window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["30387358"]={"book":{"id":30387358,"title":"爆款写作课","author":" 弗兰克","translator":"","publisher":"中国友谊出版公司","pubdate":" 2018-11","isbn":"9787505745186","tags":["写作","新媒体","方法论   文案   学习方法   营销   职场"],"memCount":null},"np":1,"pb":[38],"idx":[{"i":19746,"t":"自我介绍之MTV法","l":"TF1-1","c":"艳子归来","g":1,"p":1},{"i":19478,"t":"让人印象深刻的自我介绍法则","l":"TF1-1","c":"博清","g":1,"p":1},{"i":19434,"t":"爆款写作课片段拆解“用正确的方式展示自己即用MTV三步法介绍自己”","l":"TF1-2","c":"穷查理","g":1,"p":1},{"i":19432,"t":"自我介绍之MTV法则","l":"TF1-1","c":"庆庆","g":1,"p":1},{"i":19384,"t":"高效鲜活立体的自我介绍——MTV","l":"TF1-1","c":"韧木","g":1,"p":1},{"i":19339,"t":"一招写出让人眼前一亮的自我介绍","l":"TF2-1","c":"丁大鹏","g":1,"p":1},{"i":19229,"t":"自我介绍","l":"TF1-2","c":"卓越影响者","g":1,"p":1},{"i":19064,"t":"MTV自我介绍","l":"TF1-2","c":"百万","g":1,"p":1},{"i":19021,"t":"自我介结的MTV法则","l":"TF1-1","c":"苏小暖","g":1,"p":1},{"i":18979,"t":"《爆款写作课》之MTV自我介绍法","l":"TF1-2","c":"深蓝～","g":1,"p":1},{"i":18675,"t":"MTV自我介绍法","l":"TF1-1","c":"李沐恩","g":1,"p":1},{"i":18191,"t":"如何让别人对你产生兴趣，而不是仅仅简单记住你","l":"TF1-1","c":"莫九","g":1,"p":1},{"i":18127,"t":"用MTV法介绍自己","l":"TF1-1","c":"刘君","g":1,"p":1},{"i":18086,"t":"MTV自我介绍法","l":"TF1-2","c":"louis0325","g":1,"p":1},{"i":17708,"t":"爆款写作课教会我如何用MTV法写出眼前一亮的自我介绍","l":"TF1-2","c":"Minch明奇","g":1,"p":1},{"i":17693,"t":"自我介绍","l":"TF1-1","c":"阅苏张庆磊","g":1,"p":1},{"i":17643,"t":"通过MTV法自我介绍，快速与人留下影响并建立链接","l":"TF1-2","c":"卓越影响者","g":1,"p":1},{"i":17517,"t":"MTV法介绍自己","l":"TF1-1","c":"李素芬","g":1,"p":1},{"i":17459,"t":"通过MTV法来介绍让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，然后让对方产生想与你链接的意愿。","l":"TF1-1","c":"拿鐵","g":1,"p":1},{"i":17368,"t":"让人印象深刻的自我介绍---MTV法则","l":"TF1-2","c":"田娟","g":1,"p":1},{"i":16826,"t":"晋级","l":"TF1-2","c":"黄艳","g":1,"p":1},{"i":16633,"t":"带着“自我介绍”来，收获“高效链接”的价值","l":"TF1-2","c":"莫愁","g":1,"p":1},{"i":16629,"t":"如何用MTV介绍法，加深第一印象，拓展与人深度连接机会","l":"TF1-2","c":"李丫丫","g":1,"p":1},{"i":16565,"t":"遇到矛盾时如何实现双方共赢","l":"TF3-3","c":"木木33","g":1,"p":1},{"i":16210,"t":"用MTV法介绍不一样的自己","l":"TF1-2","c":"看见的力量","g":1,"p":1},{"i":16063,"t":"MTV自我介绍法：只需3步，让人主动加你微信！","l":"TF2-1","c":"丁大鹏","g":1,"p":1},{"i":16036,"t":"爆款写作课","l":"TF1-2","c":"米岚","g":1,"p":1},{"i":16010,"t":"自我介绍-MTV法","l":"TF1-1","c":"雪荔","g":1,"p":1},{"i":15944,"t":"用MTV法做一分钟自我介绍","l":"TF1-1","c":"占春","g":1,"p":1},{"i":15688,"t":"自我介绍MTV法则","l":"TF1-2","c":"晨捷","g":1,"p":1},{"i":15617,"t":"MTV法介绍自己","l":"TF1-2","c":"小熊123","g":1,"p":1},{"i":15511,"t":"拆页主题:MTV法介绍自己","l":"TF1-2","c":"徐怡芳","g":1,"p":1},{"i":15351,"t":"MTV介绍法","l":"TF1-1","c":"无求乃乐","g":1,"p":1},{"i":14624,"t":"MTV法介绍自己","l":"TF1-1","c":"唐钰茹","g":1,"p":1},{"i":14473,"t":"爆款写作课","l":"TF1-1","c":"米老鼠vera","g":1,"p":1},{"i":14189,"t":"MTV法介绍自己","l":"TF1-2","c":"孙浩雄","g":1,"p":1},{"i":12952,"t":"\"MTV公式\"自我介绍，更好的展现自己。","l":"TF2-2","c":"解毒心肺","g":1,"p":1},{"i":11577,"t":"TF1-1过级","l":"TF1-1","c":"依哲","g":1,"p":1}],"ms":[{"id":19746,"topic":"自我介绍之MTV法","learn_goal":"","remark":"参与者学会MTV自我介绍法，能链接到更多人和资源","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"艳子归来","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>\u003cstrong>大家好，我叫陈艳，我是一名高中地理老师，非常高兴能和大家相聚于此，我相信我们到这里来的人，都是同频的人。能和同频的人一起学习，一起进步将是一件快乐无比的事情，所以我参加了拆书帮。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书帮是什么？拆书帮是一群热爱读书、热爱学习的青年组成的非盈利组织，全国各地每个分舵每周一次聚集在一起，用读书的形式赋能每一个人。是一个非常活跃的社群。拆书帮有什么成就事件？拆书帮能给你提供什么？一群和你志趣相投的伙伴和朋友，让你的情感有更多支持和链接；一次次思维碰撞，促进认知升级；一个个锻炼机会，促进表达、组织能力提升；一个个阅读的需要，培养终身阅读终身学习的习惯。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书是什么？拆书是适合成年人学习的方法，它有两种形式，一种是适合个人学习的便签拆书法，另一种是适合组织学习的现场学习法。拆书强调的不是记住知识，而是转化和内化，把图书中的知识转化成可以利用的方法，提升学习者的能力。拆书能给你提供什么？对知识更深刻更透彻的理解；将一个个知识转化成能力增长点；阅读的成果立马体现，让你的阅读更有动力。下面我们就一起来体验拆书的全过程吧！\u003c/strong>\u003c/p>","ratings_count":1,"texts":[{"id":24167,"quote":"\u003cp>【R1：原文片段】自我介绍之MTV法 来自《爆款写作课》\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。 \u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp> V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>  比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp> 1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp> 2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp> 当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>\u003cstrong>我看大部分伙伴都阅读完片段了，没有阅读完的也没有关系，接下来我们一起学习。MTV自我介绍法是一种自我介绍的方法。通过清晰、有条理地展现个人信息、成就事件和价值，有效地凸显个人核心竞争力。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>通过这样的介绍，听众可以迅速了解你的身份、成就和价值，从而增加他们对你的兴趣和信任，如果不这样介绍，你的介绍可能耗时长但是仍说不到重点，大家可能听过就忘了，不能快速建立你与他人的链接。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这样的介绍适合面试场合、社交活动、商务洽谈、线上线下社群及个人品牌塑造等场合。但如果你是走亲戚串门或者相亲什么的只关注情感链接的场合就不用这么介绍了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这个介绍方法主要是分三步介绍。第一步ME介绍你是谁，也就是你的基本信息：包括姓名、职业、教育背景等，还可以加入一些独特的标签或自我定位，如“行业专家”、“创新先锋”等，这些标签有助于听众快速了解你的专业领域或个性特点。第二步Thing介绍你的成就事件，列举2-3个具体、可量化的成就事件，这些事件应能够体现你的专业能力、创新思维或解决问题的能力。可以适当加些细节，会更有说服力。第三步VAlue介绍你能提供的价值，如方案制定、提供服务等。\u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>读了这个片段，我悔恨我没有早点读到这个片段，因为我今年9月刚调入一个新学校，在全校教职工大会上，我们所有新加入的老师被要求进行自我介绍，我们一共有40位新老师。我是怎么介绍的呢？就是我这次拆书开始那样自我介绍的？大家好，我叫陈艳，我是目前在高三，是一名地理老师，非常高兴能和大家相聚于此，短短几天的相处，我们学校给我一种温馨温暖的感觉，希望未来和大家一起奋斗。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>结果会议结束后，我们去食堂吃饭，我被老师们反复问到，你是新来的吧？你叫什么名字来着？你是教哪个科目的呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我知道我这次介绍是完全失败的，我让听众记住我是谁都没有记住，更何况是我的成就和我的价值更是一点没沾边。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>看到这个片段，我眼前一亮，原来自我介绍是有清晰的方法步骤的啊？原来我这么多年一直在抓瞎。赶紧来试试用这个方法，马上，我就用这个方法向大家重新介绍我吧\u003c/strong>\u003c/p>\u003cp>\u003cstrong>ME我是谁？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我是（没有沉鱼落雁之貌，但有沉鱼落雁之名）的陈艳，我是一名热爱教育事业，专注于研究班级管理和激发学生内驱力的高中地理教师，也是一位专注于提升孩子自我效能感的妈妈，还是一位自我管理的践行者。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Thing我的成就事件：①我被表彰为优秀班主任，四有好老师；②我的一节精品课被评为教育部优秀精品课；③最让我有成就感的事情是高一我上五个班的地理课，选课的时候5个班的同学都要求要选地理；④我毕业于北京师范大学，我是学习比较好的，通常面对这样的妈妈，孩子容易在学习上找不到成就感，但是我用主动示弱法提升了女儿的自我效能感，让她在学习上有信心有动力，她现在8岁，学习完全是她自己自主安排，而且名列前茅。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Value我能提供的：1.如果你是老师，我对老师的困境和解决方法有一些心得可以分享；2.如果你是家长，关于提升孩子的自我效能感我有一些方法可以探讨；3.如果你最近信心不足，我比较擅长鼓励人，可以和我聊聊；4.我是一个重视生命体验感的人，如果你有些有意思的活动缺一个搭子，非常希望你拉我入伙。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这样介绍下来是不是比最开始的介绍好多了呢？大家最近有没有需要自我介绍的场合呢？大家可以一试哟！非常欢迎大家私下联系我哟！感谢大家积极参与，也欢迎大家用便签写下对我的鼓励和建议意见等。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1772087473000,"updated_at":1775267546000,"ria":true},{"id":19478,"topic":"让人印象深刻的自我介绍法则","learn_goal":"","remark":"在跟随我完成本次RIA现场学习后，学习者可以学会给人留下好印象、避免“万能模板”尴尬的MTV自我简介法。\n【拆解书籍】《爆款写作课》的MTV自我简介法","level":"TF1-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"博清","city":"长治市"},"club":{"name":"长治上党分舵","city":"长治"},"prologue":"\u003cp>小伙伴们大家好，我是博清，本名高洋，本职工作是常村矿新闻中心的一名编辑。业余已经和心理学打了十年交道了、坚持每日冥想三年，算是半条“修行人”。\u003c/p>\u003cp>从2015年开始，我一边考心理咨询师证书，一边试着把心理学变成饭桌上的家常话：写公众号、上抖音、发小红书，这一走就是10年，说实话，翻车现场不少，但硬是把冷板凳坐成了长板凳。\u003c/p>\u003cp>但是，自朋当妈以后，生活确实成了主旋律，可每当我翻开书、打开笔记，那种“啊，这就是我最喜欢的自己”的感觉，就像在平凡日子里藏了颗薄荷糖——清清爽爽。所以，我来到了拆书帮，想在这里不断的回味这种甜蜜。\u003c/p>\u003cp>今天里，其实就想\u003cstrong>用十年心理学积累+平台运营经验+拆书帮的思维工具\u003c/strong>，和拆书帮的伙伴们一起探讨、一起冥想、一起把书里的金句变成生活里的\u003cstrong>烟火气\u003c/strong>。\u003c/p>\u003cp>因为我是一个拆书帮的新人，所以，接下来我想跟大家分享一下我理解的拆书帮，以便大家帮忙指正。\u003c/p>\u003cp>我觉得拆书最大的观念转变是：以学习者为核心的，而不是以知识为核心的。我像是一块吸铁石，把碎片化的知识吸附在我的身上；而不是我溶解到知识的海洋里，找不见自己。简单一句话，拆书是“知识怎么帮我解决问题”。\u003c/p>\u003cp>拆在这里就很好理解了，就是“转化和内化”为我的东西，为我所用。\u003c/p>\u003cp>【拆书法】\u003c/p>\u003cp>拆书法分为个人学习和现场培训两种形式。\u003c/p>\u003cp>个人学习法，其实就是便签读书法。用3张便签，在I便签上写下自己对原文的理解，A1便签上写下自己过往的经验，A2便签上写下自己未来如何应用。\u003c/p>\u003cp>而现场培训的拆书法，是更高级的、帮助别人把知识拆为已用。\u003c/p>\u003cp>【拆书帮】\u003c/p>\u003cp>就是咱们这帮学习的爱好者，互相学习、互相成长在一起的非营利性的组织；表现为各地的拆书帮分舵。\u003c/p>","ratings_count":1,"texts":[{"id":23859,"quote":"\u003cp>自我介绍之MTV法 来自《爆款写作课》\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>","explains":"\u003cp>大家看完之后，举手示意我一下。\u003c/p>\u003cp>【\u003cstrong>what\u003c/strong>】我今天给大家分享一个：可以给人留下好的第一印象的——MTV自我介绍法。其实就是一个自我介绍的方法，MTV是英文简称，后面我会给大家一一分解。\u003c/p>\u003cp>【\u003cstrong>why\u003c/strong>】不管是找工作、交朋友还是上课，一个靠谱的自我介绍就像你的“人设广告”，能让人一秒记住你、了解你的闪光点。而MTV自我介绍法，就是用最自然的方式，让人觉得觉得“这人挺有意思，能聊得来”，不自觉的让人对你“有印象、有好感、想靠近”。\u003c/p>\u003cp>【\u003cstrong>how\u003c/strong>】\u003cstrong>MTV自我介绍法一共分为4步：\u003c/strong>\u003c/p>\u003cp>1、确定目标受众\u003c/p>\u003cp>首先，你需要问自己一个问题：“我要把自己介绍给谁？”面对投资人时，你要突出解决问题的能力和商业价值；认识新朋友，我们要强调自己的性格特点和共同兴趣；来访者是家长，我们强调亲子关系和沟通；如果是年轻女性我们要分享个人提升和感情观点。\u003c/p>\u003cp>不同的场景和听众决定了你的表达方式，调整内容的侧重点，避免“万能模板”的尴尬。\u003c/p>\u003cp>2、准备介绍素材库\u003c/p>\u003cp>把自己想要介绍的内容罗列出来：学习经历、工作成就、性格标签、人生信条……\u003c/p>\u003cp>3、找到优势能力\u003c/p>\u003cp>问问自己：“哪些经历或技能能直接解决对方的痛点？” 从我们的素材库中找到自己的优势罗列出来。\u003c/p>\u003cp> 4、MTV模型的搭建\u003c/p>\u003cp>M：me-我是谁？用一句话概括你的身份和核心标签.\u003c/p>\u003cp>T：task-我的成就。这就需要我们从素材库里一条一条的找到对应的优势和能力。\u003c/p>\u003cp>V：value-价值，直接告诉对方，你认识我，我可以给你带来什么样的价值。\u003c/p>\u003cp>【\u003cstrong>where\u003c/strong>】这个方法是在我想把自己“推销出去”让大家有需求来找我的时候用到的。如果和家人聚会、朋友聚会，用这个方法反而显得很功利，拉远了彼此之间的距离。\u003c/p>","interaction":"\u003cp>接下来，分享一下我的A1便签，举一个自己的案例。\u003c/p>\u003cp>刚开始，原老师让我写一份自我简介，我罗列出来自己的两个标签交了上去。\u003c/p>\u003cp>大家好，我叫博清，本名高洋，是拆书帮的一名老会员、却是一位新选手。接下来，我简单的介绍一下我自己身上的两个标签：\u003c/p>\u003cp>第一个：编辑。我的本职工作是常村煤矿新闻中心的编辑，工作第一年就获得了“十佳编辑”的荣誉。因为工作的原因，公众号编辑、图片编辑、以及视频制作都是我的强项，我可以为大家提供专业化的帮助和制作。\u003c/p>\u003cp>第二个：心理老师。从2015年起到现在，我用10年的时间学习心理学的专业知识。经营和编辑了抖音、视频号和小红书三大平台的心理学家庭教育方向的视频内容；还有公众号个人成长方面的文字内容。\u003c/p>\u003cp>我有个希望，希望有一天可以成为一名足够专业、足够敬业的心理学方面的讲师。所以再一次来到了这里，希望脚踏实地走好这里的每一步。\u003c/p>\u003cp>但我看到MTV自我简介法之后，我发现我犯了三个错误：\u003c/p>\u003cp>1、\u003cstrong>没有明确目标受众\u003c/strong>\u003c/p>\u003cp>只顾着说“我是谁”，但完全没想“我说的这些，对谁有用”。\u003c/p>\u003cp>2、\u003cstrong>介绍素材单一，没有特色\u003c/strong>。最开始写自我介绍时，只聚焦在“专业评定”这一个维度。像性格、做事方式、人生信条这些内容都没有，所以整个介绍很干，没有温度，没有“活起来”的。\u003c/p>\u003cp>\u003cstrong>3、不是我觉得而是你觉得\u003c/strong>——我写的时候没意识到，优势不是自己觉得“我挺能干”，而是要让别人觉得“你能帮我解决问题”。\u003c/p>\u003cp>经过改正以后，就有了今天我跟大家做的自我介绍。\u003c/p>\u003cp>针对这次拆书帮过级，还有未来一些可能出现的场合，我重新制定了自我简介模板。\u003c/p>\u003cp>首先：丰富自己的素材库。不仅有专业评定、还加上性格特征、做事方式、人生信条等多个类别。让我的简介活起来，亲切一些。\u003c/p>\u003cp>其次：看明白受众群体是哪一类人。如果我是去讲课，要了解听众是什么类型的人，他们的职业是什么；如果在工作单位介绍自己，我的工作成果要展现出来；如果是认识新的朋友，那我的兴趣爱好、性格标签、人生信仰等等要和大家分享。\u003c/p>\u003cp>最后，在我写自己的价值时，要站在对方的角度，不是“我有什么”，而是我能“我能给予你什么”的角度来看写。\u003c/p>\u003cp>刚刚给大家分享了自我介绍的技巧，希望对大家有用！\u003c/p>\u003cp>我的分享到此结束，谢谢大家的聆听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1764300957000,"updated_at":1765509179000,"ria":true},{"id":19434,"topic":"爆款写作课片段拆解“用正确的方式展示自己即用MTV三步法介绍自己”","learn_goal":"","remark":"爆款写作课这本书中关于“用正确的方式展示自己即用MTV三步法介绍自己”片段拆解","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"穷查理","city":"银川市"},"club":{"name":"银川拉拉缨分舵","city":"银川"},"prologue":"\u003cp>\u003cstrong>请问观察家老师拿到观察家记录表、晋级准备表了吗？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请问现场的小伙伴都准备好了吗？\u003c/strong>\u003c/p>\u003cp> \u003cstrong>好，现在正式开始今天的拆解。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是张克南，在拆书帮的笔名是穷查理。用三个标签，介绍一下我自己，“支付行业老兵、篮球爱好者、终身学习者”。\u003c/p>\u003cp>【分组】由于今天有讨论/分享环节，人员不多，我们就不分组了，大家形成一个大组。\u003c/p>\u003cp> 今天与大家分享的拆页内容是“用正确的方式展示自己”即“用MTV 3步法介绍自己”，这个观点出自弗兰克的著作《爆款写作课》。\u003c/p>\u003cp>《爆款写作课》该书基于作者从职业经理人转型自媒体人的经验，面向新媒体写作场景，探讨文字传播与用户需求的系统性方法。这本书能帮助想要进行自媒体创作的小伙伴解决创作的难题，利用当下时代的红利，实现自我价值。\u003c/p>","ratings_count":1,"texts":[{"id":23806,"quote":"\u003cp>介绍完这本书，接下来请大家看一下原文拆页，3分钟的时间，看完了请举手示意一下。\u003c/p>\u003cp>\u003cstrong>《爆款写作课》P38-42页\u003c/strong>。“用正确的方式展示自己”即“用MTV 3步法介绍自己”\u003c/p>\u003cp>\u003cstrong>用正确的方式展示自己\u003c/strong>\u003c/p>\u003cp>我做了一个读者微信群，进群的朋友都会先发一个自我介绍。当一个读者进来之后，很多朋友都出来点赞。\u003c/p>\u003cp>她的自我介绍是这样写的：\u003c/p>\u003cp>姓名：××\u003c/p>\u003cp>城市：北京\u003c/p>\u003cp>职位：制片人\u003c/p>\u003cp>擅长的事：音乐&amp;影视内容的策划与制作\u003c/p>\u003cp>成就事件：\u003c/p>\u003cp>1.经营过一家唱片公司10年，担任过多位知名艺人的经纪人。\u003c/p>\u003cp>2.成功打造某音乐组合，4次登上央视春晚，获奖无数。\u003c/p>\u003cp>3.制作过两档电台节目，在全国120多家电台播出。\u003c/p>\u003cp>4.为谋求发展，出售唱片公司，转行成为院线电影独立制片人。\u003c/p>\u003cp>5.始终忠于内心，主动离婚两次，终觅自己想要的心灵伴侣。\u003c/p>\u003cp>想做的事：打造自己的知识付费产品，重视并建立个人品牌。\u003c/p>\u003cp>当这个姐姐做完自我介绍，有朋友说，看到大神的自我介绍，在此献上膝盖；有朋友说，厉害厉害，太厉害了；还有朋友说，姐姐好牛，想去你那里工作了。\u003c/p>\u003cp>面对陌生人，尝试梳理出自己最引以为豪的事情，节约对方的时间，吸引对方的注意力，产生连接的可能。\u003c/p>\u003cp>你可以尝试从学习、健身、工作或者理想等维度与其他人产生共鸣。\u003c/p>\u003cp>\u003cstrong>学习\u003c/strong>\u003c/p>\u003cp>一位朋友这样介绍：每年读纸质书20本，电子书50本，精读2～5本。另外一位朋友这样介绍：2017年11月至2018年2月初看了86本书并用思维导图输出。\u003c/p>\u003cp>一个妈妈这样介绍：宝宝一岁时，在职考取西南财经大学MBA，兼顾工作、带娃、学业，如今已顺利毕业。\u003c/p>\u003cp>\u003cstrong>健身\u003c/strong>\u003c/p>\u003cp>一个山西的朋友这样介绍：每天下班跑步5公里，坚持一个月，参加全马并完成比赛。\u003c/p>\u003cp>做自我介绍，其实就是一个做减法的过程，在过去的经历中，找到最亮点的成就事件，找到关键数据做支撑，然后尝试和对方连接。\u003c/p>\u003cp>\u003cstrong>用MTV 3步法介绍自己\u003c/strong>\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp> M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>好，我看到大家已经示意我看完拆页了，接下来我就分享一下我的理解和体会。\u003c/p>\u003cp>【\u003cstrong>what\u003c/strong>】MTV自我介绍法是一种结构化的自我介绍方法，通过三个步骤，清晰展示自己，快速与他人建立有效连接。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>传统的自我介绍没有亮点，难以让对方记住或产生信任。MTV自我介绍法通过你具体成就事件建立信任，并明确价值主张，让对方清晰了解“你能为我带来什么”，从而提升沟通效率，创造合作机会。\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>MTV自我介绍法的使用方法：\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>M（Me）：\u003c/strong>简要说明你是谁？比如：我是张克南，一名支付行业优秀运营经理；\u003c/p>\u003cp>\u003cstrong>2. \u003c/strong>\u003cstrong>T (Thing)：\u003c/strong>列举1-3个最亮眼的成就事件。比如：1.我曾多次参与省内多家银行支付产品洽谈合同，成功签约3年村镇银行的业务；2.我曾主导一个突发运营事件的运营解决，2个小时内把客户的损失降到最低。\u003c/p>\u003cp>\u003cstrong>3. V（Value）：\u003c/strong>明确你能提供的具体价值。比如：我可以帮你，1.快速定位产品问题，提升客户体验；2.精准分析运营数据，找到业务增长点等。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>MTV自我介绍法适用于快速展示个人价值的场景，比如大型行业交流会、读书会活动、正式面试等。\u003c/p>\u003cp>大家可以根据自己的场景，选择使用不同的自我介绍方法介绍自己。\u003c/p>","interaction":"\u003cp> 【\u003cstrong>A1\u003c/strong>】便签：\u003c/p>\u003cp> 我们学完了这个拆页，了解到了用正确的方式展示自己即MTV自我介绍法，现在请大家盘点一下，在过往的工作和生活中肯定经常要做自我介绍，你当时是怎么做的，包括背景、经过以及结果，可以是失败的经历也可以是成功的经历。\u003c/p>\u003cp>\u003cstrong>【现场指令】\u003c/strong>大家在组内轮流分享，4分钟后，我们结束小组分享并邀请1位伙伴与我们分享。\u003c/p>\u003cp> 好，时间到，下面我们请这位伙伴进行分享，大家欢迎。\u003c/p>\u003cp>\u003cstrong>（学习者案例记录）\u003c/strong>学员巧燕分享自己在部门培训时，自我介绍主要是以姓名，来自于哪个部门，负责具体的工作事项，有具体的哪些问题可以咨询她等方面进行介绍。\u003c/p>\u003cp>\u003cstrong>（反馈）\u003c/strong>好，非常感谢这位小伙伴的分享。\u003c/p>\u003cp>【\u003cstrong>A2\u003c/strong>】便签：\u003c/p>\u003cp>\u003cstrong>（拆书家提问设计）\u003c/strong>\u003c/p>\u003cp>好，非常感谢这位小伙伴的分享，接下来我们就规划一下，在下周，怎样运用今天学习的MTV自我介绍法介绍自己。\u003c/p>\u003cp>给大家2分钟的时间，把自己的目标和行动规划写到便签纸上。（大家可以用这个模板进行填空）：\u003c/p>\u003cp>我计划在\u003cstrong>\u003cu>未来一周内\u003c/u>\u003c/strong>【具体时间：____月____日至____月____日】，在\u003cu>什么场景\u003c/u>【具体场景，如：行业交流、读书会、个人面试等】中，运用MTV自我介绍法。\u003c/p>\u003cp>1. M（Me）：简要说明你是谁？\u003c/p>\u003cp>2. T(Thing)：列举1-3个最亮眼的成就事件\u003c/p>\u003cp>3. V（Value）：明确你能提供的具体价值\u003c/p>\u003cp>\u003cstrong>（学习者案例记录）\u003c/strong>\u003c/p>\u003cp>我计划在\u003cstrong>\u003cu>未来一周内\u003c/u>\u003c/strong>【具体时间：_11___月__17__日至__11__月_22___日】，在\u003cu>什员工培训 \u003c/u> 【具体场景，如：行业交流、读书会、个人面试等】中，运用MTV自我介绍法。\u003c/p>\u003cp>1. M（Me）：简要说明你是谁？\u003c/p>\u003cp> 我是马巧燕\u003c/p>\u003cp>2. T(Thing)：列举1-3个最亮眼的成就事件\u003c/p>\u003cp>1) 负责组织全行零售条线培训（包括新员工及管理者培训）\u003c/p>\u003cp>2) 会理解会合规会反洗钱会消保的全能银行人\u003c/p>\u003cp>3. V（Value）：明确你能提供的具体价值\u003c/p>\u003cp>a) 为您解答银行业务，处理金融培训相关问题\u003c/p>\u003cp>b) 优启教练，教你认识自己\u003c/p>\u003cp> 感谢小伙伴的分享。\u003c/p>\u003cp> 今天我的TF1-2拆书就到这里，感谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1763426808000,"updated_at":1763525565000,"ria":true},{"id":19432,"topic":"自我介绍之MTV法则","learn_goal":"","remark":"用“定标签+述成就+表价值”三步法，让“自我介绍”瞬间彰显价值","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"庆庆","city":""},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>1. 自我介绍：\u003c/p>\u003cp> 大家好，我是冯庆，是一名国企公办幼儿园的执行园长，也是一名家庭教育指导师，现在正在学习“拆书和演讲”，接下来的目标是成为一名“拆书家”和一个“会演讲”的教育人，帮助更多的家庭提供育儿指导，带领更多的老师实现专业成长；\u003c/p>\u003cp> 今天，非常荣幸来到我们武汉拆书帮珞珈分舵，参加TF1-1过级考核；我今天选的主题是：自我介绍之MTV法则，选自《爆款写作课》，目标是花10-15分钟时间让大家掌握用“定标签+述成就+表价值”三步法，做好一场值钱的自我介绍”，那在开始之前，我先带大家了解一下什么是“拆书”和“拆书帮”：\u003c/p>\u003cp>2、什么是拆书？什么是拆书帮？\u003c/p>\u003cp>拆书，顾名思义，就是把书中的内容和思想进行拆解，达到学以致用的作用。“拆书法”是成人学习的重要方式，这种方法强调以学习者为中心，而不是以追求知识为中心，这样就可以做到有目的、带着问题去进行阅读，并关联学习者的经验，规划出实践运用的过程。\u003c/p>\u003cp>“拆书”一般分为两种形式：“个人学习的拆书法”和“组织学习的拆书法”。个人学习的拆书法，我们运用的是“便签法”，通过三张便签，依次用自己的理解分别记录：原文思想—过往相关经验---目标行动计划，通过这种方式去阅读，可以实现阅读一本书就如同参加了“同主体培训”的效果；\u003c/p>\u003cp>组织学习的拆书法，是指一位拆书家拿出一本书加工出一场现场学习，引导和带领一群人拆为己用。从学习的效果来看，一位拆书家创造的价值是不亚于一位培训师的。\u003c/p>\u003cp>所谓“拆书帮”，也叫“拆书帮俱乐部”，它是一群“拆书法”学习爱好者自发组织的，主要表现为全国各地的非营利性拆书帮分舵，其使命是帮助更多的学习爱好者成为“拆书家”。\u003c/p>","ratings_count":1,"texts":[{"id":23803,"quote":"\u003cp>【R1：原文片段】自我介绍之MTV法 来自《爆款写作课》\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp> V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp> 比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp> 1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp> 2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>I便签：\u003c/p>\u003cp> 我们常常以为，一次好的自我介绍，就是把过去的成就说清楚，让人发出“哇”的赞叹。但现实是：别人听完后可能觉得你很厉害，却不知道你能为他做什么，于是听完后，也就忘记了。\u003c/p>\u003cp>一份优质的自我介绍，不仅能让对方快速记住自己，更能起到宣传自己、展示自己能提供给对方的价值，建立信任，让对方有需求时能第一时间选择自己，从而建立更多的“链接”。\u003c/p>\u003cp>《爆款写作课》提出的自我介绍“MTV”法则，非常完美地解决了这个问题，它不是一个炫技的工具，而是一个建立连接、传递价值的沟通框架。主要步骤如下：\u003c/p>\u003cp>1. M（Me）你是谁？： 这里需要用“姓名 + 标签”的方式定位身份（如我是XX，是一名阅读爱好者），标签要能让人一听就知道你是哪个领域的，最擅长什么！同时，设计标签时，还要考虑受众群体，如果你面对的是一群爱学习的人，那么这个标签就非常贴合，反之，如果面对的是一群爱打麻将的老太太，这个可能对她们就没有什么吸引力。\u003c/p>\u003cp>2. T（Thing）你做过最有成就的事情是什么？ ：围绕标签讲一件或几件真实、具体、有影响力的成就事件，作为你的“信任状”。（我有一套高效实用的阅读方法，通过这种方法，一年的实践我可以深度阅读50本书；），这个成就事件就是和标签相关联，能增强信任感，让别人了解你的优势和实战经验，构建信任。\u003c/p>\u003cp>3. V（Value）你能提供什么价值？：明确告诉对方你可以给听众能带来什么价值,越具体越好，如：“如果你有XX问题，可以找我解决！”（如果你想掌握高效阅读的方法，我可以分享给你！”），根据自己的标签和成就事件，来提炼自己的价值。\u003c/p>\u003cp>适用场景：\u003c/p>\u003cp>当你需要在短时间内建立专业形象时： \u003c/p>\u003cp>如会议开场、培训破冰、社群入群、演讲前暖场等； \u003c/p>\u003cp>当你想影响特定人群时： \u003c/p>\u003cp>如向他人传播理念、向同行分享经验、在学习型组织中建立影响力； \u003c/p>\u003cp>当你希望别人记住你并主动链接你时： \u003c/p>\u003cp>不只是留下印象，而是成为他们心中的“可求助对象”。\u003c/p>\u003cp>不适用场景：\u003c/p>\u003cp>时间极短或环境嘈杂（如聚餐、活动间隙），信息难以完整传达； \u003c/p>\u003cp>对方对你已有深入了解（如老同事、亲密伙伴），此时更需要情感交流而非价值陈列； \u003c/p>\u003cp>场合偏重仪式感或情感共鸣（如追思会、庆功宴），过度强调“我能为你做什么”会显得功利。\u003c/p>\u003cp>总结：MTV法则不是教你“包装自己”，而是教会你在有限时间内，坦诚地告诉别人：我是谁、我做过什么、我能帮你什么，从而让每一次自我介绍，都成为一次有价值的连接。\u003c/p>","interaction":"\u003cp>A1便签：\u003c/p>\u003cp> 作为幼儿园园长，在很多场合都需要做自我介绍，但以往我在做自我介绍时，仅仅只会说出自己的名字和过往经历，很少会谈及为他人能带来什么价值；比如，每学期我们有新员工加入时，都会有自我介绍环节，我一般是这样来介绍的：\u003c/p>\u003cp> 大家好，我叫冯庆！从事幼儿教育事业已经有十三年时间了，现在担任幼儿园园长，我非常喜欢孩子，也很喜欢阅读，欢迎新同事的加入，如果以后有什么困难随时可以找我！\u003c/p>\u003cp> 以上自我介绍，我讲了很多年，听起来亲切、热情，也表达了欢迎之意。但是对照MTV法则来看，显得很随意，不够专业；具体分析如下：\u003c/p>\u003cp>在M部分：基本是具备的，说了名字、职业和从业年限，不过在标签部分不够具体，可以在标签部分再显化一些，比如（专注于幼儿园特色课程打造、善于家园共育等）等，显示专业定位；\u003c/p>\u003cp>在T的部分：基本是缺失的，只说了从业的年限比较长，经验显得比较空泛，而且没有具体的成就事件举例，可以围绕标签定位描述具体的2-3个代表性案例，           \u003c/p>\u003cp> 最后在T的部分，也是模糊不清的，“有困难可以找我”看似开放，实则太笼统，新老师不知道你具体能帮什么，可以根据标签梳理2-3条可以给新老师提供的价值，如（如果你遇到带班难题、课程不知如何设计、或者在和家长沟通时遇到困难，都可以随时和我沟通！）\u003c/p>\u003cp>A2便签：\u003c/p>\u003cp>目标：在11月份初的一场招生活动上，使用“MTV”法则拟定的自我介绍进行开场，参加人数每次15组家庭，预计80%现场加微信，报名率60%以上；\u003c/p>\u003cp>过程：1.在10月初，完成“用MTV”法则设计的一份面对“意向家长”的自我介绍，\u003c/p>\u003cp>2.在10月中询熟练背诵，下旬进行模拟演练3次，11月份活动时正式使用。\u003c/p>\u003cp> 自我介绍设计具体如下：\u003c/p>\u003cp>（1）M(me）:你是谁？\u003c/p>\u003cp>大家好，我叫冯庆，是一名国企公办幼儿园的执行园长，同时也是一名家庭教育指导师。\u003c/p>\u003cp>（2）.T(ting):你做过的成就事件？\u003c/p>\u003cp>在过去的13年幼教职业生涯里，我走访了全国十多个城市，做过早教老师，也做过培训讲师，从一线老师到执行园长，变的是职位，不变的是我对幼儿教育事业的那份热爱！\u003c/p>\u003cp>这些年，我致力研究幼儿心理及亲子关系，先后带领几十名老师实现专业成长，将最前沿的教育理念带给幼儿园的孩子们；\u003c/p>\u003cp>此外，我也曾多次受邀前往各地开展育儿讲座，为数百个家庭提供过一对一的育儿指导，帮助他们走出带娃焦虑与困惑。在这个过程中，我也深深体的会到：科学的方法，真的可以改变一个家庭的氛围！\u003c/p>\u003cp>（3）V(Value):你能提供什么样的价值？\u003c/p>\u003cp>如果您正在经历：\u003c/p>\u003cp>孩子情绪难管、动不动就发脾气？ \u003c/p>\u003cp>亲子关系不好，沟通出现障碍？ \u003c/p>\u003cp>面对各种理念的幼儿园，不知如何选择？\u003c/p>\u003cp>欢迎加我微信\u003c/p>\u003cp>我不一定是专家，但我愿意分享真实的实战经验\u003c/p>\u003cp>认识我，让您养娃不焦虑； \u003c/p>\u003cp>链接我，让教育更有温度!\u003c/p>\u003cp>谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1763375526000,"updated_at":1764542615000,"ria":true},{"id":19384,"topic":"高效鲜活立体的自我介绍——MTV","learn_goal":"","remark":"开展自我介绍的有效方法——MTV","level":"TF1-1","duration":18,"status":30,"type":0,"chaishujia":{"username":"韧木","city":"衡水市"},"club":{"name":"廊坊风陵分舵","city":"廊坊"},"prologue":"\u003ch2>\u003cstrong>高效鲜活立体的自我介绍——MTV\u003c/strong>\u003c/h2>\u003cp>高效鲜活立体的自我介绍——MTV自我介绍法\u003c/p>\u003cp>开场：\u003c/p>\u003cp>一、自我介绍（1分钟）\u003c/p>\u003cp> 大家好，我是廊坊风陵分舵的韧木。首先介绍一下我自己，用拆书帮内部通用的自我介绍法——三个标签。我的三个标签是：高校教师、健身教练、考试达人。高校教师是我的主业，也是我一直以来的梦想职业（相比异地乡镇公务员钱多事少离家近）；我兼职肚皮舞教练两年，腰腹操教练三年。考公考编考研，四次笔试第一，四次裸考上岸，拥有记者证、教师证、教练证三个证书。虽然不算学霸，但身边人都管我叫考神附体的考霸。如果大家想了解一些高校教师的工作生活，想练马甲线，想了解一些应试技巧和做题节奏，都可以来找我聊聊。\u003c/p>\u003cp>下面进入我的五个主题分享\u003c/p>\u003cp>二、拆书帮介绍（2分钟）\u003c/p>\u003cp> 我想简单介绍一下拆书帮。先从定义开始，“拆书”的拆不是“拆散”，是转化和内化。拆书，就是强调把图书的知识拆页转化为学习者的能力。“拆书”分两种，一种是个人学习的拆书法，让我们运用RIA便签法，看一本书就能达到听一场培训的效果；另外一种是组织学习的拆书法，是一个拆书家把一本书加工成一场现场学习训练，引导和促进一群人把知识拆为己用，就像我现在和以后要做的一样。“拆书帮”主要表现方式就是各地的拆书分舵。拆书分舵是一个学习爱好者的社群，大家互相帮助赋能成长，我们的目标是成长为拆书家，培养三级拆书家！ \u003c/p>\u003cp>R原文片段：\u003c/p>\u003cp>\u003cstrong>三、【R】阅读原书拆页（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong> &lt;*技能点：拆页内容未超过2页图书内页。【R】所选拆页包含有具体行动或做法。*&gt;\u003c/strong>\u003c/p>\u003cp> 下面给大家阅读一下，大家自行思考。\u003c/p>\u003cp> 今天的拆页是《爆款写作课》里的自我介绍之MTV法。\u003c/p>\u003cp> “梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp> 这里我要向你介绍一个做自我介绍地工具，MTV法则。M是英文单词Me的缩写，意思是你是谁？T是英文单词Ting的缩写，意思是你做过什么成就事件？V是单词Value的缩写，意思是你能提供什么价值？ \u003c/p>\u003cp> 这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp> 当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。” \u003c/p>\u003cp> 看小品图片便于记忆MTV，此MTV非彼MTV。\u003c/p>\u003cp>\u003cstrong>四、【I】拆书家当众表达I便签（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong> &lt;*技能点：【I】便签用自己的话重述原文知识点，清晰易懂。*&gt;\u003c/strong>\u003c/p>\u003cp>读完原文，我来用自己的语言阐述一下这段话的内涵，这就是我们的I便签。\u003c/p>\u003cp>WHAT：这个片段讲了一个重要方法，我们可以用这种方法来进行自我介绍。M就是E，它的意思是代表我是谁，T就是英文thing的缩写，代表的是我有什么值得骄傲的成就。V就是value，就是我能不能给别人带来什么价值。 \u003c/p>\u003cp>WHY：每当我们去到一个新的环境，或者换了新的工作，或者认识了新的人，那么自我介绍就是十分重要的，但是往往我们会感觉自己无话可说。通过这个方法我们就知道怎么样更快的跟对方拉近关系，产生链接。\u003c/p>\u003cp>HOW：那我们怎样运用这个进行自我介绍呢？我认为是三步。第一个M就是me，你要先介绍自己的名字，然后自己身上所代表的标签。比如说你的职业，你的兼职，你的优势。（列标签）第二就是简单的说一下自己觉得最有成就的事情，最有自豪感的事情。（谈成就）最后一步就是V很关键的一步，就是你要让别人明白你能给他提供的价值，就比如说你的职业事业，你擅长专业的事，你可以为大家做什么？（聊价值）\u003c/p>\u003cp>WHERE：MTV自我介绍法适用于我们讲讲课，或者说做宣讲，或者做一个培训的开场白。适用于我们认识一个新的朋友，适用于我们来到了一个陌生的新的环境，便于让大家更快的了解我们自己，对我们产生兴趣。\u003c/p>\u003cp>\u003cstrong>五、【A1】拆书家当众表达A1便签（3分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&lt;*技能点：【A1】便签给到至少一个自己的具体案例，可以是作证知识点有用的正面案例，也可以是自己之前没能做到所以效果不好的反面例子。\u003c/strong>*&gt;\u003c/p>\u003cp> 就在十一假期之前，9月30号，我们社科部开了一个会。其中一项内容就是新老师进行自我介绍。作为一名新老师，我站起来的一瞬间大脑一片空白，突然不知道该怎么介绍自己了，听到前一位老师就只说了自己叫什么，我也只说了自己名字，我说我叫段藤藤，然后就坐下了。结果那些老教师们面面相觑，也没什么反应。书记当时也脸色阴沉，气氛变得十分古怪，瞬间冷场了。我自己也觉得很尴尬，因为我虽然是个新老师，毕竟自己也是职场老人了，不该在自我介绍中这么敷衍。当时错过了一个很好的让人认识自己记住自己对自己产生兴趣的机会，既没有亮出自己的标签，又没有分享有成就感的事情，更没有展示自己的价值。这样最终导致的结果是别人对我不认识不感兴趣，没有有效建立起与他人的连接。这让我觉得十分后悔和惋惜。\u003c/p>\u003cp>\u003cstrong>六、【A2】拆书家当众表达A2便签（2分钟）\u003c/strong>\u003c/p>\u003cp> &lt;*技能点：【A2】便签规划对知识的具体运用，听起来够清晰，能执行。*&gt;\u003c/p>\u003cp>我计划定一个可行的目标。在下周二给我学生上课时用MTV自我介绍法对我的学生们好好介绍一下我自己。先说自己的名字，自己的标签，你们的德法课教师、考公达人。再简要说一下自己的成就，主要是跟学生们息息相关的考试经历，三次考公考编笔试第一上岸，考研裸考上岸，三个证书裸考通过。最后强调自己能提供给他们的价值，我的裸考经历——可以快速找到课程重点，带学生们轻轻松松通过德法考试。如果我能应用MTV自我介绍法，就奖励自己吃顿火锅。 \u003c/p>\u003cp>最后，简单总结一下，我们今天主要学习了一个高效鲜活立体的自我介绍方法——MTV自我介绍法，它的三个要素是：列标签、聊成就、谈价值。期望大家谨记，并能在以后工作生活中真正用起来，给人良好的第一印象。\u003c/p>\u003cp> 我的分享完毕，谢谢大家！\u003c/p>\u003cp> 总时长：12-17分钟\u003c/p>\u003cp> &lt;*技能点：总时长没有少于12分钟，没有超过17分钟 *&gt;\u003c/p>","ratings_count":1,"texts":[{"id":23751,"quote":"\u003cp> 今天的拆页是《爆款写作课》里的自我介绍之MTV法。\u003c/p>\u003cp> “梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp> 这里我要向你介绍一个做自我介绍地工具，MTV法则。M是英文单词Me的缩写，意思是你是谁？T是英文单词Ting的缩写，意思是你做过什么成就事件？V是单词Value的缩写，意思是你能提供什么价值？ \u003c/p>\u003cp> 这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp> 当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。” \u003c/p>","explains":"\u003cp>WHAT：这个片段讲了一个重要方法，我们可以用这种方法来进行自我介绍。M就是E，它的意思是代表我是谁，T就是英文thing的缩写，代表的是我有什么值得骄傲的成就。V就是value，就是我能不能给别人带来什么价值。 \u003c/p>\u003cp>WHY：每当我们去到一个新的环境，或者换了新的工作，或者认识了新的人，那么自我介绍就是十分重要的，但是往往我们会感觉自己无话可说。通过这个方法我们就知道怎么样更快的跟对方拉近关系，产生链接。\u003c/p>\u003cp>HOW：那我们怎样运用这个进行自我介绍呢？我认为是三步。第一个M就是me，你要先介绍自己的名字，然后自己身上所代表的标签。比如说你的职业，你的兼职，你的优势。（列标签）第二就是简单的说一下自己觉得最有成就的事情，最有自豪感的事情。（谈成就）最后一步就是V很关键的一步，就是你要让别人明白你能给他提供的价值，就比如说你的职业事业，你擅长专业的事，你可以为大家做什么？（聊价值）\u003c/p>\u003cp>WHERE：MTV自我介绍法适用于我们讲讲课，或者说做宣讲，或者做一个培训的开场白。适用于我们认识一个新的朋友，适用于我们来到了一个陌生的新的环境，便于让大家更快的了解我们自己，对我们产生兴趣。\u003c/p>","interaction":"\u003cp>A1： 就在十一假期之前，9月30号，我们社科部开了一个会。其中一项内容就是新老师进行自我介绍。作为一名新老师，我站起来的一瞬间大脑一片空白，突然不知道该怎么介绍自己了，听到前一位老师就只说了自己叫什么，我也只说了自己名字，我说我叫段藤藤，然后就坐下了。结果那些老教师们面面相觑，也没什么反应。书记当时也脸色阴沉，气氛变得十分古怪，瞬间冷场了。我自己也觉得很尴尬，因为我虽然是个新老师，毕竟自己也是职场老人了，不该在自我介绍中这么敷衍。当时错过了一个很好的让人认识自己记住自己对自己产生兴趣的机会，既没有亮出自己的标签，又没有分享有成就感的事情，更没有展示自己的价值。这样最终导致的结果是别人对我不认识不感兴趣，没有有效建立起与他人的连接。这让我觉得十分后悔和惋惜。\u003c/p>\u003cp>A2：我计划定一个可行的目标。在下周二给我学生上课时用MTV自我介绍法对我的学生们好好介绍一下我自己。先说自己的名字，自己的标签，你们的德法课教师、考公达人。再简要说一下自己的成就，主要是跟学生们息息相关的考试经历，三次考公考编笔试第一上岸，考研裸考上岸，三个证书裸考通过。最后强调自己能提供给他们的价值，我的裸考经历——可以快速找到课程重点，带学生们轻轻松松通过德法考试。如果我能应用MTV自我介绍法，就奖励自己吃顿火锅。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1761226435000,"updated_at":1761272750000,"ria":true},{"id":19339,"topic":"一招写出让人眼前一亮的自我介绍","learn_goal":"","remark":"如何用简单的方法写出让人愿意和你产生链接的自我介绍","level":"TF2-1","duration":60,"status":30,"type":0,"chaishujia":{"username":"丁大鹏","city":""},"club":{"name":"广州大湾区分舵","city":"广州"},"prologue":"\u003cp>【学习目标】在学习完片段的方法后，学习者能写出一个符合MTV自我介绍法特征的自我介绍。\u003c/p>\u003cp>【开场白】大家好，我是丁大鹏，大鹏展翅的大鹏，我有3个标签，分别是：注册监理工程师，一级拆书家和终身学习者。今天分享的主题是：MTV自我介绍法，让对方更想了解你。\u003c/p>\u003cp>【Feature特点】这个方法来自于《爆款写作课》这本书，他的作者叫弗兰克，是一名世界500强的职业经理人，这本书是他从零开始学写作，到不断写出10W+的爆款文案中，总结出来的方法、技巧与实战案例的集合。\u003c/p>\u003cp>【Advantage优势】里面包含了作者总结出的吸引、打动、说服3步法，和3大成功案例，以及在此基础上拆解出的11种爆款文案写作技巧，然后用了128个实战演练来讲解与说明，相对于市面上的同类书籍来说，讲解更细致，实操性也更强。\u003c/p>\u003cp>【Benefit利益】如果你是写作小白，想要更快地入门，那么这本书需要你认真阅读，如果你是写作老手，想要突破写作瓶颈，也可以随时拿出来翻一翻。而我们今天拆页中的方法，则可以让你在做自我介绍时，让别人更快地认识你、记住你、甚至了解你。怎样才能做到这一点呢？\u003c/p>\u003cp>【过渡】请大家花1-2分钟时间来读一下我们的片段。读完的小伙伴也请抬头示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":23700,"quote":"\u003cp>片段来源《爆款写作课》P67-69   \u003c/p>\u003cp>1.3. 学习写作，写出眼前一亮的自我介绍\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>【过渡】大家可以回想一下，你平时见过最多的自我介绍是怎样的？\u003c/p>\u003cp>\u003cstrong>&lt;一般人的做法&gt;\u003c/strong>我是谁？来自哪儿？做过什么工作？有什么兴趣爱好。然后就没有然后了。\u003c/p>\u003cp>\u003cstrong>&lt;一般做法的坏处&gt;\u003c/strong>在人少的时候这样做完全没问题，一旦人多，别人转头可能就把你给忘了，更别说产生链接了，除非对方本来就对你很感兴趣。\u003c/p>\u003cp>\u003cstrong>&lt;反面案例&gt;\u003c/strong>比如我去参加一个大厂的面试，HR每天要面试几十上百人，如果我只是介绍说我叫丁大鹏，是一名注册监理工程师，在恒大做过飞检，在中海做过项目管理等等，估计对方转头就把我的简历给扔进垃圾桶里了。\u003c/p>\u003cp>（Why）为什么会这样？因为对方不清楚我的飞检、项目管理具体做的是什么。更加不明白我做过的事情能给他带来什么价值。\u003c/p>\u003cp>（What）而这个片段告诉我们，不止要告诉对方我是谁，还要把我们做过的具体事项罗列出来，并且总结性地告诉对方，我们做过的这些事情可以给对方带来什么帮助？\u003c/p>\u003cp>（How）具体要怎么做呢？用MTV自我介绍法，分3步搞定：\u003c/p>\u003cp>第一步、告诉对方我是谁，也就是Me。比如我叫丁大鹏，这里可以加上我的标签注册监理工程师。\u003c/p>\u003cp>第二步、告诉对方我做过哪些事情，也就是Things。比如我在恒大做过飞检，这里需要告诉对方具体做了哪些事，比如飞检包括制定每个月的抽检计划，以及确定检查项目，在检查的过程中发现问题，并提出解决方案等等。\u003c/p>\u003cp>第三步、告诉对方我做过的事情，能给对方带来什么价值。也就是Value。比如我的工作经历可以帮助对方优化工作流程，以提高10%-20%的工作效率。这里是总结前面工作后得出的结论。\u003c/p>\u003cp>\u003cstrong>&lt;正面案例&gt;\u003c/strong> 最后我的MTV自我介绍就是这样的。\u003c/p>\u003cp>Me：你好！我叫丁大鹏，是一名注册监理工程师。\u003c/p>\u003cp>Things：以前在恒大做过飞检，其主要包括制定每个月的抽检计划，以及确定检查项目，在检查的过程中发现问题，并提出解决方案等。\u003c/p>\u003cp>Value：以上的工作经历可以起到优化工作流程的作用，帮贵公司提高10%-20%的工作效率。\u003c/p>\u003cp>（Where）这个方法主要适用于你想让对方了解你，甚至和你产生链接的情况，除了面试还可以用在单身交友，或者想要认识某位大咖等等场景。记住，针对不同的场合，我们需要准备不同版本的MTV自我介绍。当然如果你只想做个小透明，那随便介绍一下自己也是可以的。\u003c/p>","interaction":"\u003cp>\u003cstrong>&lt;A1&gt;&lt;显像提问&gt;\u003c/strong>请大家回想一下，最近一周或者一个月时间内，你有没有遇到过这样的场合，你想要让某人了解你，于是热情地过去打招呼，做了自我介绍，结果对方只是应付两下就完了。比如在某个行业交流会上，你遇到可以拓展业务的客户，或者在某次单身交友活动上发现了心动的他。当然也可以是自我介绍后，对方表示对你很感兴趣的情况，请用1分钟时间来回忆一下，你当时是怎么做的？然后请一位朋友来分享一下。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>分享者游鸿志：\u003c/p>\u003cp>我去年参加广东省安全生产文化分享会，遇到一个大咖讲课非常好，于是想和他产生连接，本来准备等他分享完后就去找他，但他因为讲课时间很赶，加上自己的犹豫，觉得自己没法给对方提供什么价值，结果就错过了这次机会。\u003c/p>\u003cp>【答疑】我们很多时候之所以错过机会，主要有3个原因，①是我们没有提前做准备，②是觉得自己没有什么成就事件，③是觉得自己做的事情没法给对方带来价值，这也是最大的问题。然而现实情况并不是这样的，就拿这件事情来说，哪怕是我们记录下大咖的分享，然后向对方提几个问题，也是对他有帮助的，这就是在给他反馈。\u003c/p>\u003cp>\u003cstrong>&lt;A1+&gt;\u003c/strong>那么下面请大家想一想，你可以怎样把我们今天学过的MTV自我介绍法和刚才的自我介绍结合起来，从新做一个全新的自我介绍？关于Me，你会怎么说？关于Things，会包含哪些你做过的事情？关于Value，这些事情可以给对方带来什么价值？ 请大家花1分钟来思考一下，然后我会请人来分享。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>分享者王美惠：\u003c/p>\u003cp>M：我叫王美惠，是一名美业从业者。T：从业12年做过上百场线上线下培训。V：能帮助大家改善亚健康、皮肤问题和身材问题。有需要可以联系我。\u003c/p>\u003cp>\u003cstrong>&lt;一句话总结&gt;\u003c/strong>感谢美惠的分享，她做了一个完美的MTV自我介绍，最后我想大家应该都听过这样一句话，真诚的友谊来自不断地自我介绍。这个真诚不自在于你，也不在于我，而在于我做过哪些事情，能给你带来什么价值，最终实现价值的匹配，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1758855265000,"updated_at":1762833283000,"ria":true},{"id":19229,"topic":"自我介绍","learn_goal":"","remark":"通过MTV法自我介绍，快速与人留下影响并建立链接","level":"TF1-2","duration":23,"status":30,"type":0,"chaishujia":{"username":"卓越影响者","city":"广州"},"club":{"name":"广州大湾区分舵","city":"广州"},"prologue":"\u003cp>\u003cstrong>【自我介绍】1分钟\u003c/strong>\u003c/p>\u003cp>    大家好，接下来是进行我1-2的拆书，我拆书的主题是爆款写作法——MTV介绍法。 \u003c/p>\u003cp> 三个标签自我介绍一下，我叫李东华， 有时候我会介绍是三个武侠高手。但是有时候我会简单的介绍， 如果有看过三生三世十里桃花，都知道里面有个东华帝君，所以其实很多人也会叫我东华帝君，也有人简称我帝君。 所以我的头像也是东华帝君，\u003c/p>\u003cp> 我有\u003cstrong>三个标签\u003c/strong>：\u003c/p>\u003cp> 一个是\u003cstrong>终身学习者\u003c/strong>，我一年看五十本书，这个刚也介绍了；\u003c/p>\u003cp>\u003cstrong> 内向探索者\u003c/strong>，就是我会坚持冥想。 因为我 是一个非常浮躁的人， 做市场销售的，所以内心 比较浮躁。有时候也需要停下来静一静，慢下来，其实对自己很有帮助，这是一个总结复盘跟自我提升的一个机会。 \u003c/p>\u003cp> 第三个我是\u003cstrong>卓越影响者\u003c/strong>，这也是我的微信名。我希望能影响身边的人变得卓越，我也希望被身边卓越的人影响，所以我就起了这个名字。 这也是我学习了两门课程，一个是对卓越的投资，第二是影响力。这两门课程对我整个人生改变很大，所以我就用卓越影响者做微信名，天天都提醒我要朝这个目标去进步。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【过渡语&amp;分组】1分钟\u003c/strong>\u003c/p>\u003cp> 今天来的人应该因为美慧老师应该是有事先走了，人不多，要不我们就一个大组可以吧？ 好，那我们就分一个大组。 \u003c/p>\u003cp> 我今天\u003cstrong>拆解的书籍是：《爆款写作课》\u003c/strong>，学习目标是通过本次学习，可以懂得在自我介绍的时候，可以用到我们这个方法，在短时间内就获得认可和关注，快速建立链接。\u003c/p>\u003cp> 首先我\u003cstrong>分享的目录\u003c/strong>是这样子的，先对书籍进行一个简介。第二个我们就阅读一下原文，然后重述一下知识点。第四个就是具体应用也分享一下。\u003cbr> \u003cstrong>简单的介绍这本书\u003c/strong>， 爆款写作课，打造爆文的三个黄金法则。作者花了三年时间潜心钻研写作章法跟逻辑，独创了新媒体写作的三步法，吸引、打动、说服。讲述了打造爆文的三个黄金法则，主张会说话的人就会写作，详细拆解爆文的构成， 手把手教你从选题利益牢牢抓住读者眼球，打动和说服读者。 普通人只要遵循这个技巧，也能写出10万+，这是这本书的简介。你看秋叶、李海峰、彪悍一只猫，这些都是我们网上的一些大咖，联名推荐的一本书。\u003cbr> 我们现在来进行\u003cstrong>阅读原文\u003c/strong>，给两分钟时间。同样的如果大家阅读完这份是原文以后，可以在群上回复个1。那我们现在开始。\u003cbr>\u003c/p>","ratings_count":2,"texts":[{"id":23585,"quote":"\u003cp>\u003cstrong>【R：阅读原文片段】2分钟 自我介绍的MTV法\u003c/strong>\u003cbr>片段来源：《爆款写作课》（电子书P33-P34）\u003cbr>\u003cbr>\u003c/p>\u003cp>\u003cbr>\u003cbr>做自我介绍，其实就是一个做减法的过程，在过去的经历中，找到最亮点的成就事件，找到关键数据做支撑，然后尝试和对方连接。\u003cbr>用MTV 3步法介绍自己。\u003cbr>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003cbr>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003cbr>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003cbr>\u003c/p>\u003cul>\u003cli>M是英文单词Me的缩写，意思是你是谁?\u003c/li>\u003cli>T是英文单词Thing的缩写，意思是你做过什么成就事件?\u003c/li>\u003cli>V是单词Value的缩写，意思是你能提供什么价值?\u003c/li>\u003c/ul>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003cbr>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询:\u003cbr>1.普通人如何做出属于自己的歌曲?\u003cbr>2.如何成功脱单，找到自己的心灵伴侣?\u003cbr>3.个人品牌时代，如何借鉴明星包装经验推广自己?\u003cbr>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。理财的朋友可以协助配置家庭资产;读书很厉害的朋友可以帮助提高阅读速度;跑步的朋友可以解答坚持跑步过程中的疑惑;做演讲的朋友可以提升公众演讲能力。\u003cbr>当我们在自我介绍中说出能力(品类和标签)，说出成就事件(信任状)，说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>\u003cstrong>【I重述知识点】 4分钟\u003c/strong>\u003c/p>\u003cp> 既然大家都阅读完了，我们现在进行下一步，我们已经把这个原文阅读完了。那接下来我们简单介绍一下MTV法。\u003c/p>\u003cp> 那接下来我们简单介绍一下这个MTV法。这个MTV法其实 非常的简单，只要三步就可以了。在自我介绍的时候，我们就可以用这个MTV法，只要三步，第一步是M，这个M是Me，就是我；T就是Thing，就是事情，有价值的事情，有成就的事情；然后最后V是价值。所以\u003cstrong>MTV法就是第一个说我是谁？\u003c/strong> \u003cstrong>第二个说你做过最有成就的事！第三个说你对别人有什么价值。MTV法是什么？就是一个让他人可以深刻记住自己的自我介绍的方法。\u003c/strong>\u003c/p>\u003cp> 用MTV法做自我介绍非常好用。现在我基本上都是用这个方式自我介绍的，包括我们现在拆书帮的自我介绍，也是有有用到这个模型。\u003c/p>\u003cp> \u003cstrong>第一步就是说Me，这个M就是me，我是谁？\u003c/strong>像我会自我介绍说：“我是东华，我是三生三世十里桃花，里面的东华帝君，所以如果你记得我，看到我头像，就会想起我的人名。然后\u003cstrong>第二步就是你做过最有成就的事情\u003c/strong>，比如说我 ，我是做大市场销售的，我有一次在公司的会议里面做分享。在自我介绍的时候，我是这样说的，我是公司号称“薪价比&quot;最高的人。注意是薪，是薪酬的薪，不是性质的性，我是薪价比最高的人。长期蝉联广州销冠。那为什么我能就这样子呢？因为我把握着我们行业80%的大客户，这80%的大客户都愿意跟我合作。你想想，我们下面都是做销售，一听说我这么牛，他们马上脑子里的灯泡就亮起来：“遇到一个牛人，对吧！”。然后\u003cstrong>第三步就是，讲我对大家有什么价值\u003c/strong>，“我喜欢交朋友，可以帮你快速的建立市场关系，达成销售业绩。”\u003c/p>\u003cp> 这样子一讲，很多人就觉得我是个可以交的朋友。认识他，跟他对接上，以后有什么疑问，有什么困难都可以找他帮忙。所以我只要分享完，就会有一群人会跑过来跟我交朋友，加我微信。这个方法可以在短时间内就达到自我展现的效果，区分成自我和人群，吸引你同类别的朋友互相关注。除了参加活动、入职、开会的时候都可以用到这个方法，可以在很短的时间内破冰留下印象，并吸引同类人群自动链接。\u003c/p>\u003cp> 当然了，\u003cstrong>有一种场合是不适合用\u003c/strong>的。就是你不能拿这个方法，这个方式去跟你的长辈、跟领导介绍。因为你的长辈，你的领导，成就比你多，所以他的价值也比你强。你在他们的面前讲这些东西，会产生一种班门弄斧的感觉，这是要注意的地方。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1联系具体经验】1分钟\u003c/strong>\u003cbr>\u003c/p>\u003cp> 接着我再介绍一下， 在用这个MTV法则的时候一些连接和反思。回想起我当时刚刚入职的时候，作为普通员工，领导就让我自我介绍一下。\u003c/p>\u003cp> 我站起来的时候，我是很紧张的。我简单说一下我叫什么名字，来自哪里，有什么爱好，都是这样子的。希望快速的结束话题，然后让下一个人去自我介绍，对不对？很多人都这样子。最后一句说，很高兴认识大家，大家多多指教。\u003c/p>\u003cp> 基本上就是普通的自我介绍的一个逻辑，我也是这样子的，就仅此而已。因为轮到我，我就想把这个任务完成了就算了，所以很多人也用这个方式自我介绍，他们也是这样子的，跟我一模一样，然后介绍完，开完会后，谁也不认识谁。\u003c/p>\u003cp> 所以当时这个情况，我发现就是因为紧张，目的就是老想着说，这就是领导安排的任务，是击鼓传花，我把这个花传出去就行了，别多说多错。然后老是自我安慰，不要讲那么多。 现在短暂的自我介绍，其实是有目的的。你其实是要获取更多人的认可和链接，这样你在未来的成就跟机会，会多一点。有道是：朋友多了路好走，对不对？所以你如果会使用MTV法，就能短时间内让周边听过你介绍的人，都会了解到你的成就和价值点，然后得到认可，然后被关注。开完会或者是介绍完就会加你微信，找你请教，跟你交朋友，然后互相共享资源，这个是非常有用的一个方法。\u003c/p>\u003cp> 刚刚我们学习了自我介绍的MTV介绍方法。我想请各位有没有经历过类似的自我介绍的经历？当时你们是怎么做的？成功的也可以，失败的也可以，我们有请几个小伙伴出来分享一下，可以吗？\u003c/p>\u003cp>\u003cstrong>【分组分享：小组讨论，分享各自的过往经验】3分钟\u003c/strong>\u003c/p>\u003cp>  李芊老师： 我觉得自我介绍应该很多场合都有， 我讲一下我在讲培训课的时候的自我介绍。我当时是面对一百多人的新员工的介绍，我就感觉说，在新员工面前是不是要表现自己，能拉近他们的关系，或讲一些语言上面要是生动活泼一点，接地气的。所以当时我是在AI上生成了一段，生成以后，可能我自己太紧张了，结果我在讲的时候，我感觉讲的有点太过于，怎么说呢？ 就是不是用我自己的话去说的，就有点像背书的那种感觉，我觉得这样子就不太好。又没有经过自己深入的思考，或者换成自己的话去说，也没有怎么去练习过。 \u003c/p>\u003cp> 东华帝君： 我们没有学习MTV法的时候，反正自我介绍大家都差不多，对，您的经验差不多。咱们还有没有其他小伙伴呢？\u003c/p>\u003cp> 松晓老师：我之前做自我介绍的时候，就是，我是谁，我做什么工作的就完了。这样导致了一个后果，就是再次见面的时候，他就是很外向的一个小伙伴。看到我说，反正我们之前见过，但是你是叫什么什么吗？然后我不太记得清了，然后当时就很尴尬。\u003c/p>\u003cp> 东华帝君：是是是，确实会有这种情况，现在就有种说法，最怕去见那些老同学或老同事，见了面，对方名字却是想叫但叫不出来，这个脸很熟悉的，知道是自己同事或者老同学，但是名字叫不出来，也是蛮尴尬的。好的，还有吗？\u003c/p>\u003cp> 平常心老师：我分享一下，关于说自我介绍，我们有很多的一些场合做自我介绍。 比如说我们公司也有一些培训。 然后的话相关的每次在培训的话，老师也会让我们做一下自我介绍。 我们通常的形式就像大多数介绍一样，可能是说叫什么名字，来自哪个地方，然后是属于哪个部门，负责什么的。如果我们学了这个MTV的这个沟通方式之后，可以增加一些跟同事之间的互动的。比如说可以说自己有哪一些的专长，哪一些的兴趣爱好，或者是说工作方面也可以去展现一下。在哪些方面对公司工作流程经验比较熟悉，其他的人员对这一部分不熟悉的，我们可以自己去展现这部分，给别人提供帮助。\u003c/p>\u003cp> 东华帝君：对的，谢谢平常心老师。说实在的，以前我自我介绍也这样说：大家好，我叫东华，来自潮汕。或者用另一种方法说：我叫东华，我在做什么工作的，对吧？就像松晓老师那样子， 说请多多指教。其实讲完后，跟没有自我介绍一样，我们学的这个方法后，其实是蛮有用的。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【A2具体应用】9分钟\u003c/strong>\u003c/p>\u003cp>我们刚刚学会了一些新的自我介绍法，用“MTV法”自我介绍，也联系了过去。接下来，我们要把这个方法应用到实际的生活中面去。 \u003c/p>\u003cp>\u003cstrong>（目标）：\u003c/strong>\u003c/p>\u003cp> 我们先设定一个目标，这个目标是这样子，你可以这样设定，就在每次聚会，包括开会，生活上比如拆书帮的聚会也行。通过自我介绍，介绍完后，至少有3到5个人会主动的加你的微信或表达互相认识的要求。这个是很明确的，很好的考验你学习完后，你应用后的目标，能达到什么程度。 \u003c/p>\u003cp>\u003cstrong>（行动）：\u003c/strong>\u003c/p>\u003cp> 行动就是在短时间内，我们通过这个MTV法表现，并获得期望的效果。你自我介绍其实也不能太长了，太长，人家也会觉得你讲话挺啰嗦的。所以要在短时间内，通过这个MTV的这个模式去做自我介绍，通过这个表现获得期望的效果。期望效果就是有人加你微信，能链接上，所以你可以针对不同的场合多准备几套自我介绍的内容，比如我有两张名片的，如果是在工作上，我给政府机关递交名片的时候就会印发什么某某分局主任之类的。但是我在市场在商界，我递交的就是说区域总经理的名片。\u003c/p>\u003cp> 这样子快速的获取亲近和认同感，收获人脉和提高合作几率。\u003c/p>\u003cp> 所以我们要针对不同的场合做自我介绍，不要把工作上的自我介绍和在拆书帮或者是在线下读书会的介绍一样，当然都是用MTV法。但要围绕对象，主体准备不同的内容。\u003c/p>\u003cp> 我举个例子 \u003c/p>\u003cp>\u003cstrong>（第一套\u003c/strong>）\u003cstrong>： \u003c/strong>\u003c/p>\u003cp> 比如说我在工作市场方面，我会这样子自我介绍。首先我说，大家好，我是番禺区市场部经理，我叫李东华。然后小李飞刀的李、东方不败的东、中华英雄的华，这个就是把名字做一个链接，让大家记住。有时候我会用首诗来做自我介绍，比如说：我是日出东方烁烁其华，的东华。也是用一首诗来介绍自己名字。朗朗上口，容易记忆。\u003c/p>\u003cp> 然后T就是事情，我有什么样的成就，因为我之前说了，我不是武侠高手，但我确确实实是大市场高手。在我们行业，我不但是广州第一，而且是垄断了广州的大客户资源。因为我会讲粤语、客家话、潮汕话，所以行业内大客户，有3分之2都是我老乡。这句话讲话里面潜意识就是告诉你说，我有很多资源，我有很多成就，对吧？然后你如果链接我，我可以教你，我可以把我资源过渡给你。\u003c/p>\u003cp> 另外我会讲粤语、客家话、潮汕话，那说明你有可能是我老乡，也可以找我链接。所以一句话里面，带了很多价值成就在里面。\u003c/p>\u003cp> 第三个我会这样接着说，有需要我牵头认识的，可以找我介绍，我可以轻松的让你获得人脉跟达到销售业绩，这就是我在市场方面的自我介绍。\u003c/p>\u003cp>\u003cstrong>（第二套\u003c/strong>）\u003cstrong>：\u003c/strong>\u003c/p>\u003cp> \u003cbr> 当然在朋友或者是在生活方面我是这样子介绍：大家好，我叫李东华，三生三世东华帝君一样的名字，大家叫我帝君就好了。\u003c/p>\u003cp> 这样简单也好记。然后我有三个标签，这里注意一下，我的这个自我介绍是有区别的。 所以你学习了这个方法后，它可以迭代跟进步。我在拆书帮自我介绍的时候说，我是终身学习者，我每年看五十本书。那是因为我们拆书帮的人都爱看书，一听到这个就很有共鸣，有没有？ \u003c/p>\u003cp> 然后是内向探索者，坚持正念冥想心理纠偏。我帮助过四名同事走出过抑郁，迈向新的生活。因为如果人一直都是焦虑的，被事情推着往前走，那你根本就没办法停下来思考人生。所以如果你能停下来做一下正念冥想，你就发现很多事情其实没有那么严重，过去的所有事情都是擦伤，都是小事。\u003c/p>\u003cp> 为什么说我要帮四名同事走出抑郁？就是现场会有一些，比如说倾向内向的人，或者需要帮忙的人，我就可以帮到他，这是我的成就。\u003c/p>\u003cp> 另外我作为培训讲师，卓越影响者这个身份，我是一名企业讲师，我是省级十优讲师，现在是集团级的训战师了。\u003c/p>\u003cp> V就是价值，讲完我的介绍后，我会告诉你，作为你的朋友，它是有什么价值。我有一套自我学习的思想模型，他可以让我从一个内向抑郁患者变成一个外向的社牛，我们可以交流，共同成长，这是我具体的案例。\u003c/p>\u003cp>\u003cstrong> （作业：要求符合Smart原则）：\u003c/strong>\u003c/p>\u003cp> 接下来我们规划一下，在不久的将来，如果你需要做自我介绍时候，你怎么运用今天的MTV方法，来做自我介绍，迭代一下。因为你们之前自我介绍方法，学习我这个拆书法之前，更学习之后，你应该怎么做自我介绍。\u003c/p>\u003cp> 我们给大家两分钟时间，我们把它写下来好吧？然后再请大家来分享一下可以吗？\u003c/p>\u003cp> 如果大家把这个MTV法，自我介绍想好后或写下来后，可以在群上主动出来分享一下。来，我们现在开始。\u003c/p>\u003cp> 之前有用过MTV法的，就是确实有迭代过，可以讲一讲，会直接来分享。\u003c/p>\u003cp> 好的。\u003c/p>\u003cp> 其实如果大家需要回去再自我思考一下，可以写完后分享到群里面。然后我跟三午老师再给大家一些小小的补充建议，可以吧？\u003c/p>\u003cp> 由于时间关系，我们的今天的拆除方法就讲到这里，好吗？\u003c/p>\u003cp>\u003cstrong>【结束语】1分钟\u003c/strong>\u003c/p>\u003cp> 希望大家能通过今天的学习和运用，在今后的生活跟工作上能用上，给对方，给你想要介绍的人，留下深刻的印象，并留下链接，打造自己的人脉。我的1-2晋级就到这里，谢谢大家参与，请各位小伙伴给一些洋葱跟苹果，也请观察者给我一个点评，谢谢。\u003cbr> \u003c/p>\u003cp>\u003cstrong> 【洋葱跟苹果】\u003c/strong>\u003c/p>\u003cp> 三午老师：好的，谢谢东华老师，你分享的很赞。那还是一样，我们先来说一下苹果和洋葱，有请松晓老师。 \u003cbr> 松晓老师：东华老师今天两个分享都是非常实用的，而且我也都有好好学习。然后接下来这两个方法，我也都会在实际生活中多次运用到，这个是非常好的。而且我觉得帝君老师那个讲解还是蛮清晰的。如果说是洋葱的话，提个小建议。如果咱们\u003cstrong>线上的活动比较多的话，咱们的PPT可以在用重点色或者是重点符号把咱们的段落给它分出来\u003c/strong>。只有这一个。\u003cbr> 东华老师：好的，就\u003cstrong>标红标黑分段\u003c/strong>。\u003c/p>\u003cp> 松晓老师：对。 就是\u003cstrong>加粗，换个颜色\u003c/strong>。\u003cstrong>在重点的地方\u003c/strong>，这样可能看起来会稍微轻松一些。\u003cbr> 东华老师：好的，谢谢。\u003cbr> 三午老师：好，非常谢谢松晓老师。接下来芊芊老师。\u003cbr> 李芊老师：我觉得东华老师讲的这个片段，我是觉得挺喜欢的。就像是我刚在分享的时候，我觉得每个人都会有这种的场景，也唤起了我们，对这些自我介绍的这一段的，在生活或者是工作上联系上的这种实际用途，我觉得是非常好的。第二个就是我觉得东华老师的这个讲解，就一如既往都是很比较比较平易近人，很亲切的这种讲法，听起来还是蛮舒服的。洋葱的话我也暂时没有想到有其他。\u003cbr> 三午老师：好的，谢谢倩倩。平常心老师方便发言吗？\u003cbr> 平常心老师：好的，我觉得东华老师整个的分享的话，第一的感受就是\u003cstrong>很流畅\u003c/strong>，然后也比较\u003cstrong>专业\u003c/strong>。然后分享的这个具体的这个案例的话，也是一是也可以影响大家的共鸣，然后也是比较实用的，就是大家有共同的一些场景。然后我们学习了之后，也就是说在各种场合也都\u003cstrong>可以运用到自己的一些实际生活中去\u003c/strong>。 这些都是算苹果的部分。\u003c/p>\u003cp> 洋葱部分的话，就是刚刚在拆解那个介绍第二个环节的时候，我不知道是因为时间的关系还是什么，就是感觉上面有一点点仓促。如果是说能够让大家展开一组的讨论，可能会更更完美一点。\u003cbr> 三午老师：好的，您是说在最后还是在那个激活经验那里？\u003cbr> 平常心老师：最后的。\u003cbr> 东华老师：好的。最后因为我\u003cstrong>自己分享的案例多了\u003c/strong>，大家时间占用了，下次会注意这个问题。谢谢平常心老师，谢谢。\u003cbr> 三午老师：对，平常心老师也点评的非常到位，整体来说东华老师，分享的非常好。我觉得特别他分享的这几个案例，你把我们的经历都完全的激活了。其实东华老师很多自我介绍我都有听过，但是我今天又感觉到又有收获，这是作为学习者。作为观察者，他对1-2的技能是非常的娴熟的。因为他之前也已经过了一次1-2，而且又做了一下，这一次又做了一下迭代，非常用心。 我觉得这个心思非常用心，而且真的是非常超赞。而且他还举了几个例子，举了\u003cstrong>面对不同的客户类型\u003c/strong>，比如政府，比如同行，比如陌生人的环境，比如拆书帮的这些\u003cstrong>环境\u003c/strong>。我觉得这些都可以借来就可以套用的，非常好，这个MTV的非常实用。\u003cbr> 唯一有一个，是因为我在背后默默的提醒他，我说时间快到了，那肯定有一点点，我也不好意思，有点误导他。他这时间我们是最长是25分钟，那今天我们东华老师货值一共是23分钟，其实他可以再延长一两分钟，因为我我提醒了他，导致误导了他，以为他时间到了他就马上结束。 所以这里会有一个，但是不影响它的过程。 因为1-2，这个A2我们可以客户写完，就是请大家写完以后发一个案例给他。因为上次他过去就出现在这个bug上，就是写完以后大家没有把案例给他他没有收到案例，最后实录没有没通过。\u003cbr> 我们是允许过级完以后再给案例给他的，就是把MTV方法我们运用一下，我们怎么运用？把这个写一个就行了。你看东华老师这里有个示例，我们可以写市场的，也可以在拆书帮里面写自我介绍的，是这个方法是挺好的。最后就恭喜我们的东华老师成功晋级。\u003cbr> 东华老师：好，谢谢三位老师。\u003cbr> 松晓老师：我想插一句。在那个\u003cstrong>阅读原文的那个段落里面\u003c/strong>，其实可以加一句话。如果他比较长或者是比较慢的情况下，就是提醒\u003cstrong>如果没有阅读完的小伙伴也不要着急，在我讲之后的讲解中，大家会理解到这个原文的\u003c/strong>。\u003cbr> 东华老师：对对对，太好了，谢谢宋佳老师。这也是很好的方法。这个很好的方法。是的，特别是线上。因为线下的话大家一举手我们就能看到，所以线上其实这个方法是挺好的。我再补充个案例，反正还有两分钟时间，行不行？ 我在上次去现场做拆书帮的活动的时候，在听拆书帮其他同事自我介绍，其中就有用到这个方法。有一个同事说他是驴友，走过全国多少个城市，都给她跑完了。我听完后就很兴奋的，我会后马上就加她微信，说能不能来分享些旅游攻略。还有我们芊芊老师自我介绍说，他是瑜伽的多少级别的培训师。可惜我是个男的，不然我也想跟他多学瑜伽。所以听完很牛的人的分享以后，你就自然就很想跟他有链接，就补充一下这些。\u003c/p>\u003cp>\u003cstrong> 【李芊老师作业】\u003c/strong>\u003c/p>\u003cp> 在学会以后，所有的自我介绍中，都自觉主动采用MTV进行自我介绍，争取每次介绍完后，能给目标留下深刻印象，达到加微信链接的效果：\u003cbr> 【常见的自我介绍】\u003c/p>\u003cp> “大家好，我是李芊，是专线解决方案经理。我有十多年的工作经验，平时的工作就是在各个线条之间做协调沟通，所以我非常擅长沟通。大家以后工作中也会和其他部门打交道，如果对怎么有效沟通有疑问，我可以分享一些经验。”\u003c/p>\u003cp> 【自我反思】上面的常见介绍说了“擅长沟通”，但没有证明，提供了价值，但比较模糊被动，不易让人当场记住并采取行动。\u003c/p>\u003cp> 【使用MTV介绍法后】\u003c/p>\u003cp>M-“各位新同事大家好，我是李芊，一名‘拆墙’的产品经理。（用“拆墙”这个比喻代替“协调沟通”，形象地概括了产品经理工作的本质)\u003c/p>\u003cp>T-（擅长）我的日常工作就是穿梭在技术、集客和县分这些线条部门之间，把大家拧成一股绳，共同把指标做好。比如，我上周主要牵头一家三甲医院招投标项目，最自豪的一件事，就是通过建立一套高效的沟通机制，把一个原本需要扯皮两周的技术需求与商务价格评审会，压缩到了2天内搞定，这让我们的招投标文件完善提速30%。\u003c/p>\u003cp>V-（价值）我特别能理解大家回到岗位后，第一次需要去推动其他部门同事时可能会有的那种无助和忐忑。我的价值就是：我愿意成为大家在未来跨部门协作时的一个‘急救包’和‘润滑剂’。会后，欢迎大家加我微信，我会给大家分享一份我整理的《跨线条沟通避坑3板斧》。更重要的是，当你下次遇到跨线条难题不知道找谁时，或者会议陷入僵局时，别客气，直接来找我支支招！\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1755507386000,"updated_at":1756788596000,"ria":true},{"id":19064,"topic":"MTV自我介绍","learn_goal":"","remark":"传统的自我介绍流于形式，难以建立深度链接. \n而MTV 自我介绍法可以清晰呈现自我价值与他人进行链接. 便于他人理解和记忆. \n那什么是MTV自我介绍法呢? ","level":"TF1-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"百万","city":"宁波市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>大家好 我是有料青年刘百万 \u003c/p>\u003cp>拥有6年调味品行业 TOB C销售经验 14个月马龄的头马演讲人，\u003c/p>\u003cp>如果你在销售和公众表达 两版板块需要问题 欢迎我们一起交流。\u003c/p>\u003cp>今天的拆页它来自《爆款写作课》一书，作者弗兰克 一位很有经验的新媒体老师。\u003c/p>\u003cp>此书的核心观点是：关于写作，写东西不是为了自己爽，关键要有效传播，让别人看懂，记住，愿意转发。\u003c/p>\u003cp>书中有分钟很多实在的工具和方法，比如爆款公式，吸引人的结构，5S法则 MTV自我介绍法 等等 \u003c/p>\u003cp>那么今天我们拆页就是其中一个工具 MTV自我介绍法\u003c/p>","ratings_count":2,"texts":[{"id":23408,"quote":"\u003cp>首先让我们一起用看两分钟时间阅读下原文片段，阅读完的伙伴请在评论区扣个1\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。 \u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。 \u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。 \u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？ \u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？ \u003c/p>\u003cp>V是单词Value的缩写意思是你能提供什么价值？ \u003c/p>\u003cp>这样，量让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。 \u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询： \u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲？ \u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣？ \u003c/p>\u003cp>3.个人品牌时，如何借鉴明星包装经验推广自己？ \u003c/p>\u003cp>当晚添加一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。 \u003c/p>\u003cp>理财的朋友可以协助配置家庭资产，读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。 \u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。 \u003c/p>","explains":"\u003cp>谢谢大家，我看到6位伙伴完成了阅读，接下来让我们进行I便签的拆解分享 。\u003c/p>\u003cp>刚刚那篇原文用我们自己的话讲解时为我们介绍 \u003c/p>\u003cp>What ：\u003c/p>\u003cp>一个可以呈现自我价值 实现人际关系链接的自我介绍的工具MTV 即（ME THING Value ）\u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>\u003c/p>\u003cp>传统的自我介绍自我：大家好 我叫刘百万 祖籍安徽 生长于大连 和高兴认识大家。 当我讲完了之后也就没有然后了，可能一结束人家便忘记你是谁了。 难以建议人际链接。\u003c/p>\u003cp>而用MTV自我介绍公式，尤其在陌生场合可以第一时间 让对方知道你是谁 ？记住你的成就的事件，让听者对你多一些了解和信任，记住你可提供的价值 让有需要的人可以第一时间 想到你 找到你 链接到你。是一种高效的自我介绍方式。\u003c/p>\u003cp>\u003cstrong>How\u003c/strong> ：\u003c/p>\u003cp>MTV 自我介绍法则具体如何操作起来呢？我们来看一下具体步揍\u003c/p>\u003cp>第一步：Me \u003c/p>\u003cp>告诉对方我是谁？ 我的全名 年龄 职业 \u003c/p>\u003cp>第二步： Thing告诉对方自己做过什么成就事件 ？ \u003c/p>\u003cp>比如：获得的荣誉和奖项 在某行业深耕许多年有着丰富的经验 \u003c/p>\u003cp>自己做过别人没有做过的事情 自我的突破 都可以 \u003c/p>\u003cp>第三步：Value你能提供什么价值？ \u003c/p>\u003cp>就是你的专长，领域 资源 可以为对方提供生么样的帮助 。 \u003c/p>\u003cp>举个例子： \u003c/p>\u003cp>第一步：大家好我是刘百万，宁波Star TTT头马演讲会的现任主席 \u003c/p>\u003cp>第二步：在头马自主学习有一年的演讲实战经验 进行11篇备稿演讲。\u003c/p>\u003cp>今年参加了头马官方的演讲比赛获得我们小区的中文演讲冠军， \u003c/p>\u003cp>第三步：如果你想提升 公众演讲能力，需要从0-1攥写一篇演讲稿欢迎你与我一起交流。\u003c/p>\u003cp>MTV自我介绍法可以应用那些场景当中呢和大家分享三个板块\u003c/p>\u003cp>\u003cstrong>Where：\u003c/strong>\u003c/p>\u003cp>职场社交 快速让客户/朋友 记住你能解决的问题 碰到问题第一时间想到你 \u003c/p>\u003cp>求职面试 可以清晰明确的呈现出自己的价值以及自我优势 用价值代替自我宽泛的自夸\u003c/p>\u003cp>自媒体简介当中 明确单一赛道 ，提供的价值与个人成就可以吸引精准的粉丝群体 \u003c/p>","interaction":"\u003cp>\u003cstrong>指令：\u003c/strong>\u003c/p>\u003cp> 好啦，听过了我的分享现在邀请大家思考下，自己曾经有没有成功或失败的自我介绍经历？ \u003c/p>\u003cp>当时是什么样的场景和经过 结果，请在小组内互相分享：3分钟时间 结束后邀请一位小伙伴进行1-2分钟分享\u003c/p>\u003cp>分组指令：今天会场10位伙伴我们系统自动分成两组。\u003c/p>\u003cp>学员A1案例分享：\u003c/p>\u003cp>自我介绍场景：便签营开营第一次自我介绍\u003c/p>\u003cp>大家好我是彭光耀硕士毕业，工作十几年了 14年研发经验，每年为企业节省300万的费用。很高兴认识大家。这样子介绍。\u003c/p>\u003cp>回应：：谢谢彭光耀的分享，从你的分享中，我听到你介绍了 自己和行业经验。现在我们一起做个总结学习了今天MTV法，保留介绍我和成就事件的同时再将自我的价值清晰明确传递出去，是不是可以更好的传递自我价值，与现场有需要的伙伴产生链接。分享给你\u003c/p>\u003cp>话术过渡：30秒\u003c/p>\u003cp>再次感谢彭光耀的分享，今天我们学习了MTV自我自我介绍法，，今天学了在生活中去实践才算是真正的习得一份技能 \u003c/p>\u003cp>指令：接下来请大家思考下未来一周或一个月，会在什么场景下可以运用今天所学习的MTV法进行自我介绍给大家2分钟时间，\u003c/p>\u003cp>请写下具体的运用规划。\u003c/p>\u003cp>温馨提示：大家需要有具体做法、行动步骤，明确的时限和可衡量的预期结果写好后我将邀请1位学习者进行分享，时间2分钟/人\u003c/p>\u003cp>PPT举例：\u003c/p>\u003cp>时间：6月6号 到 6月30号 \u003c/p>\u003cp>场景：去拜访餐饮连锁客户的时候 进行MTV自我介绍法\u003c/p>\u003cp>行动步骤：\u003c/p>\u003cp>第一步：李总你好我是刘百万，料百道定制一部负责人 \u003c/p>\u003cp>第二步：在调味品行业深耕6年时间，拥有三年ToB销售经验，公司2023年度的销冠。\u003c/p>\u003cp>我们工厂专业做鸡精，鸡汁鸡粉23年，拥有鸡肉酶解技术。专注服务于餐饮连锁客户，做产品定制 为企业提质降本。\u003c/p>\u003cp>第三步：如果您这边想在产品上提质降本或者定制复合调料粉，我们可以随时交流。\u003c/p>\u003cp>可衡量 结果：添加至少三位有产品印象的的客户，进行交流。\u003c/p>\u003cp>两分钟时间到啦，大家都写完了么，现在邀请一位伙伴进行分享。\u003c/p>\u003cp>学员A2计划分享：\u003c/p>\u003cp>时间：6月25日\u003c/p>\u003cp>自我介绍场景：青少年学习训练营自我介绍时\u003c/p>\u003cp>行动步骤：大家好我是彭光耀 \u003c/p>\u003cp>成就事件：拆书训练营优秀学员 100天便签挑战赛 工做14年研发经验，每年为企业节省300万的费用。\u003c/p>\u003cp>可提供价值：拆书技能 自我专业上咨询\u003c/p>\u003cp>可衡量结果：10个人有一个人添加微信 产生进一步的交流\u003c/p>\u003cp>回应：感谢彭光耀的分享从你的计划当中我听到了在我介绍，在一个具体的事件6月25号，具体的场景青少年训练营，具体的MTV行动步骤以及达成以为伙伴链接，可衡量的结果。以结果再回看计划和内容。谢谢你分享了一个完整的自我介绍一天计划。\u003c/p>\u003cp>过渡：\u003c/p>\u003cp>给我们伙伴打了个样，大家可以参考，鼓励大家带着计划多去尝试和应用。时间有限有需要不懂得地方我们线下在交流。\u003c/p>\u003cp>现在我们做一个今天学习内容的总结\u003c/p>\u003cp>今天我们学习了MTV自我介绍法\u003c/p>\u003cp>第一步：Me \u003c/p>\u003cp>告诉对方我是谁？ 我的全名 年龄 职业 \u003c/p>\u003cp>第二步： Thing告诉对方自己做过什么成就事件 ？ \u003c/p>\u003cp>比如：获得的荣誉和奖项 在某行业深耕许多年有着丰富的经验 \u003c/p>\u003cp>自己做过别人没有做过的事情 自我的突破 都可以 \u003c/p>\u003cp>第三步：Value你能提供什么价值？ \u003c/p>\u003cp>就是你的专长，领域 资源 可以为对方提供生么样的帮助 。\u003c/p>\u003cp>期待今天的分享对大家有所帮助，在不同的生活工作场景中去运用起来与更多的伙伴产生链接，或许还会提升自我的影响力。\u003c/p>\u003cp>谢谢大家的聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1751082860000,"updated_at":1751339942000,"ria":true},{"id":19021,"topic":"自我介结的MTV法则","learn_goal":"","remark":"线下拆书","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"苏小暖","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"\u003cp>大家好，我是孙璇。今天很高兴能开启我的第一拆，现在我先自我介绍，我的三个标签是：\u003c/p>\u003cp>1、【职业标签】律师。从毕业至今我已经从事律师职业七年多，以后仍会继续下去。虽然做律师很辛苦，坚持下来的信念就是&quot;学法的女人不能输&quot;。\u003c/p>\u003cp>2、【兴趣标签】我的兴趣爱好是跳舞。最爱跳的是爵士舞，我接触爵士舞蹈的时候是在大学期间报的兴趣班，后来参加工作后中断了。直到去年参加律所年会演出，和同事一起表演了女团舞，我就又重新捡起了舞蹈的兴趣。\u003c/p>\u003cp>3、【身份标签】志愿者。我从大学开始就一直从事志愿者的活动，一直延续到现在。我从事志愿者的动机很简单，就是体验不同的生活状态，同时也能帮助到他人。关于身份标签，我希望以后能成为一名拆书家，一位终身学习的践行者。\u003c/p>\u003cp>拆书帮介绍\u003c/p>\u003cp>我是在今年4月份，阅读了赵周老师《这样读书就够了》之后，通过视频号和公众号添加了桃子老师的微信号，后来加入微信群，再后来参加了线上线下拆书活动，就慢慢接触到拆书帮这个组织。\u003c/p>\u003cp>&quot;拆书帮&quot;是基于拆书法的学习爱好者社群。拆书法是一种学习方法论，适用于以解决问题提升自己能力为目的的成人学习方法。它的核心概念是学以致用，用我们学到的知识和我们自身的经验相结合，并形成我们下一步的行动计划。拆书法的三个步骤是RIA，R（Reading）指的是阅读原书拆页，I（Interpretation）是拆书家讲解引导，对原文片段进行理解、阐述。A（Appropriation）联系自己的实际经验。\u003c/p>\u003cp>今天我分享的片段是用《爆款写作课：打造爆文的3个黄金法则》中的用MTV法则进行自我介绍。这个片段来自于弗兰克所著的一本畅销书。弗兰克，曾为世界500强外企职业经理人，2015年33岁起从0开始写作，2017年做自媒体收入100万。3年时间潜心钻研写作章法与逻辑。这本书他详细拆解了爆文的构成元素，手把手教咱们从选题立意牢牢抓住读者眼球，循序渐进打动和说服读者，最终将文字变现。\u003c/p>","ratings_count":1,"texts":[{"id":23359,"quote":"\u003cp>MTV法则 片段来源《爆款写作课：打造爆文的3个黄金法则》\u003c/p>\u003cp>做自我介绍，其实就是一个做减法的过程，在过去的经历中，找到最亮点的成就事件，找到关键数据做支撑，然后尝试和对方连接。用MTV 3步法介绍自己梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>I便签中用自己的话重述了原文知识点，清晰易懂\u003c/p>","explains":"\u003cp>【what】\u003c/p>\u003cp>为了更高效向他人介绍自己，让他人能记住自己，并建立个人品牌。该片段介绍了MTV法，通过介绍我是谁，我做过有成就的事情及能为他人提供的价值三个方面进行介绍自己。让别人主动链接自己，从而产生个人品牌。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>自我介绍最怕什么？最怕讲完人家没留下印象。那为什么会没留下印象呢？这是因为我们的介绍内容和对方个人之间缺少链接，没有关系，别人自然记不住。所以自我介绍想成功，我们就需要努力去链接对方，那有没有什么百搭的方法可以适用于各种场合呢？当然有啊，MTV法就可以，它是一种价值导向的介绍，而价值是最好的链接催化剂，所以在各种场景下，面对各类人，都可以发挥很好的效果。这个方法主要围绕三个方面介绍自己，首先是介绍自己基本信息及能力，这一步就是破冰，大家可以对自己有个初步的了解；然后是做过有成就的事件，让他人对自己产生好奇和信任；最后是介绍自己能为他人提供的价值，让自己与他人产生联系，为他人主动和自己联系搭建了桥梁。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>MTV法包含以下三个步骤：\u003c/p>\u003cp>M：介绍自己，例如：大家好，我叫孙璇，一位在上海工作的武汉人，爱吃辣，爱跳舞，同时也是一名专做商事诉讼的律师。\u003c/p>\u003cp>T：介绍自己做过有成就的事情，例如：历尽3年无偿为13位劳动者维权，通过劳动仲裁和诉讼方式为代理的劳动者追讨拖欠工资，虽然用人单位已处于破产清算流程，但我们的13位劳动者的债权足额清偿，成功挽回他们辛苦工作的血汗钱。\u003c/p>\u003cp>V：介绍自己的价值点，例如：如果遇到法律问题，我可以提供一对一的法律咨询。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>MTV介绍法适用于目标导向的社交场合、商务合作洽谈或快速建立专业形象的场景。不适用于非正式的社交或情感导向的场景，例如：朋友的聚会、相亲等场合，同时在权力不对等或需要弱化自我的场景也不太适用，例如：向权威领导进行工作汇报等。\u003c/p>","interaction":"\u003cp>A1-激活经验\u003c/p>\u003cp>A1便签中给到了至少有一个自己的具体经历，可以是佐证知识点有用的正面实例，也可以是自己之前没能做到所以效果不好的反面例子\u003c/p>\u003cp>这让我想起了上周四参加律所组织的建设工程主题的分享会上的自我介绍，我的自我介绍是“大家好，我叫孙璇，我来自万商天勤（上海）律师事务所，目前主要执业领域是商事诉讼，处理过大量的建设工程纠纷案件。”这个自我介绍信息仅仅提供了我的姓名、工作单位及职业领域，对于听众而言没有太多的链接点，没有列举相关的成功案件及自我提供的价值信息，这将无法增进大家对我的了解和信任，无法产生与我进行链接的想法。\u003c/p>\u003cp>A2-催化应用\u003c/p>\u003cp>A2便签规划了对知识的具体运用，听起来够清晰、能执行\u003c/p>\u003cp>目标：下周五的街道社区关于劳动维权的普法会议上利用MTV法进行自我介绍。\u003c/p>\u003cp>行动：根据参会的人员情况，准备好自我介绍的初稿“大家好，我叫孙璇，我是一名商事诉讼的律师，做过大量的劳动争议案件。曾历尽3年无偿为13位劳动者维权，通过劳动仲裁和诉讼方式为代理的劳动者追讨拖欠工资，虽然用人单位已处于破产清算流程，但我们的13位劳动者的债权优先清偿，劳动者全都拿回了他们的血汗钱。由于现在经济下行，企业为了降本增效进行大量的裁员或进行降薪操作，如果你也遇到类似的情况，可以随时和我联系，我会法律支持，帮助你最大化争取合法权益。”\u003c/p>\u003cp>我今天的分享就到此结束了，希望我的分享会对各位小伙伴有所帮助。大家再遇到自我介绍时，咱们可以试试MTV法则，从而实现更高效地与他人链接。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1749993560000,"updated_at":1750922145000,"ria":true},{"id":18979,"topic":"《爆款写作课》之MTV自我介绍法","learn_goal":"","remark":"如何用MTV介绍法，加深第一印象，拓展与人深度连接机会。\n欢迎大家来参加腾讯会议","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"深蓝～","city":"台州市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>一、【自我介绍】\u003c/p>\u003cp>大家好！我是李梨花，来自宁波幸福虚度分舵，我是一名财务工作者，也是一名钩织爱好者，现在更是一名新手拆书家，正在为我的1-2级而努力。\u003c/p>\u003cp>二、【图书介绍】\u003c/p>\u003cp>很高兴今天能在这里和大家一起来拆解这本《爆款写作课》，这本书的作者弗兰克对写作技巧有着独特的且实用的见解，并且独创了新媒体写作三步法：吸引、打动、说服，为渴望在新媒体领域突围的创作者提供了一套极具实用性的方法论。\u003c/p>\u003cp> 今天我们要学习其中的“MTV自我介绍法”。\u003c/p>\u003cp>接下来请大家花两分钟时间来看一下原文片段，看完后大家扣1示意我一下，谢谢。\u003c/p>","ratings_count":2,"texts":[{"id":23314,"quote":"\u003cp>三、【R原文片段】《MTV自我介绍法》电子书P33-34，片段来源〈爆款写作课〉\u003c/p>\u003cp>做自我介绍，其实就是一个做减法的过程，在过去的经历中，找到最亮点的成就事件，找到关键数据做支撑，然后尝试和对方连接。\u003c/p>\u003cp> 用MTV 3步法介绍自己。\u003c/p>\u003cp> 梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁?\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件?\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值?\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询:\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲?\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣?\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己?\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。理财的朋友可以协助配置家庭资产;读书很厉害的朋友可以帮助提高阅读速度;跑步的朋友可以解答坚持跑步过程中的疑惑;做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力(品类和标签)，说出成就事件(信任状)，说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp> 四、【I拆书家讲解引导】\u003c/p>\u003cp> What：，MTV自我介绍法作为一种自我介绍的工具，通过三个关键要素即“我是谁（me）”、“成就事件（Thing）”、“提供价值（Value）”来简洁明了的传达个人信息和价值。\u003c/p>\u003cp>Why：人与人之间通常是先从一个自我介绍开始熟悉从而产生连接。传统的自我介绍可能只是简单的说明基本信息，很难给人留下深刻印象。而MTV自我介绍法能突出重点，让对方迅速了解你的独特之处以及能为其带来的帮助，这样大大提升了自我介绍的效果。\u003c/p>\u003cp>How：那么如何使用MTV法来进行自我介绍呢，我们可以把它分成三步来表达：\u003c/p>\u003cp>第一步：介绍标签，就是介绍”我是谁(me)”，给自己贴个标签，以便对方快速的了解我的身份，例如我是一位会计师。\u003c/p>\u003cp>第二步：介绍自己的成就（Thing），就是向对方介绍我曾经做过什么有成就的事件。例如介绍自己曾成功完成企业年度汇算清缴，合理税务筹划为公司节税十几万。\u003c/p>\u003cp>第三步：提供价值(Value)，就是介绍我有何价值。例如介绍自己是会计师，曾经为公司解决过财务方面的纠纷，避免公司经济损失。那么别人若是对这个价值点有需求，就会主动链接我和我就会有更深入的互动。    \u003c/p>\u003cp>我记得去年参加一场读书交流活动时，遇到了尴尬的事，主持人要求大家先做个自我介绍，但我没想到会是从我这排先开始而我恰好是第一个当时没多想站起来就说：“我是李梨花，来自玉城，很高兴认识大家”。然后就结束了发言。那时就想快点讲完，好把话筒交给下一个。没想到后面的伙伴大部份都参照了我的模版来自我介绍，就只有四五个伙伴用了不一样的方法给我们留下了深刻的印象，后面才知道他们是用了MTV介绍法。\u003c/p>\u003cp>自从认识到MTV介绍法的好处后，后来再参加社交活动时我都会用MTV来做自我介绍；\u003c/p>\u003cp>第一步：用M（我是谁）贴标签：介绍了我是李梨花来自玉城，是一名会计师。\u003c/p>\u003cp>第二步：用T（介绍自己的成就）：曾经在处理税务稽查时，通过合规手段化解风险，避免公司被罚款。\u003c/p>\u003cp>第三步：用V（我能提供的价值）：大家有什么税务或财务等方面的问题都可以来问我，我一定积极帮大家解答。\u003c/p>\u003cp>Where： MTV自我介绍法比较适用于正式的场合中，如商务合作洽谈、市场推广、求职面试等。而非正式场合如私人社交就不太适合。\u003c/p>","interaction":"\u003cp> 接下来我们进入讨论分享环节， 晚上有8个人，我们分为两组讨论，我会给大家做线上的分组，到时候大家进入讨论小组进行讨论分享。\u003c/p>\u003cp> 五、【A1激活经验】\u003c/p>\u003cp> （一）拆书家提问+组内讨论分享\u003c/p>\u003cp> 刚才我们一起学习了用MTV法来自我介绍，这种方法不仅可以在有限的时间内，清晰地展示我们的特点和经历，还可以帮助我们更好地与他人沟通，加强对方对我们的信任感，那么对方就会在有需要的时候主动链接我们。\u003c/p>\u003cp>接下来请大家回想下自己以往的自我介绍的经历，当时有没有用过类似的方法，结果如何?\u003c/p>\u003cp> 现在请大家花2分钟时间在组里讨论分享下，小组讨论结束以后，我会邀请伙伴来大组分享。\u003c/p>\u003cp> 好，时间到。有哪位伙伴愿意分享呢？\u003c/p>\u003cp> （二）现场学员的分享：\u003c/p>\u003cp> 此念：之前的自我介绍也是很简单，就是介绍自己的姓名、职业,这些比较基础的信息，没有自己独特的标签。感觉难为情自己也没有什么成就事件跟价值。所以说在几十个学员当中,这样的自我介绍结果可想了,肯定是都没有记住我。所以活动结束之后,大家也就都没有联系了。\u003c/p>\u003cp> 感谢此念的分享。\u003c/p>\u003cp> 六、【A2规划应用】\u003c/p>\u003cp> （一）拆书家提问+学员规划书写\u003c/p>\u003cp>经过今天的学习，相信大家对MTV自我介绍法有了初步的掌握。那么我们就要把这个好方法运用到实际生活中去，请大家思考在未来一个月、三个月内你将如何运用MTV法来做自我介绍，比如去参加一场社交活动或者求职面试等 ，你将如何制定规划使用目标和具体行动。请注意目标一定要有具体的使用时间，要和方法相关，要具体可完成，结果可衡量,行动一定要体现方法的具体内容。\u003c/p>\u003cp> 现在给大家3分钟时间思考下，然后把你的构思写在便签纸上，有时间的话也会邀请伙伴来分享。\u003c/p>\u003cp> （二）现场学员的分享：\u003c/p>\u003cp> 粿子：通过MTV的这个介绍法，在一个月内参加活动我首先我是要介绍一下我是谁，然后介绍三个标签：一个是食品检验工程师，第二个我是独抚两个孩子的妈妈，然后第三个就是我是在升级打怪路上的现任拆书家，还是一级的。这是我现在比较明显的三个标签。然后我的成就：首先一个是也做了十几年的食品检验的工作，在食品检验这一块我还是比较在行的，也算是我们单位的高手之一吧。然后像在带娃方面，毕竟两个孩子也已经是小学高年纪，所以对于男孩子之间的这种冲突我还是比较有经验，虽然可能特别时候我也会比较有脾气,但是相对来说我还是感觉比较有经验的那种，对于拆书法这一块嘛,毕竟自己已经过了一级了嘛,是一级拆书家了,相对新手来说可能还是有那么一点点经验的。这就是我的成就。然后我的提供的价值嘛,我感觉我最近给他人提供的价值最重要的就是那个情绪价值，能给别人提供那种积极向上的情绪。\u003c/p>\u003cp> 感谢粿子分享，也希望能收到你用MTV法在参加社交活动时的效果反馈。\u003c/p>\u003cp> 由于时间的关系就不再叫人分享了，大家回去后呢可以多练习这个方法，在以后参加社交活动时可以运用起来，\u003c/p>\u003cp> 七、【总结】\u003c/p>\u003cp>今天给大家分享了用MTV法来做自我介绍，通过这种方法能高效展现个人亮点，快速建立专业印象，使个人价值更容易获得别人的肯定、产生高的需求链接。无论是在商务合作、面试还是社交场合，我相信这套方法都能帮到你。\u003c/p>\u003cp> 最后欢迎大家扫码加入我们宁波幸福虚度分舵。\u003c/p>\u003cp> 我今天的分享就到这里，非常感谢大家的陪伴，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1749111889000,"updated_at":1749115150000,"ria":true},{"id":18675,"topic":"MTV自我介绍法","learn_goal":"","remark":"当我们需要介绍自己时，\n除了说名字年龄爱好，竟不知该说点什么？\n介绍完坐下了才发现想说的都没说？\n介绍完自己别人完全没get到我们的“精髓”？\n如何让自我介绍清晰简单却有效？\n今天的MTV自我介绍法则支持到你！\n","level":"TF1-1","duration":5151,"status":30,"type":0,"chaishujia":{"username":"李沐恩","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>【开场】0.5分钟\u003c/strong>\u003c/p>\u003cp>拆书帮的各位伙伴，你好！\u003c/p>\u003cp>今天我要进行TF1-1的过级，感谢各位伙伴到场支持。\u003c/p>\u003cp>我今天的拆书主题是，&lt;MTV自我介绍法则&gt;，片段来自《爆款写作课》这本书，拆书时间大约15分钟。\u003c/p>\u003cp>\u003cstrong>【自我介绍】1分钟\u003c/strong>\u003c/p>\u003cp>首先做下自我介绍。我叫沐恩。一个符合能量学，易学，以及我的喜好的名字。\u003c/p>\u003cp>我的3个标签是：\u003c/p>\u003cp>（1）我是一位情商训练师，我可以用体系帮助大家提升情商能力，也就是社会情感能力。\u003c/p>\u003cp>（2）我是一名热爱分享和输出的学习者。有缘接触了拆书帮，感觉增加了一个可以分享和帮助更多人的能力，特别感恩。\u003c/p>\u003cp>（3）我是一位有生命能量的妈妈。我主张用生命影响生命，生命力养育才是最高级的养育方式。\u003c/p>\u003cp>\u003cstrong>【介绍拆书法和拆书帮】2分钟\u003c/strong>\u003c/p>\u003cp>在开始今天的拆书之前，我先介绍一下拆书法和拆书帮。\u003c/p>\u003cp>拆书，最吸引我的就是以学习者为中心。这真的是帮助我们把知识转换为自己的能力的学习方式。我们在读书时往往容易被知识吸引，从而以知识为主去读书学习，当我们无法把学到的知识转化为自己的能力，而只是灌输知识时，反而会阻挡了知识真正进入我们的头脑和生活。因此，了解拆页，关联经验，规划行动，才是真正的拆书学习。不管对于个人和组织，都是有效的方法。\u003c/p>\u003cp>“拆书帮”是拆书法学习爱好者的社群，一帮正能量，相互促进相互赋能的非营利性组织。定期举办的各种线上/线下活动，都在不断践行着以学习者为中心，帮助更多的爱好学习和成长的人成为拆书家的使命拆为己用。\u003c/p>","ratings_count":1,"texts":[{"id":22981,"quote":"\u003cp>R：MTV法介绍自己   片段来源《爆款写作课》\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp> V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp> 比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp> 1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp> 2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>I：\u003c/p>\u003cp>what：这是一种在大部分场景下都可以运用，并可以将自我介绍做的清晰明了的工具。\u003c/p>\u003cp>why：我们跟对方介绍自己的目的，一定是建立在希望产生“合作”的基础上。知彼知己才能“百战不殆”。别人在听我们做自我介绍时，也会思考跟他个人相关的信息。这时候就需要我们把自身的优势跟能为别人提供的价值共同去表达出来。\u003c/p>\u003cp>where：MTV自我介绍法更适用于新认识的朋友或者圈子。即将产生或有可能会产生合作关系的伙伴之间。\u003c/p>\u003cp>how：第一步一定是先介绍一下自己是谁，一些基本的信息是需要表达的，比如姓名年龄兴趣爱好，工作等方面。\u003c/p>\u003cp>第二步要表明我曾做过什么比较有成就的事情。如果这一步中的成就事件可以跟第三部相关就最好了。\u003c/p>\u003cp>第三步是我们能为对方提供哪些价值，让大家可以很清晰地知道，原来这位朋友，可以成为一个拥有这样标签和能力的朋友。\u003c/p>\u003cp>这样下来，就达到了有效的自我介绍，而且内容精炼，不会让对方常生厌倦。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1便签】2分钟\u003c/strong>\u003c/p>\u003cp>周二去参加头马俱乐部的即兴演讲。开场时会有自我介绍环节。我就开始了自己的侃侃而谈模式。介绍了基本信息，然后开始表达自己想做的事情以及自己的情怀和初心，我相信那时候的我是很认真的。说了两分钟、我的时间到了。下来入座后，就意识到好像，只是向别人展示了自己的激情澎湃，却没有真的让别人知道我的具体业务范围，以为我能为别人带来的资源和支持。\u003c/p>\u003cp>我思考了一下，我在自我介绍时，M这个部分是可以做到的，但是T这个部分有点泛泛而谈、主要谈论了想法和框架，但没有具体到细节之上，这对于很多新认识的人来说，是很难捕捉到具体信息去了解我的。V这个部分更是没有好好传达。总觉得我表达了自己，别人就会get到我是做什么的，我能力状态怎么样。但实际上，这样的收效是很小的。\u003c/p>\u003cp>\u003cstrong>【A2便签】2分钟\u003c/strong>\u003c/p>\u003cp>因为有一部分工作是讲课，所以少不了做自我介绍。在下一次的自我介绍当中，我一定会按照MTV的自我介绍法去做。那既然决定了就要提前做好准备。\u003c/p>\u003cp>M：大家好，我是沐恩，一只可爱的小兔子，今年38岁了，有个幸福的十岁女儿和快乐自足的自己。\u003c/p>\u003cp>T：在这短暂的人生经历中，最成就的事情是在事业单位辞职，加盟了国内前三名的情商品牌课程，在青岛创办了属于自己的情商课程品牌：乐思情商。在这个过程中进行了深入的自我学习和提升，支持到了无数的家庭，以及学校，社区等。为家庭教育事业贡献了自己的力量。\u003c/p>\u003cp>V：我可以为大家做高情商成人和儿童的培养，可以帮助大家养成积极互助的家庭养育模式，可以帮助孩子们形成自驱自洽的思维和行为方式，可以让你同另一个维度脱离生活中你的大部分苦恼，大幅度提高生活的幸福指数。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1741078726000,"updated_at":1741084491000,"ria":true},{"id":18191,"topic":"如何让别人对你产生兴趣，而不是仅仅简单记住你","learn_goal":"","remark":"写作方法","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"莫九","city":""},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp> 大家好，我是张敏，弓长张，敏而好学的敏，从毕业就开始一直在医美整形医院工作至今，第二个标签是运动爱好者，非常喜欢各类运动，第三个标签就是读书博主，可以和我换书交流讨论哈！\u003c/p>\u003cp> 简单介绍一下拆书帮，拆书帮是基于拆书法的学习爱好者的非营利性的学习社群，全国各地都是有拆书帮分舵，其使命是帮助更多学习爱好者成为拆书家，其愿景帮助拆书家们升级学习力及促进他人学习的能力，影响身边的人，让世界变得更好一点，拆书帮价值观：陪伴赋能 拆为己用 反求诸己 持续精进 共同成长。\u003c/p>\u003cp> 拆书帮的拆书法分两种，一种是个人学习时用的方法叫【便签读书法】，还有一种是组织学习时用的方法叫拆书帮现场学习法，也叫【RIA现场学习法】——R意思是阅读原文拆页，I意思是讲解引导。A意思是拆为己用！今天我们用到的就是RIA现场学习法来拆解今天的内容。\u003c/p>\u003cp> 今天我要向大家分享的是《爆款写作课》这本书，要拆的片段是MTV法介绍自己！因为它太实用啦，很多场合都用得上。下面请大家花1分钟时间看一下我们今天的片段拆页，大家看完了可以向我举手示意一下，谢谢。\u003c/p>","ratings_count":1,"texts":[{"id":22461,"quote":"\u003cp>\u003cstrong>【R原文片段】：MTV法介绍自己\u003c/strong> \u003cstrong>片段来源《爆款写作课》（电子书P33-P34）\u003c/strong>\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>好的，各位伙伴已经看完了，那我来分享一下我的解读。\u003c/p>\u003cp>【what】 用最简短的时间快捷明了介绍了自己的成就事件，我可以给你带来什么，我的价值，整体坦诚可以更好的进行深层次链接的一种沟通方式！\u003c/p>\u003cp>【why】第一印象很重要，与陌生人第一次接触所得印象会有一个先入为主，可能是正面也有可能是负面，之后很难扭转，所以第一印象有着巨大作用！\u003c/p>\u003cp>【how】分为三步：\u003c/p>\u003cp>\u003cstrong>\u003cem>M\u003c/em>：介绍我是谁\u003c/strong>，可以从你的籍贯，名字，工作，爱好等等介入，可以选择针对不同场合来选择性介绍自己的基本情况。不同场合想要展现出来的不同的面。\u003c/p>\u003cp>比如我叫张敏，我是一名10年医美咨询工作者，帮助很多求美者带来自信，那么对美丽形象维持的会感兴趣的朋友就可以选择和我链接！\u003c/p>\u003cp>\u003cstrong>\u003cem>T\u003c/em>：我做了什么？\u003c/strong>介绍你做过的成就事件，以便让对方更好地了解你的能力和价值。\u003c/p>\u003cp>比如我从被水淹到极度惧怕水到克服恐惧再到没请教练自学了各种游泳，那么可以链接想要运动学习游泳的朋友。\u003c/p>\u003cp>\u003cstrong>\u003cem>V\u003c/em>：我能提供什么价值？\u003c/strong>在你做成功的有结果的任何一件事情的细节里，可以帮助到别人的都是你的价值。\u003c/p>\u003cp>比如我的自学游泳中各类口诀，视频，日常练习动作等等，可以帮助我们克服对水的恐惧，去享受水的乐趣！\u003c/p>\u003cp>【where】想要让对方迅速了解你的价值，从而增加后续良好链接，适用于面试、社交、商务、新朋友、个人IP等，要灵活使用自己擅长的优势去选择性的介绍。\u003c/p>","interaction":"\u003cp>【A1】在过去你是怎么自我介绍的？当时会大脑一片空白吗？\u003c/p>\u003cp>那我以前就是一片空白、麻木的自我介绍，比如：大家好，我叫张敏，我喜欢运动，喜欢看书，很高兴认识你或者很高兴认识大家，根据不同场合基本就是这几句台词。直到有一次我身边人去了大老远的地方做植发，做隆鼻做双眼皮后期又花费大量时间去复查等等，后面才知道张敏你居然已经做了十多年的医美咨询，怎么不介绍你们医院啊，最起码你在医院我找你还放心些！\u003c/p>\u003cp>反思：\u003c/p>\u003cp>1.我不说或者说得少，大家不知道我从事的行业是什么，有医美整形需求时想不到找我\u003c/p>\u003cp>2.我在医美工作十年以上，是能够给爱美人士提供非常专业的咨询价值我没有体现出来，所以有整形的需求也不会想到去找我咨询。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>拆完这个MTV自我介绍后，在下次拆书帮周二的活动上，我可以这样介绍自己，大家好，我是张敏，我是一名从事10年的医美咨询者，帮助过很多求美者带来自信，所以有关任何美丽相关的问题，我都很高兴全方位进行解惑哦！第二个标签是运动爱好者，现在正在进行游泳打卡中，如果有想要运动习惯养成的可以和我一起打卡监督哦！第三个标签就是拆书帮东莞乐享分舵的会员，正在晋级拆书家的路上。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1729059003000,"updated_at":1729061115000,"ria":true},{"id":18127,"topic":"用MTV法介绍自己","learn_goal":"","remark":"在不同的场合链接同频小伙伴，更好地展现自己的价值","level":"TF1-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"刘君","city":""},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>大家好，我是刘君，刘备的刘，谦谦君子的君\u003c/p>\u003cp>我的三个标签：\u003c/p>\u003cp>1.曾经营实体店，销售电脑硬件；后又顺应时代发展创业网店，经营自有品牌望远镜\u003c/p>\u003cp>2.我是一名冥想爱好者，每天半小时冥想练习，已坚持三年，正在冥想师进阶考证中\u003c/p>\u003cp>3.我是未来的拆书家，希望将拆书法与冥想结合，组织正念冥想读书会，帮助更多人更好地应对现在高压焦虑的生活\u003c/p>\u003cp>拆书和拆书法\u003c/p>\u003cp>拆书是可以真正把书中知识用来解决生活中的实际问题、提升工作能力的一种成人学习法\u000b它以学习者为中心，分为个人学习法和组织现场学习法\u003c/p>\u003cp> 个人学习法是通过RIA便签将书中知识拆为己用\u000b 组织学习法则是通过拆书家的引导、促进、催化，结合书中知识和学习者对自身经验的反思、 提炼，然后运用到个人的生活和工作中 \u003c/p>\u003cp>拆书帮\u003c/p>\u003cp>拆书帮是拆书家和学习者们以RIA便签法为基础，相互陪伴、共同学习的平台，它是非营利性青年自发组织，在全球共有63个正式分舵，14个筹备分舵\u003c/p>\u003cp>拆书帮的使命：培养拆书家，释放拆书家能量，通过相互陪伴、助人达己提升拆书家们的学习力\u003c/p>\u003cp>拆书帮的愿景：帮助拆书家们提升学习力和促进他人学习的能力，影响身边人，让世界更和谐美好\u003c/p>\u003cp>拆书帮价值观：陪伴赋能、拆为己用、反求诸己、持续精进、共同成长\u003c/p>","ratings_count":1,"texts":[{"id":22383,"quote":"\u003cp>好，现在大家花1-2分钟时间看一下这个片段\u003c/p>\u003cp>\u003cstrong>R：MTV法介绍自己 拆页来源《爆款写作课》\u003c/strong>\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp> M是英文单词Me的缩写，意思是你是谁?\u003c/p>\u003cp> T是英文单词Thing的缩写，意思是你做过什么成就事件?\u003c/p>\u003cp> V是单词Value的缩写，意思是你能提供什么价值?\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询:\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲?\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣?\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己?\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产;读书很厉害的朋友可以帮助提高阅读速度;跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌\u003c/p>","explains":"\u003cp>\u003cstrong>what\u003c/strong>\u003c/p>\u003cp>通过MTV法介绍自己，可以简单、清晰、快速的传达你的能力和价值信息，迅速拉近彼此的距离，链接到有意愿、同频的小伙伴\u003c/p>\u003cp>\u003cstrong>why\u003c/strong>\u003c/p>\u003cp>想更自信的展现自己，让他人了解我和他的链接点，未来可以在哪类事情上共同交流学习，从而产生主动链接的意愿\u003c/p>\u003cp>\u003cstrong>how\u003c/strong>\u003c/p>\u003cp>MTV自我介绍三步骤：\u003c/p>\u003cp> - Me-我是谁，如：大家好，我是刘君\u003c/p>\u003cp> - Thing-我的能力或成就事件，如：我非常擅长物品的极简、断舍离以及收纳\u003c/p>\u003cp> - Value-我能提供什么价值，如：如果家里物品总是很多、也乱乱的，不知道如何收拾，无从下手，我可以为你提供系统断舍离的方法和建议\u003c/p>\u003cp>\u003cstrong>where\u003c/strong>\u003c/p>\u003cp>适合职场或陌生社交场景下使用，如线上的培训、交流会等，如果是闲聊或相亲等就不太适合\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验】\u003c/strong>\u003c/p>\u003cp>记得去年底参加一个线上培训课程，大家的自我介绍都非常的亮眼，而我的却非常简单，导致后面的学习都不太好意思发表观点，在群里也没什么存在感，自信心也受到影响_x005f\u000b\u000b反思：\u000b 现在想来，我因不太会挖掘自己的价值，总觉得那些都不值一提，只是简单的介绍了我是谁\u000b但今天运用MTV自我介绍法，一口气就写出了自己的价值所在，而且写出来后自我满足感大大提升\u000b后面我还要不断的深挖自己的价值，现在写作业时又发现了我还有创业经验和销售技巧方面的价值，如果继续不断深挖，应该还有很多。然后挑选最能帮助别人的，构建我的自我介绍，这样下次就可以直接展示，链接同频的小伙伴了\u003c/p>\u003cp>\u003cstrong>【A2催化应用】\u003c/strong>\u003c/p>\u003cp>目标：\u003c/p>\u003cp> 在9.10日参加的《自我关怀》课程训练营里，使用MTV介绍法进行自我介绍\u003c/p>\u003cp>行动计划：\u003c/p>\u003cp> 1.不断深挖自己的价值，完善自我介绍\u003c/p>\u003cp> 2.将群里小伙伴们的自我介绍，运用便签法拆为己用\u003c/p>\u003cp> 3.对内容进行精炼，选择适合这个场景的价值\u003c/p>\u003cp> 4.找一个APP，制作一份有设计感的电子版自我介绍，提升阅读愉悦度\u003c/p>\u003cp>我今天的分享就到这里，谢谢大家能抽出时间来参与！感恩！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1727513154000,"updated_at":1728791118000,"ria":true},{"id":18086,"topic":"MTV自我介绍法","learn_goal":"","remark":"致用类","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"louis0325","city":"东莞市"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>\u003cstrong>自我介绍\u003c/strong>：大家好，我是拆书帮东莞乐享分舵的新会员李小燕，今天要过的是TF1-2。我的三个标签是vivo外销计划总监、得到终身学习者、AACTP认证TTT讲师。\u003c/p>\u003cp>\u003cstrong>图书介绍\u003c/strong>：今天，我为大家带来的拆页来自《爆款写作课》一书。这本书的作者是弗兰克，他详细拆解了爆文的构成元素，手把手教你从选题立意牢牢抓住读者眼球，循序渐进打动和说服读者，最终将文字变现。掌握简单的方法，让你成为新媒体写作高手。这本书得到了秋叶、李海峰、彪悍一只猫、Spenser、彭小六联名推荐，引爆新媒体写作圈。出版时间是2018年11月，出版社是中国友谊出版公司。今天我们主要学习这本书中的一个“MTV&quot;自我介绍法。\u003c/p>\u003cp>\u003cstrong>分组：\u003c/strong>我们今天是线下拆书，按人数平均分成两个组参加接下来的拆书活动。\u003c/p>","ratings_count":1,"texts":[{"id":22335,"quote":"\u003cp>下面请大家花2分钟时间看一下我们今天的片段拆页，一会儿我分享一下关于这个拆页便签，大家看完了可以向我举手示意一下，谢谢。\u003c/p>\u003cp>\u003cstrong>【R原文片段】：MTV法介绍自己\u003c/strong> \u003cstrong>片段来源《爆款写作课》\u003c/strong>\u003c/p>\u003cp> 梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp> V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp> 比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp> 1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp> 2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>好的，我看大家都看完了原文，接下来我来拆解一下，3W1H结构：\u003c/p>\u003cp>\u003cstrong>what:\u003c/strong> MTV法（Me-Thing-Value）作为一种自我介绍的工具，通过清晰、有条理地展现个人信息、成就事件和价值，可以有效地凸显个人的核心竞争力。\u003cbr> \u003cbr> \u003cstrong>why\u003c/strong>:通过这样的介绍，你可以让听众迅速了解你的身份、成就和价值，从而增加他们对你的兴趣和信任。如果不这样介绍，可能会耗时比较久，但仍说不到重点，不能快速建立你与他人的连接。\u003c/p>\u003cp>\u003cstrong> where\u003c/strong>:适用于面试场合、社交活动、商务洽谈、线上社群以及个人品牌塑造等场合；如果你是去亲戚家串门或者相亲什么的就不用这么介绍了。\u003c/p>\u003cp>\u003cstrong>how:\u003c/strong>介绍步骤如下，再详细拆解一下\u003c/p>\u003cp>\u003cstrong> Me:即介绍你是谁\u003c/strong> \u003cstrong>（明确个人身份与定位）\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 基本信息\u003c/strong>：包括姓名、职业、教育背景等，这些是构建个人身份的基础。\u003c/p>\u003cp>\u003cstrong> 独特标签\u003c/strong>：可以加入一些独特的标签或自我定位，如“行业专家”、“创新先锋”等，这些标签有助于听众快速了解你的专业领域或个性特点。\u003c/p>\u003cp>\u003cstrong> 作用：\u003c/strong>明确个人身份与定位，为听众提供一个初步的印象框架，为后续内容的展开奠定基础。\u003cbr> \u003cstrong>举例:\u003c/strong>我是李小燕，vivo外销计划总监，从事供应链管理20余年，同时也是一名AACTP认证讲师。\u003c/p>\u003cp>\u003cstrong> Thing:介绍你的成就事件（展示个人能力与成果）\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 具体成就\u003c/strong>：列举2-3个具体、可量化的成就事件，这些事件应能够体现你的专业能力、创新思维或解决问题的能力。\u003c/p>\u003cp>\u003cstrong> 细节描述\u003c/strong>：在描述成就事件时，可以适当加入一些细节，如项目规模、实施难度、最终成果等，以增强说服力。\u003c/p>\u003cp>\u003cstrong> 作用：\u003c/strong>通过展示个人能力与成果，直接体现你的核心竞争力。成就事件的选择应围绕你的专业领域或目标岗位进行，确保与听众的关注点相契合。\u003cbr> \u003cstrong>举例\u003c/strong>:我2018年成为美国AACTP认证讲师，课程主题是《TTT培训培训师》，我在公司内部培训了上百名来自不同领域，不同部门的学员，辅导他们通关认证成为了内部培训师。\u003c/p>\u003cp>\u003cstrong> value:介绍你能提供的价值（强调个人价值与贡献）\u003c/strong>\u003cbr> \u003cstrong>解决方案\u003c/strong>：针对听众可能面临的问题或需求，提出具体的解决方案或建议，展示你的专业见解和解决问题的能力。\u003c/p>\u003cp>\u003cstrong> 附加价值\u003c/strong>：除了专业技能外，还可以强调你的附加价值，如团队合作精神、创新思维、领导力等，这些都能提升你的综合竞争力。\u003c/p>\u003cp>\u003cstrong> 实际行动\u003c/strong>：可以承诺提供一些具体的帮助或资源，如免费咨询、资料分享等，以展现你的诚意和实用性。\u003c/p>\u003cp>\u003cstrong> 作用：\u003c/strong>强调个人价值与贡献，让听众感受到你的实用性和合作潜力。通过主动提供价值，建立与听众之间的信任与连接，为后续的深入交流或合作打下基础。\u003c/p>\u003cp>\u003cstrong> 举例:\u003c/strong>我加入拆书帮，后续能为大家提供培训师方面的赋能\u003c/p>\u003cp> 1.如何搭建课程结构(编)\u003cbr> 2.如何设计教学流程(导)\u003cbr> 3.运用多种教学方法(演) \u003c/p>\u003cp> 总结：MTV法通过明确个人身份与定位、展示个人能力与成果、强调个人价值与贡献三个步骤，有效地凸显了个人的核心竞争力。在运用MTV法进行自我介绍时，应注意内容的真实性、针对性和吸引力，以确保能够给听众留下深刻而积极的印象。同时，根据不同场合和听众的需求进行适当调整和优化也是非常重要的。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1:激活经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计\u003c/strong>：\u003c/p>\u003cp> 好的，MTV法就介绍完了，大家现在组内分享一下：\u003c/p>\u003cp>“在过去你有自我介绍过吗？当时有没有用到类似的方法，结果如何？”\u003c/p>\u003cp>3分钟时间讨论，现在计时开始。\u003c/p>\u003cp>好的，时间到，现在我们每组邀请一位来分享TA的案例。各1分钟时间\u003c/p>\u003cp>\u003cstrong>学习者案例记录:\u003c/strong>\u003c/p>\u003cp>学员**分享：在之前的自我介绍中仅介绍姓名、职业等基础信息，没有自己的独特标签，也没有成就事件和价值，较难连接到新朋友，后续在商务活动中想要用MTV法来改进自己的自我介绍。\u003c/p>\u003cp>\u003cstrong>A2:催化应用：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计\u003c/strong>：OK，谢谢大家的分享，现在请大家想像一个未来要用到自我介绍的具体场景和具体对象，明确后试着用MTV法来做一下自我介绍，我每人发一张便签，把你们的MTV自我介绍写出来，我翻到前面HOW这一页PPT，大家照着这个顺序的内容要点思考一下自己独特有吸引力的自我介绍，计时2分钟\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>**学员的A2：\u003c/p>\u003cp>目标：在未来1个月内用MTV法向新加微好友介绍自己。\u003c/p>\u003cp>计划：1、在手机的原子笔记中提前编辑好MTV介绍内容。\u003c/p>\u003cp> M:大家好！我是一位从业10年阅读教育的创业者安心。我的标签是少儿阅读指导师、演讲导师。\u003c/p>\u003cp> T：通过用心、专注、专业的服务赢得了上百个家庭的信赖，励志培养上千个书香家庭。\u003c/p>\u003cp> 加入头马国际演讲俱乐部5年，是一名演讲导师，获得过中区冠军。\u003c/p>\u003cp> V: 我能帮助大家做少儿阅读指导，开展演讲工作坊，书籍分享等。\u003c/p>\u003cp> 2、加微信好友时即可直接转发。\u003c/p>\u003cp>\u003cstrong>总结语\u003c/strong>：好的，谢谢大家参加今天的拆书活动，大家赶紧把MTV法用起来，希望你们能连接到更多新朋友、新商机，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1726214965000,"updated_at":1726228055000,"ria":true},{"id":17708,"topic":"爆款写作课教会我如何用MTV法写出眼前一亮的自我介绍","learn_goal":"","remark":"暂无","level":"TF1-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"Minch明奇","city":"无锡市"},"club":{"name":"无锡太湖分舵","city":"无锡"},"prologue":"\u003cp>亲爱的伙伴们，大家晚上好，欢迎来到今天的拆书活动现场。我是刚加入无锡太湖分舵的闵文超，门里一个文的闵，文化的文，超凡的超，我想通过终身学习，成为门里门外都有超凡文化的人。用三个标签介绍我自己：第一个标签，我是2023年7月加入拆书帮，是一名新手拆书家。第二个标签，我是一名IT创业者，负责项目咨询和产品架构，专注于为制造型企业提供信息管理系统解决方案。第三个标签，我是两个不满10岁女童的爸爸，家庭教育和个人成长是我持续学习的课题。\u003c/p>\u003cp>下面我来介绍一下图书，今天的拆页来自《爆款写作课》电子书64到66页，这本书主要论述了新媒体写作技巧，是致用类图书。当下很多人对写作变现很感兴趣，本书介绍通过有亮点的故事、细节、案例的美文，吸引眼球、打动人心，在朋友圈、公众号、小红书等媒体中写作输出。\u003c/p>\u003cp>下面请大家花2分钟的时间阅读一下拆页。\u003c/p>","ratings_count":1,"texts":[{"id":21922,"quote":"\u003cp>【R原文片段】摘自《爆款写作课》电子书P64-P66\u003c/p>\u003cp>\u003cstrong>用MTV 3步法介绍自己\u003c/strong>\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>图 自我介绍的MTV法则\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp>1．普通人如何做出属于自己的歌曲？\u003c/p>\u003cp>2．如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3．个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>现在小伙伴已经示意我读完了，下面我拆解一下原文后，现场人员分成两组，花几分钟简单讨论和共创一下便签。\u003c/p>\u003cp>这个片段讲述了一个做自我介绍的工具，叫MTV法。\u003c/p>\u003cp>来自三个单词的首写字母，即Me(我是谁)、Thing（成就事件）、Value(提供价值)三个单词的首字母。自我介绍的目的，除了让别人了解你之外，还要让听众主动连接你。因此你的自我介绍中要说出你的能力品类和标签，说出让别人信任你的成就事件，说出你能给对方提供什么来创造价值，这三个要素，就相当于树立了你独一无二的品牌，对方能清楚什么事情可以找你协助和支持。\u003c/p>\u003cp>比如制片人可以协助做出歌曲或传授明星包装经验；读书高手可以帮助提高阅读速度；跑步的朋友可以解决跑步的疑惑；做演讲的朋友可以助人提升演讲能力。\u003c/p>\u003cp>回想起我曾经的几次自我介绍经历，有时是把自己的职场经验讲一番，有时是强调自己的爱好，有时是讲了从小时候到长大的故事，或者把曾经获得的奖状报出来，甚至最初像找工作简历一样，把报户口类似的信息一一罗列出来。学习完MTV法介绍自己，可以按这三个关键词，依次展开，M是描述我的基本信息、多重标签、所处平台。T是讲述近来最有成就的一两件相关联的事件，按讲故的要素，让听众真实信任，产生共鸣。V是我有哪些优势，能给对方提供哪些价值。\u003c/p>\u003cp>在一次沙龙活动应用MTV法的好机会。我提前准备一下自我介绍的关键词按这个框架进行。M：软件项目经理、产品经理、马拉松爱好者、读者等多重标签。T：成就事件是我的团队接到一个支援项目，专门要协助解决疑难问题，最后我们连续熬夜成功上线，也收到了客户盖章和通报的表扬信。V：如果一位职场新人想了解软件实施工程师这个岗位的相关事项，如果一家制造型企业要选型管理软件系统，如果一个在建软件项目遇到了难题，如果一位老板想规划一个新厂房，我可以提供这几个话题的一对一解答。\u003c/p>\u003cp>下一个环节，我们以座位分成1组和2组，接下来请大家各自用MTV法写出3个便签，写完后在小组中交流一下，每组派一个代表分享。 \u003c/p>","interaction":"\u003cp>学习者海燕通过拆书片段的学习，运用MTV法做了简短的自我介绍。她的现场分享，M：她是两位孩子的妈妈，是一位高级家庭教育指导师；T：比较有成就的事情是，从以前的教育方法不太好，与老大的关系有点紧张，通过学习后，与孩子关系特别好，孩子也愿意主动和她分享，孩子整个学习和精神状态特别好。V：可以给大家提供的价值是，如果有对亲子关系的处理、或者家庭教育上有什么疑问可以链接一下，她能给出一些经过验证有效的做法和建议。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1717752477000,"updated_at":1717767389000,"ria":true},{"id":17693,"topic":"自我介绍","learn_goal":"","remark":"无","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"阅苏张庆磊","city":"苏州市"},"club":{"name":"苏州阅苏分舵","city":"苏州"},"prologue":"\u003cp>环节1，自我介绍，1分钟，大家好，我叫张庆磊，我有三个标签。第1个标签是工厂工人，是我现在的职业。第2个标签是终身学习者，我马上就要退休了，想转型做自由职业者，最大的爱好就是读书，想把我打造成一个读书Ip，也报了自考南京师范大学汉语言文学专业的课程。我的第三个标签是未来的三级拆书家，为了把读的书都能为我所用，我加入了拆书帮，我是未来的三级拆书家。\u003c/p>\u003cp>环节2，拆书帮介绍，2分钟，先说拆书，拆是拆解的意思，是把书里的知识，拆为己用，是成人学习的方法论。为了解决我们的实际问题。拆书帮拆书选择致用类和实用类的书。拆书法按应用的对象分两种，一种是个人学习时用的方法叫拆书帮便签读书法，一种是组织学习时用的方法叫拆书帮现场学习法，也叫R|A现场学习法。R意思是阅读原文拆页。|意思是讲解引导。A意思是拆为己用。拆书帮是拆书法学习爱好者的社群，各地有分舵，是非营利性的青年自组织。拆书帮的使命是致力于培养拆书家，让拆书家赋能身边的学习爱好者，既帮助别人又提升自己。拆书帮愿景是，帮助拆书家们升级学习力及促进他人的学习能力，影响身边的人，让世界变得更好一点。拆书帮的价值观是，陪伴赋能，拆为己用，反求诸己，持续精进，共同成长。\u003c/p>\u003cp>过渡语，现在我拆的是《爆款写作课》这本书的片段，MTV法介绍自己。\u003c/p>\u003cp>环节3，R阅读原文拆页，1一2分钟，\u003c/p>\u003cp>接下来，邀请大家一起阅读一下原文片段，时间是2分钟，请大家阅读后放下我便知道大家的进度：\u003c/p>","ratings_count":1,"texts":[{"id":21902,"quote":"\u003cp>R：MTV法介绍自己 片段来源《爆款写作课》\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp> V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp> 比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp> 1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp> 2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>好，我看大家都读完了，下面我来说一说这段话的意思，分了四部分what、why、How.where。\u003c/p>\u003cp>环节4，I便签，what，MTV自己介绍法就是介绍自己时，按我是谁，我的最大成就，我能提供什么价值，这个步骤自我介绍。这样自我介绍相互坦诚，能让对方快速了解我的价值，主动链接我。\u003c/p>\u003cp>way，用MTV介绍法自我介绍，是为了打造个人品牌，让对方愿意去链接你，在现在互联网时代，不发声等于不发生，人人要打造个人品牌，经历了三年疫情，我们都认识到副业的重要性，凯文凯利说，未来你只要有一千个铁粉，就可以衣食无忧了。所以我现在说的这个自我介绍的方法是大家的刚需，因为这个方法可以最好的展示你的成就和你能提供的价值，让对方主动要链接你。\u003c/p>\u003cp>How，第一步M先说我是谁，我的身份，我现在的本职工作，第二步T，介绍我有哪些专业技能，我有哪些成就。第三步V，我能给别人提供什么价值。用这三个步骤介绍自己。\u003c/p>\u003cp>where，这个方法适用场景主要是人多的公众场合，用简短的发言，给在场的人留下深刻印象，在人多的公众场合，你有发言的机会时，开场破冰先做自我介绍，就适合用MTV自我介绍法。象同学、家庭聚餐就不太适合了。\u003c/p>","interaction":"\u003cp>\u003cbr>环节5，A1便签\u003c/p>\u003cp>记得上次在2月25号，拆书帮线下活动时，石婷婷教练也是开场让我们自我介绍，她就是给出MTV这3个问题，现场有一个小伙伴，我印象最深。\u003c/p>\u003cp>她的自我介绍是这样：第一句M，“我排行老三，因为平时比较爷们，网名就叫三爷，是自由职业者。”\u003c/p>\u003cp>第二句T，\u003c/p>\u003cp>我运营着一个公众号，专门写做ppt和演讲方面的内容，我写了一本关于演讲的书，这本书一年卖了一万多册。\u003c/p>\u003cp>第三句V，“我能提供的价值有：①演讲培训，给公司员工培训演讲技能。②就是做PPT，给公司或个人做PPT。”\u003c/p>\u003cp>经过三爷这样的自我介绍，我们在场的小伙伴都想加她微信，向她学习，她就是用MTV法成功打造了个人品牌，让大家很快了解她，知道了她的价值。\u003c/p>\u003cp>当天回家的路上，我反思，在当今互联网时代，每个人都要做Ip，你的差异化能力就是你的产品，产品就是品牌。我也要用MTV介绍法打造个人品牌。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":21903,"quote":"\u003cp>环节3，R阅读原文拆页，1一2分钟，\u003c/p>\u003cp>接下来，邀请大家一起阅读一下原文片段，时间是2分钟，请大家阅读后放下我便知道大家的进度：\u003c/p>\u003cp>R：MTV法介绍自己 片段来源《爆款写作课》\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>好，我看大家都读完了，下面我来说一说这段话的意思，分了四部分what、why、How.where。\u003c/p>\u003cp>环节4，I便签，what，MTV自己介绍法就是介绍自己时，按我是谁，我的最大成就，我能提供什么价值，这个步骤自我介绍。这样自我介绍相互坦诚，能让对方快速了解我的价值，主动链接我。\u003c/p>\u003cp>way，用MTV介绍法自我介绍，是为了打造个人品牌，让对方愿意去链接你，在现在互联网时代，不发声等于不发生，人人要打造个人品牌，经历了三年疫情，我们都认识到副业的重要性，凯文凯利说，未来你只要有一千个铁粉，就可以衣食无忧了。所以我现在说的这个自我介绍的方法是大家的刚需，因为这个方法可以最好的展示你的成就和你能提供的价值，让对方主动要链接你。\u003c/p>\u003cp>How，第一步M先说我是谁，我的身份，我现在的本职工作，第二步T，介绍我有哪些专业技能，我有哪些成就。第三步V，我能给别人提供什么价值。用这三个步骤介绍自己。\u003c/p>\u003cp>where，这个方法适用场景主要是人多的公众场合，用简短的发言，给在场的人留下深刻印象，在人多的公众场合，你有发言的机会时，开场破冰先做自我介绍，就适合用MTV自我介绍法。象同学、家庭聚餐就不太适合了。\u003c/p>","interaction":"\u003cp>\u003cbr>环节5，A1便签\u003c/p>\u003cp>记得上次在2月25号，拆书帮线下活动时，石婷婷教练也是开场让我们自我介绍，她就是给出MTV这3个问题，现场有一个小伙伴，我印象最深。\u003c/p>\u003cp>她的自我介绍是这样：第一句M，“我排行老三，因为平时比较爷们，网名就叫三爷，是自由职业者。”\u003c/p>\u003cp>第二句T，\u003c/p>\u003cp>我运营着一个公众号，专门写做ppt和演讲方面的内容，我写了一本关于演讲的书，这本书一年卖了一万多册。\u003c/p>\u003cp>第三句V，“我能提供的价值有：①演讲培训，给公司员工培训演讲技能。②就是做PPT，给公司或个人做PPT。”\u003c/p>\u003cp>经过三爷这样的自我介绍，我们在场的小伙伴都想加她微信，向她学习，她就是用MTV法成功打造了个人品牌，让大家很快了解她，知道了她的价值。\u003c/p>\u003cp>当天回家的路上，我反思，在当今互联网时代，每个人都要做Ip，你的差异化能力就是你的产品，产品就是品牌。我也要用MTV介绍法打造个人品牌。\u003c/p>\u003cp>环节6，A2便签\u003c/p>\u003cp>学了MTV介绍法，我也订了目标，要打造我的个人品牌，我在参加拆书帮活动时，就用MTV法介绍自己。那我再梳理一下我是谁，就是我的本职工作和我的身份，我认为我的成就有哪些，我能提供什么价值。我再介绍一下自己。\u003c/p>\u003cp>我是普通工人，马上退休了，想做自由职业者，最大爱好是读书写作。\u003c/p>\u003cp>我做自媒体三年多了，最早在头条号，这几年为退休了转型，我报了专本套读，本科南京师范大学汉语言文学专业，为学写作也报了几次课程，主要是写书评。我2020年开始写头条号，有一个问答涨了100多个粉丝。\u003c/p>\u003cp>我能提供的价值：1.自考考试通过，目前考过了几科，总结了些方法。2.做自媒体的经验。\u003c/p>\u003cp>我给我的期待是5个月，8月份退休后到春节前，把自媒体帐号做起来。\u003c/p>\u003cp>衡量标准：视频号粉丝过百，开通创作者计划。\u003c/p>\u003cp>结束语，今天拆书就是学习了MTV法介绍自己，这个方法是为打造个人品牌，今天我的发言完了。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1717408035000,"updated_at":1717475782000,"ria":true},{"id":17643,"topic":"通过MTV法自我介绍，快速与人留下影响并建立链接","learn_goal":"","remark":"通过MTV法自我介绍，快速与人留下影响并建立链接","level":"TF1-2","duration":20,"status":19,"type":0,"chaishujia":{"username":"卓越影响者","city":"广州"},"club":{"name":"广州大湾区分舵","city":"广州"},"prologue":"\u003cp>\u003cstrong>【自我介绍】1分钟\u003c/strong>\u003c/p>\u003cp>    大家好，我是今天的拆书人，我叫李东华，小李飞刀的李，东方不败的东，中华英雄的华。\u003c/p>\u003cp>   我有三个标签：\u003c/p>\u003cp>   “终生学习者”，我每年看50本书；\u003c/p>\u003cp>   “向内探索者”，坚持正念冥想，每天坚持正念冥想15分钟；\u003c/p>\u003cp>   “卓越影响者”，我是我们公司的内训师，我希望被卓越的人影响，也希望影响身边的人变得卓越。所以我才加入了拆书帮，我觉得拆书帮的人都是这样能量满满的人。\u003c/p>\u003cp>   我有一整套关于自我学习成长的思维模型，它让我从一个内向抑郁的人变成一个外向社牛。所以感兴趣的人可以找我互相交流，共同成长哦。\u003c/p>\u003cp>\u003cstrong>【过渡语&amp;分组】1分钟\u003c/strong>\u003c/p>\u003cp>    我今天拆解的书籍是：《爆款写作课》，学习目标是通过本次学习，可以懂得在自我介绍的时候，可以用到我们这个方法，在短时间内就获得认可和关注，快速建立链接。我们这本书是作者花了三年潜心钻研的写作章法。他自创了新媒体写作的三步法：吸引、打动、说服。这个MTV法就是其中的一个章节，一个套路。非常的实用，我用了以后真的收获良多。\u003c/p>\u003cp>    那行，那我们进入下一个环节。我们来一起阅读原文的拆页。给大家两分钟时间。在阅读拆页之前，我们要先分个小组，因为我们今天来的人比较少，我们就共同在1个小组内。因为阅读完后，有个小训练。两分钟阅读完的同学，可以在评论区上回复个1，或者直接告诉我，已经阅读完。\u003c/p>","ratings_count":1,"texts":[{"id":21844,"quote":"\u003cp>\u003cstrong>【R：阅读原文片段】2分钟 自我介绍的MTV法 \u003c/strong>\u003c/p>\u003cp>片段来源：《爆款写作课》（电子书P33-P34）\u003c/p>\u003cp> 做自我介绍，其实就是一个做减法的过程，在过去的经历中，找到最亮点的成就事件，找到关键数据做支撑，然后尝试和对方连接。\u003c/p>\u003cp> 用MTV 3步法介绍自己。\u003c/p>\u003cp> 梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp> 但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp> 这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cul>\u003cli> M是英文单词Me的缩写，意思是你是谁?\u003c/li>\u003cli> T是英文单词Thing的缩写，意思是你做过什么成就事件?\u003c/li>\u003cli> V是单词Value的缩写，意思是你能提供什么价值?\u003c/li>\u003c/ul>\u003cp> 这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp> 比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询:\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲?\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣?\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己?\u003c/p>\u003cp> 当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。理财的朋友可以协助配置家庭资产;读书很厉害的朋友可以帮助提高阅读速度;跑步的朋友可以解答坚持跑步过程中的疑惑;做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp> 当我们在自我介绍中说出能力(品类和标签)，说出成就事件(信任状)，说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>\u003cstrong>【I重述知识点】 4分钟\u003c/strong>\u003c/p>\u003cp>  我们阅读原文已经阅读完了，那接下来我来简单介绍一下MTV法。这个MTV法，其实非常的简单，只要三步就可以了。\u003c/p>\u003cp>   首先就是简单的清晰介绍自己，并梳理出自己的成就事件。比如说，我去年在我们省公司的参加会议的时候。我就是不经意的用到了方法（当时还没有学过这个方法）。我不经意的说了，我是全广州最牛的销售冠军。只要跟我合作过的伙伴都对我非常的认可。只要他愿意跟我合作，我从注册营业执照到随后的服务，最后他就是不够钱去做业务了，我甚至连贷款都可以帮跟他介绍好。他们听完后很感兴趣，会后很多人都主动来加我的微信。甚至就是坐的离我比较远的，都会跟我广州的同事打听说那个是不是你们公司的，这么牛。当时我只是不经意用到了这个方式，我就加了很多好友，收获了我很多的人脉。那今天我系统学完后，这个知识点会变得更加实用，所以要推荐给大家哈。\u003c/p>\u003cp>\u003cstrong>为什么要用到这个MTV法？\u003c/strong>\u003c/p>\u003cp>    因为在短时间内，你就能达到自我展现的效果，区分出自我和人群，就能吸引到同类别的朋友来进行互关。\u003c/p>\u003cp>\u003cstrong>在什么情况下可以用这种方法？\u003c/strong>\u003c/p>\u003cp>   一群人自我介绍的时候，这个环节非常的适用。比如说我们拆书帮这种活动，还有我们刚入职到一个新公司的时候，跟同事跟领导的自我介绍，都可以用这个方法。可以在很短的时间内就破冰，给对方留下印象。然后只要对你感兴趣的人，或者同类的人都会跟你进行自动链接。\u003c/p>\u003cp>\u003cstrong>这个方法怎么用？\u003c/strong>\u003c/p>\u003cp>    就这么简单，三步：\u003c/p>\u003cp>    第一步就是M，M就是Me，就是我是谁。比如说，我自我介绍时候说:“大家好，我是李东华，我和三生三世十里桃花的东华帝君，是一模一样的名字。所以你看到东华帝君,就会想到我的名字”。你看，所以你要把你的名字把它美化一下，链接诗词也好，链接一些关键热点什么都行，这样子容易被人记住你的名字。\u003c/p>\u003cp>    第二步就是T，T就是你要说出你做过最有成就的事情。比如说：“我是做过大市场销售的，我是销售冠军。我们公司的同事是怎么评价我的？说我是薪价比最高的人。你看我平时没怎么工作，但是我工资很高，然后我长期蝉联销冠，我们公司领导对我也很认可，因为我把握着我们行业80%的大客户，他们都愿意跟我合作”。 \u003c/p>\u003cp>    第三步就是V，你要讲出你对别人有什么样的价值？我就说我是很喜欢交朋友的，我可以帮你快速的建立市场关系，我的人脉可以介绍给你，你也很快可以达到销售目标，完成你的销售业绩。只要你是对别人有帮助，有价值的，人家就愿意交你这个朋友。\u003c/p>\u003cp>\u003cstrong>注意！\u003c/strong>\u003c/p>\u003cp>     当然，有一个点要特别注意的是，这个方法是不适合向长辈领导介绍的。因为你的长辈，你的领导听说你很厉害，那就会觉得你在班门弄斧。这点要特别注意。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1联系具体经验】1分钟\u003c/strong>\u003cbr>\u003c/p>\u003cp>    我为什么觉得非常好用，因为我想起刚入职的时候，遇到一个很尴尬的事情，我们领导让我自我介绍，我就很急速的站起来，简单说一下，“我叫李东华，我来自潮汕，我喜欢看书，然后很高兴认识大家，请大家多多指教，谢谢！”。匆匆的就结束了话题。就仅此而已，为什么，因为我就觉得轮到我了，我赶紧把它讲完，然后就是留给下一个人，就好像击鼓传花一样，不想给自己太大的压力。但是我讲完，我发现现场有很多人也是学我这样子讲。讲完后，会议一结束，自我介绍一结束，根本记不住谁打谁，谁是谁，我也记不住。当然我也相信人家也记不住我。所以我觉得这种方法不好。\u003c/p>\u003cp> 当我学完MTV法后，我就觉得当时太年轻了。反思一下，我当时就是真的是太紧张了，老是想着完成任务，把自我介绍当成一个任务，就想着静静的做个美男子。这样子浪费了很多机会。\u003c/p>\u003cp>\u003cstrong>【分组分享】3分钟\u003c/strong>\u003c/p>\u003cp>   那我也讲了我的经历，接下来，我想问一下各位，有没有像我这样类似的经历，就是在你做自我介绍的时候，你当时是怎么做的？有没有成功的，失败的都可以。可以在群上分享一下！ㅤㅤ\u003c/p>\u003cp>    哪位同学来试一下？\u003c/p>\u003cp>    好，谢谢两位小同学，因为你们的经历，我也切身经历过。特别现在像我作为公司的小主管，我开始招人的时候，我也会留意，一群人自我面试完，或者自我介绍完。他如果说出他特别牛逼，比如说他会做PPT、会做数据匹配，那我就愿意多给他点机会；如果他说他认识很多人脉，那我也会主动说，要不我们一起拜访一下你的人脉，那他的机会也就多一点。回想我当年跟两位小伙伴一样，真的是错失了很多机会的。\u003c/p>\u003cp>\u003cstrong>【A2具体应用】9分钟\u003c/strong>\u003c/p>\u003cp> 我们刚刚学会了一些新的自我介绍法，用“MTV法”自我介绍，也联系了过去。接下来，我们要把这个方法应用到实际的生活中面去。 \u003c/p>\u003cp>\u003cstrong>（目标）：\u003c/strong>\u003c/p>\u003cp> 比如说我给自己设定了一个目标，我的目标很简单，以后在每次聚会的时候，我要通过的MTV法做自我介绍，至少会有三到五个人会主动加我的微信，表达想跟我认识的要求。我的目标是可以量化的，而且在行动的时候，我会用MTV法，在不同场合，多准备几套自我介绍的内容。\u003c/p>\u003cp>\u003cstrong>（行动）：\u003c/strong>\u003c/p>\u003cp>   就拿我的公司来说，我们是一家国企，所以我对政府机关打交道的时候，我的名片跟自我介绍都是说是“分局主任”。如果我是在做市场对商界，那我说是“区域总经理”，不同场合用不同名片去介绍，这样子能快速获取亲近的认同感，能够收获人脉跟提高合作几率。不能说拿一套自我介绍到处都用，会很尴尬的。\u003c/p>\u003cp>    我来举个例子哈：\u003c/p>\u003cp>\u003cstrong>（第一套\u003c/strong>）\u003cstrong>： \u003c/strong> \u003c/p>\u003cp> 比如说我做市场的时候，对着我们这个行业,对我的合作伙伴做自我介绍的时候.我就会这样说，我说:“大家好，我是番禺南村区域的市场部经理，我叫李东华。李是小李飞刀，东是东方不败的东，华是中华英雄的华，这是我的名字”。我把我的名字跟三个武侠高手挂钩在一起了。然后我下一句我就会说：“我不是武侠高手，但我是实实在在的大市场高手”。这里一跳过来，就说明我是有自己能力的，我有什么样的成就哈：“我不但是大市场高手，我是广州排名第一的分局，我有很多的大客户资源，广州超过十家门店的大客户，有七成都会认识我，有五成都跟我合作，为什么？因为我会讲粤语，我会讲客家话，我会讲潮汕话，所以客户有三分之二都是我老乡”，那我这样一讲，人家一听。就会觉得：“华哥还是蛮优秀，很有成就，他做的那么厉害，如果我认识他，我可以在市场上得到他的帮助，或者跟他一起发展”。那这是一种把成就给展现出来。那么第三个，我要体现我的价值了，那我就说：“我非常喜欢交朋友，如果有需要我牵头认识的，我可以跟你一起去拜访，把我的客户介绍给你，因为朋友多了路好走，所以可以让你轻松的获得人脉，达成销售业绩”。那这是工作上面的。\u003c/p>\u003cp>\u003cstrong>（第二套\u003c/strong>）\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>    当然,如果说我现在跟拆书帮的朋友做自我介绍，我就会用我准备的第二套，因为我们不能说拿着公司内部的工作来对我们朋友或者是拆书帮的小伙伴这样介绍。我会这样子介绍：“大家好，我叫李东华看过三生三世十里桃花的，都知道里面有个东华帝君，名字是跟我一样的，虽然我没人家那么帅哈，但是他们都知道，看到我都会叫我东华帝君，所以名字也是很好记。那我有三个标签”。三个标签，我第一个标说我是终身学习者，我每年看50本书。第二个标签说我是向内探索者，坚持正念冥想心理纠偏。这里要特别“注意”一下，因为我开头的自我介绍的时候，我特意没有讲我的成就。那我这里就会说，“我学过正念冥想。我的心理方面非常强大，我曾经帮助我四名同事走出了抑郁。走出了忧郁，然后迈向新的人生”。那这就是成就了。注意哦，你说你是向内探索者也好，但是你没有成就，那我这里就会补充一下。那我第三个说我是卓越影响者，当时说我是个内训师，但也没有说我内训的成就。这点是不对的，在这里我要补充一下：你要说你是内训师，就必须是什么样的成就，比如：“我给公司1000多号人讲过培训，我是省级的十优讲师，同时我是集团级别的训战师”。这样讲，就有个成在里面。听到这里，就会有学员觉得，嗯，这个培训讲师还可以。\u003c/p>\u003cp>ㅤㅤ\u003c/p>\u003cp>   最后，我说：“我有一套关于自我学习的思维模型，它是可以让一个内向忧郁的人变成一个外向社牛。心里面有一些想不开的，或者是平时不开心的事情，都可以跟我交流，因为我是切切实的用过学过。甚至我经历过，我知道怎么走出来，怎么去开解自己。我也可以帮到你，共同成长”。注意了，从头到尾我是用了两套方案。你们也可以用两到三套、用四套都行，最重要是学会用MTV法如何的自我介绍。\u003c/p>\u003cp>ㅤㅤ\u003c/p>\u003cp>   事例也讲完了。接下来有个小小应用参与，需要小伙伴们来参加一下。你们就用我们学过的MTV法，也根据我讲过的一些注意事项，注意不要踩雷。来做一个自我的介绍。要注意标签是标签，它并不是成就。比如说小月月就给过我一个的感触，是很大的。她当时自我介绍的时候，说她是一个户外徒步爱好者，诶，这个是一个标签。但是她说她跑过全国多少个地方。我一听，这就是成就了。我听完后我回想我自己省外去过得地方很少，然后我就非常佩服她，我就想加她做好朋友，以后跟她要攻略。可以借鉴一下，成就跟标签是不一样的，这点要特别注意。来，给大家两分钟时间，等会我请一到两位小伙伴来分享一下好不好，来，开始吧！\u003c/p>\u003cp>\u003cstrong>【结束语】1分钟\u003c/strong>\u003c/p>\u003cp>    谢谢大家的聆听，今天我的拆业“MTV法”，如何介绍自己，就讲到这里。也希望大家能够通过今天的学习和应用，在以后的生活工作上能用上，给对方、给你想要介绍的人留下深刻的印象，并建立链接，打造自己的人脉宇宙。我的1-2晋级就到这里，感谢大家参与！谢谢。\u003c/p>\u003cp> 请各位小伙伴给洋葱跟苹果也请观察者给我一个点评，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1716452294000,"updated_at":1740649840000,"ria":true},{"id":17517,"topic":"MTV法介绍自己","learn_goal":"","remark":" 通过MTV法来介绍让对方一目了然知道自己是谁、能做什么、能够提供什么价值。通过这个方法，可以将自我物化，把自己想象成是别人的“神助攻”，你能帮他做什么，这就是自我介绍的过程，两个人刚开始认识时，最重要的记忆点，也就是价值。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"李素芬","city":"深圳市"},"club":{"name":"深圳智成分舵","city":"深圳"},"prologue":"\u003cp>各位老师、伙伴们，大家好，我叫李素芬，大家可以叫我瘦芬。 首先我用三个标签做个简单的自我介绍，让大家对于我这个新手拆书家有一个了解：\u003c/p>\u003cp>1、积极向阳的职场人\u003c/p>\u003cp>既要照顾眼前的苟且，也要让自己走向未来诗和远方的田野。\u003c/p>\u003cp>2、保持好奇的培训者\u003c/p>\u003cp>这个标签主要是源于我的工作，我是一位企业内训师，主要工作是迭代核心岗位课程和专注于人才发展。\u003c/p>\u003cp>3、陪伴成长二胎宝妈\u003c/p>\u003cp>拆书家新手，目前正在过1-1的级别，希望自己能够顺利成为一名三级拆书家。\u003c/p>\u003cp>很开心加入智行这个大家庭，认识这么多爱学习有能量的伙伴们！\u003c/p>\u003cp>接下来，我将把今天分享的内容分为两部分进行：\u003c/p>\u003cp>第一部分是：介绍，介绍什么呢？介绍拆书和拆书帮；\u003c/p>\u003cp>第二部分是：拆书，拆一个阅读书片断。\u003c/p>\u003cp>整个拆书流程大概需要和大家一起15分钟。\u003c/p>\u003cp>首先我来介绍一下，什么是“拆书”，什么又是“拆书帮”。拆书法和拆书帮是有专利的。\u003c/p>\u003cp>\u003cstrong>“拆书”\u003c/strong>\u003c/p>\u003cp>“拆书“不是“把书给拆开”，而是将书“拆为己用”。“拆书“是一种学习方法论，适用于以提升自身能力、解决问题为目标的成人学习，强调了以学习者为中心了而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。\u003c/p>\u003cp>\u003cstrong>“拆书帮“\u003c/strong>是基于拆书法的学习爱好者社群，是非营利性青年组织，拆书帮在全国各地设有拆书帮分舵，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>\u003cstrong>“拆书法“\u003c/strong>分为个人学习的拆书法和组织学习的拆书法：\u003c/p>\u003cp>个人学习的拆书法也就是便签法，也就是让人读一本书就能达到参加同主题培训的效果；\u003c/p>\u003cp>组织学习的拆书法是指一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp>拆书法也叫RIA便签阅读法，是拆书帮帮主赵周老师提出的一种符合成人学习的科学阅读方法。\u003c/p>\u003cp>\u003cstrong>RIA便签法\u003c/strong>\u003c/p>\u003cp>是拆书法的核心，第一个字母R是Reading的缩写，指的是阅读原书拆页；第二个字母I是interpretation的缩写，指用自己的语言重述原拆书片断的讲解及引导，尽量用自己的语言。第三个字母A是Appropriation的缩写，拆为已用。要如何达到拆为已用呢，A便签又分为A1激活学习者经验及A2催化学习者应用。A1描述的是自己的相关经验。在这件事上我经历过哪些？听说过哪些，见过哪些相关的、类似的、差不多的情况……越具体越好，把回忆到的经验写下来。【A2】则是规划自己的应用，规划的时候考虑目标、行动，我具体要做什么？要达成什么样的目标，怎么做，可以解决什么问题……。\u003c/p>\u003cp>拆书帮是一个非常有爱、有温度、彼此赋能的学习爱好者社群，截止至今，目前在全国60多个城市，共有88多个拆书帮分舵，2600多名会员。如果想要系统学习拆书法，欢迎加入拆书帮，大家一起学习。\u003c/p>","ratings_count":1,"texts":[{"id":21704,"quote":"\u003cp>\u003cstrong>接下来，邀请大家一起阅读一下原文片段，时间是2分钟，请大家阅读后放下我便知道大家的进度：\u003c/strong>\u003c/p>\u003cp>R：MTV法介绍自己 片段来源《爆款写作课》\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>\u003cstrong>M是英文单词Me的缩写，意思是你是谁？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>V是单词Value的缩写，意思是你能提供什么价值？\u003c/strong>\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp> 比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp> 1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp> 2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>好的，我们目前已经看到现场的伙伴们都已经阅读完了，那接下来话呢，我将通过我自己对这个片段的理解来去分享。\u003c/p>\u003cp>首先我给大家分享我的&quot;I&quot;便签，它包括WHAT什么，WHY为什么，HOW如何及WHERE适用边界四部分。\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>首先我们先来看一下第1个\u003cstrong>what\u003c/strong>，什么我们要掌握这个MTV法则呢？因为其实大家不难发现哦，MTV法则它看起来是有一个很好的技巧的，就是分别是告诉大家我们的：我们是谁，然后我们成就价值是什么，我们的成就事件是什么？我们给大家带来的价值是什么？片段里面给我们的关键点，那如果掌握了MTV法则，对我们来说自己有什么好处呢？那肯定是可以告诉我们在任何场合里面可以很好的把自己自我介绍进行得更有价值。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong> \u003c/p>\u003cp>那第2个就是why，为什么我要进行自我介绍啊，那其实现场可能会有宝妈宝爸啦，还有我们的职场人员等，那我们会有不同的角色在，在不同的角色和不同场合的时候，我们要进行自我介绍，肯定会有不同的方式，那我拿自己来举例子啊，比如说我在刚进一个微信社群里面，做自我介绍的时候，我以前可能会说啊大家好，我是一个有温度的培训人，我叫李素芬，很高兴认识大家啊。\u003c/p>\u003cp>这是以前我的自我介绍，那再比如说我以前来参加我们拆书帮的活动，我可能会用三个标签自我自我介绍了，我可能就会说：大家好，我是李素芬，一名新手拆书家很开心认识大家。\u003c/p>\u003cp>那过往这种场景呢，常常会让你做完自我介绍以后。觉得天哪，我刚刚在吵架，好像没有吵好，为什么呢？因为我觉得我的我的自我介绍我是没有很好的抓住听众的1~2分钟的时间，那如何能好呢？\u003c/p>\u003cp>我今天要分享的MTV法则就是可以很好的进行自我介绍的方法。\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003c/p>\u003cp>首先，我们先来看下什么是“MTV法则”？\u003c/p>\u003cp>MTV是三个英文单词的缩写，分别是：Me、Thing、Value。在MTV法则中：\u003c/p>\u003cp>M是Me，我是谁。\u003c/p>\u003cp>T是Task，我做过的成就事件。\u003c/p>\u003cp>V是Value，我能够给你带来什么价值/帮助。\u003c/p>\u003cp>我们可以回顾自己的成就事件和罗列出自己能够给对方/组织带来的价值/帮助。通过MTV法则筛选出适当的素材，并按照顺序排好，来做自我介绍。当然，这些也可以梳理后放在你大脑的知识库，根据不同场景时，筛选应用。\u003c/p>\u003cp> \u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp>通过这个方法，可以将自我物化，把自己想象成是别人的“神助攻”，你能帮他做什么，这就是自我介绍的过程，两个人刚开始认识时，最重要的记忆点，也就是价值。而这个价值并不是凭空想象的，而是通过T体现出来的。我学完MTV这个片段以后，给我的感觉就是我的自我介绍，适用边界会有更多的场景，并且更容易我们的听众有很好的一个记忆点。\u003c/p>","interaction":"\u003cp>A1便签：\u003c/p>\u003cp>回想起自己每次新进社群或是参加现场分享会时自我介绍的发言：\u003c/p>\u003cp>大家好，我叫李素芬，坐标深圳，从事培训管理工作，一位零售行业有温度的培训人。我能给大家提供给零售培训相关内容交流。欢迎同行交流，谢谢大家！\u003c/p>\u003cp>现在想想当时的自我介绍，虽然在不同的群是有不同的问候方式进行开场问好，不过和MTV法比起来，内容逊色多了，既没有记忆点，也没有突出自己的价值，更没脱颖而出，怎能让人记住？\u003c/p>\u003cp>通过我对比自己过去的自我介绍进行了反思：\u003c/p>\u003cp>我是个学习盖洛普的爱好实践者，如果大家想发现自己的优势可以与我链接，或者说我是从事培训行业10年的一位培训职场人，如果大家对培训管理，课程迭代，人才发展有兴趣的话，也可以与我链接，或者说我在培训的版块擅长于做破冰和相互融合的过程，如果大家有需要，我也可以给大家分享，那这也是我个人的一些成就事件，那最后一个就是我们的价值，我可以给大家带来什么价值呢？比如说我过往有对100个人以上做过优势的诊断，我每周会进行一次优势例会，那大家如果想发现自己的优势有也可以跟我链接。\u003c/p>\u003cp>通过片段结合自身习惯思考，我决定MTV法运用起来，提升自己自我介绍的价值。\u003c/p>\u003cp>\u003cstrong>A2便签：\u003c/strong>\u003c/p>\u003cp>目标：我将会在未来的两个月内通过MTV法则进行自介绍，链接至少2~3名不同行业的人群，让自己在公众场合时可快速应用。\u003c/p>\u003cp>方法：\u003c/p>\u003cp>首先我先针对自己的自我介绍套用MTV法做了以下3个调整：\u003c/p>\u003cp>1.调整M，增加有特色的记忆点，例如：特别的标签（爱学习的宝妈、温暖共情的宝妈、盖洛普实践爱好者）。\u003c/p>\u003cp>2.增加T，体现出自己超出一般人的优势和成就，一定是可量化的。例如：一个月减重15斤，每天读完一本书，这样的标签不超过三个。\u003c/p>\u003cp>3.优化V，和前面的个人标签相关联，提自己给别人带来的价值。\u003c/p>\u003cp>通过调整后，我的MTV自我介绍如下：\u003c/p>\u003cp>【M】大家好，我叫李素芬，从事企业培训管理工作十年，同时也是盖洛普实践爱好者。\u003c/p>\u003cp>【T】我坚持2年，每周参加一次线下/线上演讲会/优势会诊会，帮助100+伙伴学会游戏破冰，和自我探索发现自己的优势。\u003c/p>\u003cp>【V】如果你也对培训有兴趣，想迭代培训体系，想经验萃取做案例开发，想在培训中运用游戏提升趣味性，扩大影响力，欢迎链接我，我定会知无不言言无不尽！谢谢大家！\u003c/p>\u003cp>【结束总结】\u003c/p>\u003cp>相信通过学习应用MTV自我介绍的方法，我的自我介绍不仅高效且有价值。\u003c/p>\u003cp>我的分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1713622734000,"updated_at":1713664202000,"ria":true},{"id":17459,"topic":"通过MTV法来介绍让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，然后让对方产生想与你链接的意愿。","learn_goal":"","remark":"通过MTV法来介绍让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，然后让对方产生想与你链接的意愿。\n","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"拿鐵","city":"宁波市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>&lt;自我介绍&gt;\u003c/p>\u003cp> 老叶飞刀，坐标浙江宁波，我的三个标签是资深财务人员、公司上市运作者、读书会创立者（下面会有更详细的介绍，这里暂略）。\u003c/p>\u003cp>&lt;拆书帮介绍&gt;\u003c/p>\u003cp> \u003cstrong>首先，“拆书”是一种学习方法论，p是：\u003c/strong>\u003c/p>\u003cp> 1、以提升能力、解决问题为目标的成人学习方法论；\u003c/p>\u003cp> 2、以学习者为中心而不是以知识为中心，把知识关联学习者的经验、规划具体的运用。\u003c/p>\u003cp> \u003cstrong>然后，“拆书”方法可以用三张便签来加以说明：\u003c/strong>\u003c/p>\u003cp> \u003cstrong>1、R便签\u003c/strong>：重点在如何找到合适的原文作为拆页，建议是：从自己的问题/需求出发。\u003c/p>\u003cp> 想找到有用信息，就要用较快的速度阅读全书，进而留意对自己有用的理论、建议或观点。在这过程中，如果遇到难理解的地方，不妨先问问自己“这对我重要吗？”，如果不重要，就跳过继续往下读；反之，就细读。\u003c/p>\u003cp> 其实上述方式还可以优化，比如，在整体阅读之前，要先明确自己的阅读目的，自己想从书里得到什么；接着，再阅读书的非正文部分，比如前言、目录等，从而快速了解书籍梗概、找到有用章节。完成了这些步骤后再进行快速阅读，效率会更高。\u003c/p>\u003cp> \u003cstrong>2、I便签\u003c/strong>：用自己的语言重述内容。\u003c/p>\u003cp> 重述知识、引导促进、思维升级。\u003c/p>\u003cp> \u003cstrong>3、A1便签\u003c/strong>：拆为已用，重点是应用。\u003c/p>\u003cp> 针对I便签或书里的信息，联想自己有没有亲身经历，或听说、见到过类似的事情，将它们写在A1标签上，贴到I便签旁边。要有故事性，能清晰地呈现起因和结果，切忌泛泛而谈。凡是没有具体时间、事件的，都算泛泛而谈，是认知论述，不是经验叙述。\u003c/p>\u003cp> \u003cstrong>4、A2便签\u003c/strong>：我以后怎么用？\u003c/p>\u003cp> 写下自己如何实际应用书中信息或I信息，包含应用的目标、为达成目标要做的行动。将它也贴到书页上。目标要符合SMART法则：明确的、可衡量的、可实现的、结果导向、有明确截止日期的。行动要具体，包含人、时间、地点等。切忌说没用的空话，如决心泛滥或感慨万千。写A2便签还有个小诀窍，最好不要强迫自己不能做什么，比如晚上睡觉前不玩手机，而是用一个新行为去替代它，比如晚上睡觉前看书半小时。\u003c/p>\u003cp> \u003cstrong>其中，拆书法可以分为个人学习的拆书法和组织学习的拆书法：\u003c/strong>\u003c/p>\u003cp> 1、个人学习的应用是便签法，让人读一本书就能达到参加同主题培训的效果；\u003c/p>\u003cp> 2、组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp> 现在，我们说一下“拆书帮”，“拆书帮”是基于拆书法的学习爱好者社群，其愿景是帮助拆书家们升级学习力及促进他人学习的能力，影响身边的人，让世界变得更好一点\u003c/p>\u003cp> 因为“拆书帮”使命是帮助更多学习爱好者成长为学习促进者，因此其必然是非营利性学习爱好者组织。\u003c/p>\u003cp> “拆书帮”目前，拆书帮在全球共有58家正式分舵，定期举办拆书活动，深度影响数十万人的学习与生活方式，践行通过学习改变行为，释放学习促进者的能量。\u003c/p>\u003cp> \u003cstrong>最后，我们来说一下拆书帮价值观：\u003c/strong> 陪伴赋能 、拆为己用、 反求诸己、 持续精进、 共同成长。\u003c/p>\u003cp> 其他比较好理解，重点解释一下反求诸己：在学习相关的一切事情上都应“反求诸己”。从自己身上找原因,从自己身上找方法,在自己身上加要求。\u003c/p>","ratings_count":1,"texts":[{"id":21639,"quote":"\u003cp>\u003cstrong>MTV法介绍自己   片段来源  《爆款写作课》\u003c/strong>\u003c/p>\u003cp> 【过渡语】下面由我来带领大家一起拆解一下今天的片段。下面我们花3分钟看一下原文片段，看完后抬头示意一下我。\u003c/p>\u003cp> 梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp> 但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp> 这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp> M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp> T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp> V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp> 这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp> 比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp> 1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp> 2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp> 3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp> 当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp> 理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp> 当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp> 你有没有遇到遇到和别人作了自我介绍后，对方热情洋溢但并不会和你对接的情况；但有人做了自我介绍就会有很多人拥上去加微信，你是如何理解这种情况的？\u003c/p>\u003cp> MTV法是一种让直接了向对方展示自己的能力、取得过什么成就、能够提供什么价值的自我介绍方法。\u003c/p>\u003cp> MTV法好处是相互坦诚，不用相互猜忌，节约对方的时间、可以达到快速能让对方产生连接你的意愿，从而选择你这个品牌。\u003c/p>\u003cp> MTV法可以分三个步骤操作:\u003c/p>\u003cp> 1、M标签：先介绍你的主要信息，说明你是谁。这部分主要目的是呈现出你的能力，把你的品类和标签展现给对方；\u003c/p>\u003cp> 2、T成就事件：陈述一下你做过什么成就事件。这部分的目的是让对方对你产生信任，特别当你的成就事件可公开的、或者可以查询的情况下；\u003c/p>\u003cp> 3、V价值链接：说明一下你能为对方提供什么价值。\u003c/p>\u003cp> MTV法也不见得适用于所有场景，比如就不适合以下场景：\u003c/p>\u003cp> 1、你不需要也不想让现场的人来对接你；\u003c/p>\u003cp> 2、你的信息已经被大家知悉或本身就具有一定公开性（如公众人士），或者有类似主持人这样的第三方人员会来介绍你的场合；\u003c/p>\u003cp> 3、不允许你做详细自我介绍场合，如项目启动会上而你负责记录；\u003c/p>\u003cp> 4、有明确目的、分工明确的会议场合，比如商务谈判、项目推进会，等等。\u003c/p>","interaction":"\u003cp>关联具体经验\u003c/p>\u003cp> 我在参加今年3月4日开始的拆书邦便签训练营开营时，根据要求作了一个自我介绍：\u003c/p>\u003cp> 【昵称或姓名】老叶飞刀\u003c/p>\u003cp> 【我的坐标】浙江宁波\u003c/p>\u003cp> 【我的标签】资深财务人员、初级法律人员、公司上市运作者\u003c/p>\u003cp> 【我的成就事件】\u003c/p>\u003cp> 2023年通过法考、建立区域有一定影响力的静城不服书读书会\u003c/p>\u003cp> 【我能为大家提供的价值】\u003c/p>\u003cp> 财务知识分享、公司证券知识分享、法律基础知识分享\u003c/p>\u003cp> 【本期训练营的目标是】\u003c/p>\u003cp> 重塑读书模式，成为初级拆书家，帮助自己提升输入和输出效率；\u003c/p>\u003cp> 重构静城不服书读书会运营模式，帮助更多终身学习者有效学习。\u003c/p>\u003cp> 作完自我介绍，只有一位同学来对接我，主要探讨如何组织读书会运营模式的问题。说明了这个介绍按照MTV法来评价肯定是不合格的。\u003c/p>\u003cp> 对照MTV法，我对上述训练营开营自我介绍进行反思如下：\u003c/p>\u003cp> 1、M标签：这部分介绍只是把我的姓名、坐标，以及资深财务人员、初级法律人员、公司上市运作者三个标签做了一下介绍，太过笼统，并没有呈现出我的能力；\u003c/p>\u003cp> 2、T成就事件：这部分我把2023年通过法考、建立区域有一定影响力的静城不服书读书会作为成就事件。信息相对欠缺，不能让对方产生信任；\u003c/p>\u003cp> 3、V价值链接：我把财务知识分享、公司证券知识分享、法律基础知识分享作为价值链接，但这对很多人来说可能并没有什么价值。\u003c/p>\u003cp>\u003cstrong>具体应用\u003c/strong>\u003c/p>\u003cp> 目标：通过用MTV法重新梳理自我介绍，找到自己最值得骄傲的事件，吸引对注意力，并产生共鸣。\u003c/p>\u003cp> 行动：\u003c/p>\u003cp> 1、 根据对MTV法的学习，我马上重新梳理了一份可用于类似在拆书邦便签训练营、拆书精进群内、以及今天的拆书升级时沟通的自我介绍。\u003c/p>\u003cp> M标签：我叫老叶飞刀，坐标浙江宁波，我的三个标签是资深财务人员、公司上市运作者、读书会创立者。\u003c/p>\u003cp> T成就事件：\u003c/p>\u003cp> ①、资深财务人员：有20年多财务工作，高级会计师、会计硕士、英国皇家特许管理会计师CIAM， 2011年入选第一期宁波市会计领军人才，2020年提名 CGMA全球管理会计中国大奖年度财界新锐，2023年通过法考；\u003c/p>\u003cp> ②、公司上市运作者：多家公司上市/新三板操作运作经验。\u003c/p>\u003cp> ③、读书会创立者；创办一家纯公益、并无一分钱经费但却运营近三年的静城不服书读书会，在本地区域内董秘+财务总监领域内形成一定影响力。\u003c/p>\u003cp> V价值链接：有以下需求欢迎来链接我\u003c/p>\u003cp> ①、想设计好一公司家公司股权的；\u003c/p>\u003cp> ②、想运用公司上市以有资本运作的； \u003c/p>\u003cp> ③、想进行股权融资的。\u003c/p>\u003cp> ④、想创办一家纯公益、无任何经费但却能运营多年读书会，并通过读书会促进身边小伙伴一起成长的。\u003c/p>\u003cp> 2、在4月份根据外部反馈再迭代一个版本。\u003c/p>\u003cp>\u003cstrong>&lt;强有力的结束语&gt;\u003c/strong>\u003c/p>\u003cp> 最后总结一下今天的拆书。\u003c/p>\u003cp> MTV法是一种让直接了向对方展示自己的能力、取得过什么成就、能够提供什么价值的自我介绍方法。通过三个步骤清晰的介绍自己：M标签、T成就事件、V价值链接。让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。从而让对对方就会连接你，选择你这个品牌。\u003c/p>\u003cp> 我今天的分享就到此结束了，希望这个片段会对各位小伙伴有帮助。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1712043068000,"updated_at":1712189709000,"ria":true},{"id":17368,"topic":"让人印象深刻的自我介绍---MTV法则","learn_goal":"","remark":"生活或者职场，只要你需要社交，都需要自我介绍，但很多时候我们不知道怎么介绍，要么介绍后别人印象并不深刻、或者没有和对方有所链接，那有没有简单易操作且让人印象深刻的自我介绍方式呢？给大家分享一个《爆款写作课》中关于更好自我介绍的工具：MTV法则，让你会自我介绍、让你的自我介绍更令人印象深刻。","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"田娟","city":""},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp>各位伙伴大家好，我是倾城，一个深耕培训9年的老兵，我有3个标签，企业培训师，擅长讲解课程开发、演讲、礼仪等课程；野生主持人，在企业主持过运动会、年会、创业家年会等各种类型的会议，最多人数超过6000人；以及今天大家看到的我，一个正在努力过级的拆书家。如果后期你有课程开发、演讲、主持方面的问题，欢迎随时交流。\u003cbr>\u003c/p>\u003cp>为了在课程中伙伴们相互交流探讨，我们分成两个小组。。。\u003cbr>\u003cbr>在分享今天的拆页之前，先给大家介绍一下拆页的来源书籍《爆款写作课》 ，《爆款写作课》 是一本关于新媒体写作的书籍，作者弗兰克通过自己的亲身经历和教学经验，总结出了打造爆款文章的方法和技巧，如自己独创的新媒体写作3步法——吸引、打动、说服，以及如何通过练习和实践提高自己的写作水平等，对于想要提高自己写作水平和打造爆款文章的人来说非常值得一读。\u003cbr>好的，各位伙伴可以看到已经给大家准备好的拆页内容，现在请大家用2分钟的时间快速阅读一下，阅读完成后可以举手示意我。\u003c/p>","ratings_count":1,"texts":[{"id":21547,"quote":"\u003cp>\u003cstrong>R：MTV法介绍自己   片段来源《爆款写作课》 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>M是英文单词Me的缩写，意思是你是谁？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>V是单词Value的缩写，意思是你能提供什么价值？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1. 普通人如何做出属于自己的歌曲？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2. 2.如何成功脱单，找到自己的心灵伴侣？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/strong>\u003c/p>","explains":"\u003cp>好的，各位伙伴已经看完了；\u003c/p>\u003cp>\u003cstrong>WHY（为什么？）：\u003c/strong>我们经常说一个人无法给对方留下第二次第一印象，我们都知道第一印象很重要，而第一印象中除了穿着、行为举止外，最重要的部分莫过于一个令人印象深刻的自我介绍，\u003c/p>\u003cp>\u003cstrong>WHERE(用在哪里？)\u003c/strong>\u003c/p>\u003cp>因为我们无论是生活场景还是工作场景都很遇见很多人，无论是主动社交还是被动社交都需要让对方认识你、记住你，但如何做一个让人印象深刻的自我介绍呢。\u003c/p>\u003cp>\u003cstrong>WHAT（是什么？）:\u003c/strong>大家就可以使用拆页中分享的工具MTV法则来进行尝试设计一下自我介绍，MTV法将自我介绍分为三个部分，使得表达更具条理性和逻辑性，能让你更好地展示自己的优势和特点的同时，也能让对方更好地理解你的背景和能力，从而建立更深入的链接\u003c/p>\u003cp>\u003cstrong>HOW（怎么做？）\u003c/strong>\u003c/p>\u003cp>那我们如何做呢？\u003c/p>\u003cp>首先M（Me）：介绍我是谁。需要介绍自己的基本情况，比如名字、行业、职业、城市或家乡等。\u003c/p>\u003cp>T（Thing）：介绍你做过什么。需要介绍自己的成就事件，包括在工作中取得的成绩、参加过的项目、获得过的荣誉等。这些成就事件应该是具体的、可衡量的，以便让对方更好地了解你的能力和价值。\u003c/p>\u003cp>V（Value）：介绍你能提供什么价值。需要说明你能够为他人提供什么价值，例如你的专业技能、经验、资源等。你可以根据不同的场合和需求，有针对性地介绍自己的价值，以便更好地吸引对方的关注和兴趣。\u003c/p>\u003cp>比如我今天开场的自我介绍就是用的MTV自我介绍法\u003c/p>\u003cp>M:我是倾城，一个深耕培训9年的老兵，介绍了我的名字和职业\u003c/p>\u003cp>T：我有三个标签，培训师、野生主持人、正在过级的拆书家，也举例了可衡量、具体的内容，如擅长演讲、礼仪、课程开发，主持过6000人以上的会议\u003c/p>\u003cp>V：那我和大家的链接是什么，能为大家提供什么呢，大家如果有课程开发、演讲表达或者主持的问题的时候我们可以深度交流和沟通\u003c/p>\u003cp>大家可以看到这也是一个完整的MTV介绍的内容。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1:\u003c/strong>那各位伙伴，现在大家可以回顾一下你上一次自我介绍是什么时候？当时是在什么背景下发生的，介绍的过程是怎样的，结果如何？给大家4分钟的时间，小组伙伴可以相互分享一下。。。\u003cbr>\u003cbr>\u003cstrong>学习者案例分享：\u003cbr>分享者：\u003c/strong>莹莹\u003c/p>\u003cp>\u003cstrong>事件：\u003c/strong>大学开学竞选心理委员，有4个伙伴同时参与竞选，当时莹莹用mtv法则进行自我介绍，自我介绍结束后，其中一个竞选者对莹莹说，听了你的介绍我都想选你了\u003c/p>\u003cp>\u003cstrong>过程：\u003c/strong>\u003c/p>\u003cp>首先介绍了我是谁，在哪里：...\u003c/p>\u003cp>我的成就事件是：...\u003c/p>\u003cp>我能给大家带来的价值有哪些：...\u003c/p>\u003cp>\u003cstrong>结果：\u003c/strong>班级里的伙伴对她很认可，很受伙伴欢迎，最后莹莹老师成功竞选了心理委员\u003cbr>\u003c/p>\u003cp>\u003cstrong>A2:\u003c/strong>好的各位伙伴，刚才大家都兴高采烈地的做了分享，通过伙伴们的分享，大家会发现这种有逻辑性、能告知对方你的价值点、能产生链接的这种自我介绍方式是更能对方接受，同时也能为自己助力加分，当然也有伙伴分享到之前也遇到了一些坑，相信大家都已经熟悉了MTV介绍法，后期也可以多多尝试避免踩坑。我们经常说有用才有用，所以各位伙伴可以先试想一下，在未来一周，你有没有需要让对方认识你、记住你的情况，你会怎样用 MTV 法去介绍自己? 请在纸上写下来，写的时候注意，不能只是决心，要有具体的做法，要有具体的时间和可衡量的预期结果。\u003c/p>\u003cp>现在给大家2分钟的时间，请用MTV的模型拟定自我介绍框架。。。。\u003c/p>\u003cp>\u003cbr>\u003cbr>好的，我看大部分伙伴都写完了，相信各位伙伴今天都收获了MTV自我介绍的工具，也希望大家回去之后能够设计出自己不同场合下的自我介绍并进行持续练习和运用，希望你可以灵活运用MTV自我介绍法更好的展示自己的特点和价值，助力社交和职业发展的需要。谢谢大家，我是倾城，感谢大家参与今天的分享。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1709775149000,"updated_at":1710341264000,"ria":true},{"id":16826,"topic":"晋级","learn_goal":"","remark":"晋级","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"黄艳","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>请问观察家老师拿到记录表、准备表和拆页了么？\u003c/p>\u003cp>自我介绍：大家好，我是黄艳，感谢各位参加今天的拆书练习。\u003c/p>\u003cp>我一名拆书帮会员，也是一名传统文化爱好者；\u003c/p>\u003cp>我愿意成为晋级学长们的纪律委员，帮助和砥砺拆书帮想晋级的小伙伴，持续晋级；\u003c/p>\u003cp>过去三个月中，我每天通过传统文化持续帮助他人，义务解决他们工作和家庭的障碍；\u003c/p>\u003cp>这就是我，一名为可以助你持续晋级、并能助您解决工作和家庭问题的黄艳\u003c/p>\u003cp>今天现场有位书友，这样分成1个小组！\u003c/p>","ratings_count":2,"texts":[{"id":20941,"quote":"\u003cp>今天我分享的书籍来自《爆款写作课》，弗兰克\u003c/p>\u003cp>P67-69\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向大家介绍一个做自我介绍的工具\u003c/p>\u003cp>MTV法则。\u003c/p>\u003cp>M你是谁？\u003c/p>\u003cp>T做过什么成就事件？\u003c/p>\u003cp>V能为他人提供什么价值？ \u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询： 1.普通人如何做出属于自己的歌曲？ 2.如何成功脱单，找到自己的心灵伴侣？3.个人品牌时代，如何借鉴明星包装经验推广自己？当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cul>\u003cli>图书介绍：\u003c/li>\u003cli> 今天我分享的书籍是《爆款写作课》，弗兰克\u003c/li>\u003cli>P67-69\u003c/li>\u003cli>作者详细拆解了爆文的构成元素，手把手教我们从选题立意牢牢抓住读者眼球，循序渐进打动和说服读者，最终将文字变现。独创了新媒体写作3步法——吸引、打动、说服。他主张会说话就会写作，普通人只要遵循技巧，也能写出10W+。\u003c/li>\u003cli>现在请各位用2分钟时间快速阅读我发给大家的原文片段内容，完成后举手示意我。\u003c/li>\u003cli> 【what】 片段的主要观点是在讲一个自我介绍的工具，即MTV法。是从一个人的表面（姓名、职业）到内在（性格、爱好、成就）再到更深层价值（如：为别人提供咨询）的一种沟通方法。\u003c/li>\u003cli>【why】学习这个自我介绍的方法有什么好处呢？\u003c/li>\u003cli>MTV法可以让你在自我介绍后，很快地被大家记住，记住你的亮点事迹，记住你能提供他人的价值，这样他人才会真的觉得认识你很高兴呢！\u003c/li>\u003cli>【how】具体怎么做呢？……步骤完成：\u003c/li>\u003cli>用MTV法做自我介绍，分为三步：\u003c/li>\u003cli>1.M，我是谁，可以包含名字、籍贯、常住地、职业等个人基本信息，还可以加上有特点的标签来丰富。\u003c/li>\u003cli>我是黄艳，来自江安，我是一名拆书帮会员也是传统文化爱好者\u003c/li>\u003cli> 2. T，我有何成就：\u003c/li>\u003cli>过去三个月中，我每天通过传统文化持续帮助他人，义务解决他们工作和生活的障碍，\u003c/li>\u003cli> \u003c/li>\u003cli>3.V，我可以为大家提供哪些价值。MT是从我的角度出发，介绍自己来吸引你，而V是利他的角度。\u003c/li>\u003cli>比如可以做你晋级的纪律委员，帮助你持续晋级、并能够通过传统文化解决工作和家庭问题，助你走出困境\u003c/li>\u003cli>【where】MTV法是从表面到内在到价值，通过“人-事-价”三个要素进行结构化表达的交流方式，适用于比较正式的加入一个新社群，想要链接新朋友，或者上台发言介绍推广自己的场合用。\u003c/li>\u003cli> \u003c/li>\u003cli>当你遇到家庭或工作困惑或者陷入焦虑等情绪障碍的时候，你会想到可以和我来进行交流吧。\u003c/li>\u003c/ul>","interaction":"\u003cp>A1便签\u003c/p>\u003cp>1.回想过往印象深刻的一次自我介绍的场景是怎么样的？成功或者失败的案例都行，当时是怎么做自我介绍的，效果怎样？（小组内讨论，时间2分钟）\u003c/p>\u003cp>小王：我会很夸张的介绍自己，我是……，特夸张的吸引大家，我们家有18个孩子，原因是我的名字有18个笔画，效果有一点点\u003c/p>\u003cp>李老师：在加入拆书前，不管什么场合，我是这样介绍自己的：我是李永忠，是做网络安全的，来自……公司，就这么三句话。如果当时是超过5个人，几乎就没有人记住。\u003c/p>\u003cp>是的是的，没学MTV法之前，我也是这样介绍自己的！\u003c/p>\u003cp>小米：旁听\u003c/p>\u003cp>2.选出1位小伙伴分享一个自身的经历，（注意：案例要有时间、地点、人物、情节、过程、结果等，2分钟内）\u003c/p>\u003cp>A2便签：\u003c/p>\u003cp>学习了今天的MTV自我介绍三步骤，接下来请大家用2分钟时间用MTV法，把行动规划写在便签上：\u003cstrong>我在什么时间期限内（最好是未来一两个星期以内），在什么场景，运用MTV方法去干什么，想要达到什么样的效果。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（学习者案例记录）：\u003c/strong>李老师：下周3参加一个培训师的培训，我会这样说：我叫李永忠，永忠呢是永远忠于毛主席……为人民服务，我是一名网络安全程序员，如果大家有关于这方面的困惑可以交流和联系！\u003c/p>\u003cp>谢谢李老师，估计刚刚是紧张的原因，整个的介绍：我是谁很清晰，有提到提供的价值，如果能够加上，过去我有什么成就，效果就会更好！\u003c/p>\u003cp>【总结】最后希望通过对MTV的学习对各位伙伴以后的自我介绍有帮助，谢谢大家，我的分享到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1698721505000,"updated_at":1700662923000,"ria":true},{"id":16633,"topic":"带着“自我介绍”来，收获“高效链接”的价值","learn_goal":"","remark":"本书是一本非常容易上手的实操工具书，有逻辑、有内容，可以作为我们演讲、表达、写作的检验标准，也可以让我们重新认识写作。写作不仅仅是文字这么简单，更是人生的商业模式，这是一本很容易操作的新媒体实战手册，掌握简单的方法，让你成为新媒体写作高手。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"莫愁","city":"长治市"},"club":{"name":"长治上党分舵","city":"长治"},"prologue":"\u003cp>不破不能立，不拆不成器！拆书帮把知识拆成你的能力！感谢各位参加今天的拆书练习。\u003c/p>\u003cp>我是莫愁，一名拆书帮会员，也是心理咨询师和幸福力教练；\u003c/p>\u003cp>我获得过十余项发明专利，我在线上通过社群读书陪伴的方式帮助过52名女性走出抑郁情绪的障碍。\u003c/p>\u003cp>• 我可以帮助没时间看书的人学会用拆书法解决问题，把书读进生活里。\u003c/p>\u003cp>• 我可以帮助父母学会如何和孩子沟通，处理青春期孩子的冲突。\u003c/p>\u003cp>• 我可以帮助女性找到内在的力量，让更多的家庭幸福和睦。\u003c/p>\u003cp>我是莫愁，一名为你解忧、促你成长的拆书家，让你越来越自信、富有、快乐的陪伴教练。\u003c/p>\u003cp>今天现场有4位书友，我们以桌子中线分开，左边的人成为一组，右边的为一组，这样分成2个小组！\u003c/p>\u003cp>今天我分享的书籍是爆款写作课，作者详细拆解了爆文的构成元素，手把手教你从选题立意牢牢抓住读者眼球，循序渐进打动和说服读者，最终将文字变现。他独创了新媒体写作3步法——吸引、打动、说服。他主张会说话就会写作，普通人只要遵循技巧，也能写出10W+。\u003c/p>\u003cp>现在请各位用2分钟时间快速阅读我发给大家的原文片段内容，完成后举手示意我。\u003c/p>","ratings_count":2,"texts":[{"id":20744,"quote":"\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。M是英文单词Me的缩写，意思是你是谁？T是英文单词Thing的缩写，意思是你做过什么成就事件？ V是单词Value的缩写，意思是你能提供什么价值？这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。 \u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询： 1.普通人如何做出属于自己的歌曲？ 2.如何成功脱单，找到自己的心灵伴侣？3.个人品牌时代，如何借鉴明星包装经验推广自己？当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>大家都读完了，那我来分享一下我的解读。\u003c/p>\u003cp>【what】 片段的主要观点是在讲一个自我介绍的工具，即MTV法。是从一个人的表面（姓名、职业）到内在（性格、爱好、成就）再到更深层价值（如：为别人提供咨询）的一种沟通方法。\u003c/p>\u003cp>【why】学习这个自我介绍的方法有什么好处呢？\u003c/p>\u003cp>我来举个反面例子：“大家好，我叫莫愁, 有一个孩子，空余时间我喜欢读书，是一名心理咨询师，很高兴认识大家。” \u003c/p>\u003cp>这是全民阅读协会联盟成立的时候我的自我介绍。\u003c/p>\u003cp>活动结束后，一位伙伴走过来跟我说，你的表现很不错。能否冒昧问下你的名字。\u003c/p>\u003cp>我当时楞了一下，心想：我刚介绍过了啊。\u003c/p>\u003cp>小伙伴尴尬地笑着说，你的名字不好记啊。\u003c/p>\u003cp>他的反应让我意识到这次自我介绍是失败的。\u003c/p>\u003cp>今天，我阅读《爆款写作课》用MTV三步法介绍自己这段内容时候，发现一个有新意、有亮点、又能展现自身价值的自我介绍是非常有必要的。\u003c/p>\u003cp>MTV法可以让你在自我介绍后，很快地让大家记住你，记住你的亮点事迹，记住你能提供给自己的价值，这样别人才会真的觉得认识你很高兴呢！\u003c/p>\u003cp> 【how】具体怎么做呢？……步骤完成：\u003c/p>\u003cp>用MTV法做自我介绍，分为三步：\u003c/p>\u003cp>1.M，me我是谁，可以包含名字、籍贯、常住地、职业等个人基本信息，还可以加上有特点的标签来丰富。\u003c/p>\u003cp>我是莫愁，来自壶关，我是一名拆书帮会员也是一名心理咨询师；\u003c/p>\u003cp>2.T，thing，我有何成就，这样让别人长大嘴巴惊讶的同时，可以擦亮眼睛好好看看你。\u003c/p>\u003cp>我获得过十余项发明专利，我在线上通过社群读书陪伴的方式帮助过52名女性走出抑郁情绪的障碍，重获幸福生活的能力。\u003c/p>\u003cp>3.V，value我可以为大家提供哪些价值。MV是从我的角度出发，介绍自己来吸引你，而V是利他的角度。\u003c/p>\u003cp>比如我可以帮助没时间看书，看不完书愧疚的人学会用拆书法解决问题，把书读进生活里。可能这个时候学了很多道理，依然为孩子和家庭关系苦恼的人就会来和我交流吧。\u003c/p>\u003cp>【where】MTV法是从表面到内在到价值，通过“人-事-价”三个要素进行结构化表达的交流方式，适用于比较正式的加入一个新社群，想要链接新朋友，或者上台发言介绍推广自己的场合用。\u003c/p>\u003cp>\u003cstrong>分享一下我的经历：\u003c/strong>\u003c/p>\u003cp>今天在拆书帮的晋级场，有机会和大家共同度过这段时光，我在开场使用的就是MTV介绍方法。。\u003c/p>\u003cp>\u003cu>【\u003c/u>我是谁\u003cu>】\u003c/u>，我是莫愁，拆书帮会员、心理咨询师和幸福力教练，以及【我能为提供的价值\u003cu>】\u003c/u>：\u003c/p>\u003cp>\u003cu>•帮助没时间看书的人学会用拆书法解决问题，把书读进生活里。\u003c/u>\u003c/p>\u003cp>\u003cu>• 帮助父母学会如何和孩子沟通，处理青春期孩子的冲突。\u003c/u>\u003c/p>\u003cp>\u003cu>• 帮助女性找到内在的力量，让更多的家庭幸福和睦。\u003c/u>\u003c/p>\u003cp>一一进行了对应，【我的成就事件】作为实践背书。\u003c/p>\u003cp>当你遇到亲子沟通方面的困惑或者陷入焦虑、抑郁情绪障碍的时候，你会想到可以和我来进行交流吧。\u003c/p>\u003cp>【拆书家指令】\u003c/p>\u003cp>在自我介绍中，你是否有过类似的场景呢？\u003c/p>\u003cp>我们做完自我介绍，他人依然尴尬的不记得你是谁或者我们简单清晰的讲诉我们自己以及过往的成就事件，却没有阐述我们能够给对方提供什么价值，别人说：哇，这么厉害。等称赞，然后就没有下文了。\u003c/p>\u003cp>现在给大家两分钟时间互相交流，一会儿请一位小伙伴站起来为大家分享一下。\u003c/p>\u003cp>……\u003c/p>\u003cp>现在哪位小伙伴用一分钟时间来给大家简单来分享一下呢？\u003c/p>\u003cp>好，欢迎玲玲为我们带来她的故事。\u003c/p>","interaction":"\u003cp>玲玲：以前介绍的时候，我就是介绍我的职业，我是一名老师，我在学习过程中拿到的一些认证，分享这些内容就结束了，别人也没有和我主动链接的意愿。\u003c/p>\u003cp>我失败的原因今天找到了，是我没有说到自己可以给别人提供什么价值，现在我知道如何快速让她人和我链接的方法是用MTV。\u003c/p>\u003cp>我来重新给大家做一个自我介绍：\u003c/p>\u003cp>M：我了新手拆书家玲玲。玲是形容玉石撞击发出清脆的响声，玲玲盈耳，明亮美好，我也希望自己能成为给别人带来快乐和美好的人。\u003c/p>\u003cp>T：我是ET&amp;父母游戏戏力认证讲师认证，成功举办过青少年效能训练工作坊，父母游戏力工作坊，全国让家更好玩线下沙龙等活动。\u003c/p>\u003cp>V：可以帮助你建立更加亲密的亲子关系，轻轻松松做父母！\u003c/p>\u003cp>谢谢玲玲的介绍，让我们用掌声谢谢玲玲。当我们的孩子和我们有矛盾，我们做父母感觉很累，烦躁的时候，可以来找玲玲老师啊。\u003c/p>\u003cp>因为时间关系我就不邀请其它小伙伴站起来分享了，学习了今天的MTV自我介绍三步骤，希望这个片段会对各位伙伴有所帮助，大家可以根据今天的内容重新写一个新的自我介绍，我们下周拆书帮练武场上来聆听，谢谢大家，我的分享到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1694789610000,"updated_at":1695712080000,"ria":true},{"id":16629,"topic":"如何用MTV介绍法，加深第一印象，拓展与人深度连接机会","learn_goal":"","remark":"小到饭局、认识新朋友，大到面试、演讲，自我介绍无处不在。平庸普通的介绍很难帮我们拓展二次与人连接的机会，那有什么方法可以让人快速认识我们并想与我们产生进一步的互动呢？学习掌握MTV三步法，获得高效与人连接的机会。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"李丫丫","city":""},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"\u003cp>【自我介绍】很高兴认识大家， 我叫丫丫，一个忠于自己梦想的实践者，之所以这么说，是因为我一直坚信这样一句话“当你想要某种东西时，整个宇宙会合力助你实现愿望。”比如，刚毕业的我想尽快还掉大学四年的助学贷款，毕业后努力增长自己的业务能力逐步成为团队TOP sale，之后用一个月工资提成还掉了所有助学贷款。再之后我从乙方跳槽甲方再出来自己创业，注册公司，成为一名自由自由者，每一步都在自我预言的方向发展~接下来我会在如何利用自媒体创业变现、如何成为一个好的三家拆书家等方面持续探索，如果你对这些感兴趣，欢迎大家跟我连接~\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>很开心今天能跟在场的各位一起学习交流。下面进入我的拆书分享环节，今天我拆的是TF1-2，内容来自弗兰克的《爆款写作课》，今天我拆解的片段是书中提到的：在学习写作之前，如何写出让人眼前一亮的自我介绍。\u003c/p>","ratings_count":1,"texts":[{"id":20740,"quote":"\u003cp>【过渡】下面我们进入R环节，请大家用1分左右的时间阅读原文片段，看完后请举手示意我下，以便我了解大家进度。\u003c/p>\u003cp>主题：如何用MTV法做自我介绍，加深第一印象，拓展与人深度连接机会\u003c/p>\u003cp>R ：原文片段来源《爆款写作课》P72-73（微信读书）\u003c/p>\u003cp>\u003cstrong>用MTV3步法介绍自己\u003c/strong>\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，\u003cstrong>是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/strong>\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>\u003cstrong>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/strong>\u003c/p>","explains":"\u003cp>【过渡】好的，注意到大家都已经阅读完了，下面我们一起进入I环节\u003c/p>\u003cp>\u003cstrong>【I重述知识点】\u003c/strong>\u003c/p>\u003cp>（why)认识新朋友、进入新的团队或者行业沙龙上，你是如何跟别人介绍自己的呢？是简单的我叫某某，来自哪里还是简单的说下职业、参与的原因呢？这样的介绍说出来大家对你的印象不是很深刻，很难与人产生进一步的连接和互动。另外您有没有遇到过这类自我介绍，说了很多，但别人什么都没记住，最后也没能吸引到其他人的主动连接，也是挺尴尬的局面。那有什么方法清晰简单的介绍自己，又能让别人对我们产生好奇想要主动的和你连接并保持联系呢？\u003c/p>\u003cp>（What）这个片段就给我们提供了一个特别棒的自我介绍方法——MTV三步法，它能帮助我们快速的梳理出自己的能力优势、价值点，从而吸引别人想要进一步了解你，进而有效的提升我们个人品牌影响力。 \u003c/p>\u003cp>（How)那MTV法具体的做法是什么呢？\u003cstrong>（大白纸卡片形式讲解引导）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>M（Me）说出你是谁。\u003c/strong> 说姓名、职业，来自哪里等基础信息，让对方初步了解自己。\u003c/p>\u003cp>\u003cstrong>T（Thing）展示成就事件。\u003c/strong>你都做过哪些成就事件？可以尝试从学习、健身、工作或者理想等维度思考， 这个成就事件中最好有一件与当下的场域相匹配的，让对方了解与之相关的我们的过往经验、经历等，这有助于吸引志趣相投的人主动与我们连接。\u003c/p>\u003cp>\u003cstrong>V（Value）提供价值。\u003c/strong>你个人能提供给大家什么价值？ 这个最好也是同样与场域相关的价值点，让大家了解，哪些事情是自己可以给协助和支持的——吸引有类似需求的人主动连接。\u003c/p>\u003cp>&lt;失败经历&gt;这让我想到之前参与读书分享会的一次经历，那时的我挺想拓展社交，希望有机会跟共同兴趣的人产生进一步连接的，但那个时候对自我介绍也没什么认识，只是简简单单的说下自己的姓名，坐标哪里，为什么过来参加什么的，也没有留下什么记忆点。\u003c/p>\u003cp>&lt;反思&gt;而反观当时有一两个其他的小伙伴，除了基础信息外还列举了自己在兴趣领域里做了哪些自豪的事儿，能提供给大家怎样的支持后，在场的人纷纷过去要微信。现在回顾起来跟MTV三步法不谋而合。 后来参与的活动多了，也意识到自我介绍的重要性，尤其在学了MTV法之后，平时也会有意识的用这三步法提炼自己的优势和价值点。\u003c/p>\u003cp>比如有次在一个行业大佬云集的分享会上，作为新人入群做自我介绍时，我是这样说的：\u003c/p>\u003cp>&lt;应用举例&gt;（大白纸用关键词的形式讲解以下内容）\u003c/p>\u003cp> “哈喽，我叫 丫丫，宁壹文化的负责人，6年的品牌营销经验。\u003c/p>\u003cp>（与大会主题相关的成就事件）作为甲方，在刚过去的一年里，操盘过千万级预算的品牌投放，用7%低营销费比，达到roi2+以上，多次超预期完成推广效果。 也曾用5W打造出100w的曝光效果， \u003c/p>\u003cp>（与大会主题相关价值点）在小众品牌低成本营销方面小有心得，对于kol市场报价敏锐，可接触到全网各类kol资源，如果大家有兴趣，可以会议后进一步沟通分享。”\u003c/p>\u003cp>这次自我介绍完，很多品牌的负责人都主动加了我的微信，有的线下还约了单独的小局，深入了关系；有的成了我的前辈老师，日常不断互相分享交流；还有的成为了我的新客户，使得业务进一步扩大。 \u003c/p>\u003cp>（where)这个方法适用于面对的群体里有陌生人，你想与其产生新连接的场合里，但用这个方法也需要注意一些“度”，比如有些人身上有很多的价值点，有选择性的挑选一个对方最感兴趣的价值点或者自己想对外连接的价值点进行介绍。面对不同的人群和场域，有不同的需求，重要的是让别人记住你，引起别人的好奇与连接，创造更多的可能性。\u003c/p>\u003cp>【过渡】以上就是我对MTV法的理解和应用。其实小到饭局、相亲、认识新朋友，大到面试、演讲，自我介绍无处不在。接下来我们进入A1环节。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>在此之前，我们先进行分组。临近的人两两一组，接下来有讨论分享的环节。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活学习者经验】4分钟\u003c/strong>\u003c/p>\u003cp>现在请各位回想下自己最近一个月内印象深刻的一次自我介绍的场景是怎么样的或者让你印象深刻的关于别人的一次自我介绍，当时是在什么的场合下，你或者你看到的他具体是怎么做自我介绍的，效果怎样？\u003c/p>\u003cp>请每人回忆分享一个自身的经历，成功或者失败的案例都行，按照分组，两两分享，时间1-2分钟。要注意的是，案例最好要有时间、地点、人物、情节、过程、结果等。\u003c/p>\u003cp>稍后邀请一两位伙伴来分享下那时是怎样的情境，自己是如何做自我介绍的。\u003c/p>\u003cp>好了，时间到。下面邀请一两位伙伴来分享，请想要分享的小伙伴举手。\u003c/p>\u003cp>&lt;分享者桔子老师&gt;：\u003c/p>\u003cp>我是做教育培训行业的，平时遇到的自我介绍场景还是挺多的，失败的案例像我们很多没有舞台经验的新学员上课，他们的自我介绍很多都是我是谁，我来自哪里，没有其他特殊的标签，人很多的时候这类介绍跟没有介绍是一样的。对于自我介绍有所训练的人介绍的就不一样，他有什么标签，什么爱好，能为大家提供什么，让人对这个人有一个IP印象，这类的就比较容易让人记得住，是印象中成功的案例。\u003c/p>\u003cp>【过渡】谢谢桔子老师的分享\u003c/p>\u003cp>\u003cstrong>【A2催化应用】1-2分钟\u003c/strong>\u003c/p>\u003cp>刚才我们激活了过去经验，接下来是我们的A2环节—规划未来的应用，请大家设想下，在接下来两周或一段时间内，比如需要参加互动分享会，或者出席有陌生人的饭局，或者新客户的拜访等等情境，根据MTV介绍法，应该怎么做自我介绍呢，请大家把自我介绍写在便签纸上，时间半分钟左右写下关键词。\u003c/p>\u003cp>写完后举手示意下我，稍后我们邀请一位小伙伴分享下他的A2——对未来的规划应用。\u003c/p>\u003cp>【过渡】好的，现在请青青给我们分享下她的经历。\u003c/p>\u003cp>&lt;分享者青青&gt;： \u003c/p>\u003cp>下周我在面试的场景中应用下这个方面。\u003c/p>\u003cp>M：我叫青青，有6年的托育行业经验；\u003c/p>\u003cp>T：策划过大型的品牌营销活动，有百万的营销业绩。\u003c/p>\u003cp>V：会再具体展开案例说明在策划、管理、营销等方面有丰富的经验。\u003c/p>\u003cp>【过渡】谢谢青青老师的分享\u003c/p>\u003cp>\u003cstrong>【结语】0.5分钟\u003c/strong>\u003c/p>\u003cp>希望通过今天MTV介绍法的分享，能让大家的自我介绍更精彩！也建议大家平时针对不同的场景进行练习，尝试梳理出自己最引以为豪的事情，有备无患，下次在面对新的陌生场合时，就能轻轻松松打出个人品牌的标签，推动与人深度连接的新可能。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1694594056000,"updated_at":1695847381000,"ria":true},{"id":16565,"topic":"遇到矛盾时如何实现双方共赢","learn_goal":"","remark":"遇到问题时候如何找到真正的解决方案？第三选择，揭秘一个能够改变你的生活决策的重要原则。","level":"TF3-3","duration":75,"status":29,"type":0,"chaishujia":{"username":"木木33","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"\u003cp>\u003cstrong>【个人介绍】\u003c/strong>\u003c/p>\u003cp>亲爱的小伙伴们，大家好，我是木木。三个标签介绍自己：拆书家，美业从业者，户外爱好者。\u003c/p>\u003cp>【学习总目标】今天学习的总目标是：学习者在面临与他人的观点有分歧的时候，首先运用“第三选择思维”四步法找到共识点，进而采取“协同”四步法讨论出可满足各方需求的解决方案。\u003c/p>\u003cp>\u003cstrong>【学习者场景法图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（场景）\u003c/strong>不知道大家是否有遇到这样的情景：你和你们家爱人因教育孩子的方式不同，心生不满；和父母因为观念或者生活方式不同，经常吵架；工作中与同事想法不同，各执己见，谁也没有办法来说服对方。\u003c/p>\u003cp>\u003cstrong>（提问）\u003c/strong>在面对自己和对方有分歧的类似问题时，通常我们会情绪激动，习惯性的想要争个输赢对错。那么你对自己的处理结果还满意吗？\u003c/p>\u003cp>学习者：不满意。\u003c/p>\u003cp>拆书家：不满意是吧，那为什么不满意呢？\u003c/p>\u003cp>学习者：感觉老是自己妥协。\u003c/p>\u003cp>拆书家：感觉自己老是妥协，还有其它的吗？\u003c/p>\u003cp>学习者：问题依旧在，情绪也依旧在。\u003c/p>\u003cp>拆书家：问题依旧在，情绪也依旧在。你觉得还可以怎么样呢？\u003c/p>\u003cp>学习者：希望他能听我的。\u003c/p>\u003cp>\u003cstrong>（影响）\u003c/strong>是的，很多时候我们不情愿的妥协或者强势的坚持“我”是对的。妥协是不是就让我们自己的内心处于拉扯状态，凭什么让我妥协呀，心生抑郁，怨恨等负面情绪；强势就会很容易和身边人发生争吵，破坏我们的人际关系。\u003c/p>\u003cp>\u003cstrong>（解决）\u003c/strong>今天拆解的这本书《第三选择》，当和对方存在分歧的时候，创造和谐，达成共赢。在今天的拆页中将引导大家运用“第三选择思维”模式，从新的视角来看待所面临的问题，并且通过与他人协同，创造出更好的解决方案。\u003c/p>\u003cp>请大家用30秒的时间阅读片段一，阅读完毕的小伙伴请举手示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":20694,"quote":"\u003cp>\u003cstrong>【R：阅读原文】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆页一】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>《第3选择》\u003c/strong>\u003c/p>\u003cp>两种选择思维\u003c/p>\u003cp>第3选择思维\u003c/p>\u003cp>1\u003c/p>\u003cp>我只看到了“我这一方”。\u003c/p>\u003cp>我看到了“我这一方”的独立的自我。\u003c/p>\u003cp>2\u003c/p>\u003cp>我对你有成见。\u003c/p>\u003cp>我将你视为独立的人，而不只是“你那一方”的代表。\u003c/p>\u003cp>3\u003c/p>\u003cp>我要维护自己，因为你是错的。\u003c/p>\u003cp>因为你看待事物的角度不同，所以我要找到你。\u003c/p>\u003cp>4\u003c/p>\u003cp>我攻击你，双方因此爆发战争。\u003c/p>\u003cp>我与你协同，我们共同创造一个超乎想象的不可思议的未来。\u003c/p>\u003cp>上表列举了普通的两种选择思维与第3选择思维的思维模式的对比。你可以看到，随着每一阶段的深入，两种选择思维逐渐离创造性解决方案越来越远。没有第3选择思维模式，获得创造性解决方案是不可能的。每一种思维模式都是下一阶段思维模式的基础，所以思维模式序列是非常重要的。\u003c/p>","explains":"\u003cp>\u003cstrong>【学习目标一】\u003c/strong>我们今天的学习目标一，学习者在面临与他人观点有分歧时，首先运用“第三选择思维”四步法找到共识点。\u003c/p>\u003cp>（互动）提问：片段中给大家讲了哪两种思维？\u003c/p>\u003cp>学习者：有两种选择和第三选择。\u003c/p>\u003cp>拆书家：有两种选择和第三选择思维，之前你们习惯用哪种思维？\u003c/p>\u003cp>学习者：两种选择思维。\u003c/p>\u003cp>拆书家：习惯用两种选择思维，好的，谢谢大家。\u003c/p>\u003cp>【I：重述原文】\u003c/p>\u003cp>\u003cstrong>（WHY）\u003c/strong>第一选择是“我打败你”，第二选择是“你打败我”。不管是坚持“你觉得”，还是“我觉得”，那么无论在生活还是工作中就很难进行愉快高效的互动和合作，轻则郁郁寡欢，为什么总是我受委屈，严重还会影响到家庭和睦，职场的晋升。认知模式决定行为，当面对一个看似只有两个极端选择的困境时，“第三选择”帮助我们跳出二元对立的思维定势，发掘隐藏需求，从而和谐沟通。\u003c/p>\u003cp>\u003cstrong>(WHAT)\u003c/strong>今天就让我们一起来打破思维惯性，学习一种新的思维方式——“第三选择思维”\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>“第三选择思维”是我们为找到双方的共同点，利益点，达成共赢而进行的，在生活和工作中都可以运用。不适用于某一方作为单独的受益者或者某一方有不可撼动的主导权。\u003c/p>\u003cp>\u003cstrong>（HOW）\u003c/strong>刚刚了解了思维的重要性，具体要怎么去做呢？——“第三选择思维四步法”：\u003c/p>\u003cp>\u003cstrong>一、\u003c/strong>\u003cstrong>回问自己。\u003c/strong>我的真实想法是什么样的？这里要关注事实和情绪。\u003c/p>\u003cp>\u003cstrong>二、倾听对方。\u003c/strong>平和的向对方提问，问对方你是怎么想的？耐心的听对方表达。\u003c/p>\u003cp>\u003cstrong>三、回应对方。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>确认对方。回应对方的时候先确认对方，就好像我刚才问大家有哪些思维？大家回应我“有两种选择思维”，我回应大家“有两种选择思维”，去重复对方的观点就可以了。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>表达自己\u003cstrong>。\u003c/strong>告诉对方我是怎么想的。\u003c/p>\u003cp>\u003cstrong>四、找到共识。\u003c/strong>不要求我们找到很多很多的共识，在这里找到一个共同点就可以了。\u003c/p>\u003cp>运用了“第三选择思维四步法”之后，我们就从分歧中找到和对方观点一致的地方，不用愤怒也不用忍让，和对方形成良好的互动，为寻找解决方案创造了一个和谐的氛围。\u003c/p>","interaction":"\u003cp>\u003cstrong>【案例】\u003c/strong>在这里给大家分享一个我自己的案例：\u003c/p>\u003cp>刚刚过去的一个星期，我儿子整天抱着手机打游戏，我是很烦很讨厌打游戏的。我气极了，劈里啪啦就是一顿，孩子被骂也很生气，又来怼我。学习第三选择之后，我做出了以下改变：\u003c/p>\u003cp>\u003cstrong>一、\u003c/strong>\u003cstrong>回问自己。\u003c/strong>我的想法是：我讨厌打游戏是因为我觉得孩子只要打了游戏，就一定是上了瘾，就一定会影响学习。\u003c/p>\u003cp>\u003cstrong>二、倾听对方。\u003c/strong>“儿子，你这几天游戏打的这么频繁，是因为什么原因？”这个时候他就会给我很多反馈，会讲到很多的点。\u003c/p>\u003cp>\u003cstrong>三、回应对方。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>确认对方。“你的意思是快开学了，接下来上高中很累，最近只想肆意的放松放松，感受下高中前最后的快乐？”\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>表达自己。“妈妈看到你打游戏就会认为一定会影响到你的学习，很担心你上瘾了。”\u003c/p>\u003cp>\u003cstrong>四、找到共识。\u003c/strong>经过这样的沟通之后发现我和我的孩子目标是一致的，都是希望他在开学之前好好的放松放松，然后进入高中认真努力的学习，好好的收一收心。\u003c/p>\u003cp>通过这样的四步法，了解到我和孩子对学业的规划是一致的。一下子就释然了，情绪就没有那么焦躁了，避免了和青春期孩子的更多冲突，为后一步沟通怎么解决这个事件创造了和谐的氛围。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>通过第三选择思维改变了思维惯性，分别从自己和对方的角度进行察觉，创造和谐。如果不这么做，很容易被自己升起的念头左右，分歧马上升级为矛盾，争端随时就会爆发。\u003c/p>\u003cp>\u003cstrong>【A2：小剧本】\u003c/strong>\u003c/p>\u003cp>俗话说：“学的好，不如用的好。”学习就是为了致用。刚才我们学习了“第三选择思维四步法”，让我们化身为编剧。请大家看着小剧本，想象一下在未来的一个月里，生活或工作中可能和对方产生分歧的场景，请设计出当时的情景，情节变化包括：起因，经过，结果和当时的对话，动作等。可能是因为孩子教育问题，可能是你和父母观念的不同或者生活习惯的分歧，可能是工作中和同事之间不能达成一致。请大家先想象一下，想出来就可以了，有想到的小伙伴举手示意我一下。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>拆书家：丁丁你想到了吗？\u003c/p>\u003cp>学习者（丁丁）：我觉得今天这个位置，随便一喵就看到我了。\u003c/p>\u003cp>拆书家：丁丁是要再思考一下对吗？\u003c/p>\u003cp>学习者（丁丁）：我先思考一下。\u003c/p>\u003cp>拆书家：好的。青青分享一下。\u003c/p>\u003cp>学习者（青青）：我想分享的是孩子吃饭的问题，孩子不爱吃饭的话，婆婆就会给她喂饭，一边看动画片一边喂饭，我看到这个情景就很火大。\u003c/p>\u003cp>拆书家：因为孩子吃饭，她认为孩子应该自己吃，婆婆觉得孩子是需要大人去喂的，有这样的分歧。\u003c/p>\u003cp>拆书家：李任性，你给大家分享一下。\u003c/p>\u003cp>学习者（李任性）：我觉得分歧可大了。我弟弟不上班，我想让他上班，他不肯上，家里乌烟瘴气的，并且他说话不算话，明明给我说天气凉了就出去上班，但是现在都不和我沟通了，只要问到这个事情，就是你管我干嘛。\u003c/p>\u003cp>拆书家：好，我总结一下，你的弟弟不愿意上班，你想让他上班，这个事情出现了分歧对不对？\u003c/p>\u003cp>学习者（李任性）：是的。\u003c/p>\u003cp>拆书家：请大家把刚刚想到的分歧，简短的写到上剧本的上面。\u003c/p>\u003cp>接下来请大家运用“第三选择思维四步法”找到共识点，找到一个就可以了，把关键字写在小剧本上，但是最后要以对话的形式呈现出来。时间3分钟，3分钟后有请一位小伙伴分享她的剧本。请注意是用“第三选择思维四步法”找到双方的共识点。请注意最后我们是要以对话的形式呈现出来的。\u003c/p>\u003cp>【学习者分享一】\u003c/p>\u003cp>拆书家：哪位小伙伴先来为我们分享一下，青青先来为我们分享一下吧。这个事件发生在什么时间，接下来这个事情准备在什么时候进行？\u003c/p>\u003cp>学习者：下周晚上的时候，在家里和我的婆婆聊一下关于孩子喂饭的这个事情。\u003c/p>\u003cp>拆书家：你准备怎么进行呢？\u003c/p>\u003cp>学习者青青：\u003c/p>\u003cp>一，回问自己，我为什么看到婆婆给孩子喂饭我就很生气，我觉得都这么大了，应该自己独立吃饭，这样会惯的她习惯不好，没有独立性，我主要是担心这点。\u003c/p>\u003cp>二，倾听对方。我：“婆婆，你为什么不能等等孩子，一到点就一定要给孩子喂饭呢？”\u003c/p>\u003cp>婆婆：“到时间不吃饭孩子就会变瘦，营养不良，个子长不高。”\u003c/p>\u003cp>三，回应对方。\u003c/p>\u003cp>确认对方。我：“我知道你主要是担心孩子不好好吃饭，影响身体的发育。”\u003c/p>\u003cp>表达自己。我：“我也希望孩子健康长大，但是孩子也需要独立。”\u003c/p>\u003cp>四，找到共识。“其实你也是想孩子好，我也是想孩子好。”\u003c/p>\u003cp>【拆书家反馈】经过这么一系列的对话下来以后，我们就发现不用再像以前看到婆婆喂饭只有抓狂的情绪，心里是很难过的，但是这件事情不知道怎么去解决，情绪上很憋闷。运用了“第三选择思维四步法”之后经过了这样的沟通，把我们担心焦虑的情绪放下来，然后才能够一起去寻找解决方案。\u003c/p>\u003cp>\u003cstrong>【总结和过渡】\u003c/strong>学习了第三选择思维让我们在面对分歧的时候，可以考虑到双方的需求，找到更多的双方共同点，达成更多的一致。改变思维可以化解冲突，避免激化矛盾。创造了友好互动的氛围后，才能够平心静气的面对实际的问题，付出行动，寻找解决方案。接下来，进入片段二，用“协同原则”共创解决方案。\u003c/p>\u003cp>\u003cstrong>【量表自测】\u003c/strong>\u003c/p>\u003cp>在开始第二个片段前，首先，请大家先做一下自测题，按照1-6的标准给自己打分，1分代表完全不符合，6分代表非常符合，请你花1分钟时间，将每道题打分，并汇总分数，做好的小伙伴可以用微笑示意我。\u003c/p>\u003cp>得分（1分完全不相符，6分是完全相符）\u003c/p>\u003cp>1.出现分歧时，我总是会邀请对方一起寻找解决方案.123456\u003c/p>\u003cp>2.集体活动中，我总是会关注到每个人的需求。123456\u003c/p>\u003cp>3.有人反对我，我能认真的听完他的想法。123456\u003c/p>\u003cp>4.面对冲突时，我总认为会有更好的方法。123456\u003c/p>\u003cp>5.和对方观点不同时，我总会从细节中寻找出共同点。123456\u003c/p>\u003cp>总分\u003c/p>\u003cp> \u003cstrong>【I测试题解释+和学习者互动】\u003c/strong>\u003c/p>\u003cp>20分以上的小伙伴请举手，包括20分，我看到有一位小伙伴，恭喜你，你非常擅长于和他人合作，如果能够熟练运用今天协同的方法，就可以创造出更多共赢的局面。15-20分的小伙伴举手我看一下，大部分都是15-20分，这个分数段说明大家已经意识到合作的重要性，并且愿意和大家协同找到更好的方案， 15分以下的小伙伴有吗，没有，在我们现场大家都非常棒，15分以下的更喜欢让别人认同自己的观点。作为一名社会人，每个人都不可能独立的存在，无论是生活还是工作都有需要协同的地方。\u003c/p>\u003cp>让我们一起来看片段二，请大家用30秒的时间阅读，阅读时把关键词标注出来。\u003c/p>\u003cp>\u003cstrong>【R：阅读原文】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆页二】\u003c/strong>\u003c/p>\u003cp>寻求“协同”的原则\u003c/p>\u003cp>我们通过一种被称为“协同”的原则达成第3选择。协同就是1加1等于10或者100甚至1000！协同就是两个或以上的人决定放弃成见，迎接挑战的硕果。它关乎激情，活力，创造力以及创造美好新现实的冲动。\u003c/p>\u003cp>协同与妥协是两码事。妥协时1加1最多等于1.5，双方都有损失。协同则不仅能够解决冲突，而且在协同达成的时候，我们能够超越冲突。我们会达到一种新的境界，人人为新希望而激动，未来因此而发生改变。协同比“我的方法”或“你的方法”更好，它是“我们的方法”。\u003c/p>\u003cp>\u003cstrong>【学习目标二】\u003c/strong>片段二的学习目标是：采取“协同”四步法讨论出可满足各方需求的解决方案。\u003c/p>\u003cp>拆书家：协同有哪些关键词？\u003c/p>\u003cp>学习者：放弃成见，创造力，超越冲突，迎接挑战。\u003c/p>\u003cp>\u003cstrong>【回应式反馈+概念】\u003c/strong>放弃成见，创造力，超越冲突，迎接挑战，大家都非常的棒。“协同”将我们作为一个整体，关注大家的利益，创造出让人倍感愉悦的方案，什么叫倍感愉悦呢？大声的欢呼“YES”，激动的互相拥抱，急于开心的向别人分享。\u003c/p>\u003cp>\u003cstrong>【I：重述原文】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>经常夫妻间为了谁洗碗而吵架，在很多家庭中是有的，我看到有小姐姐在笑，和父母间为了生活习惯吵的不可开交，同事间为了一些琐事而大发脾气的时候，我们特别容易把目光放在冲突点上，然而真正要解决的并不是冲突点，而是转变导致冲突发生时的处理方式。这种方式就是“协同”。\u003c/p>\u003cp>\u003cstrong>【概念对比】\u003c/strong>为了更好的理解协同，给大家举几个例子：\u003c/p>\u003cp>【反例一】我是妈妈，你要听我的。是不是协同？\u003c/p>\u003cp>学习者：不是。\u003c/p>\u003cp>拆书家：对，不是协同。协同不是某一方的标准，是参与者都认同的标准。\u003c/p>\u003cp>【反例二】公司安排下来的这个项目我们每个人都全力配合。是不是协同？\u003c/p>\u003cp>学习者：不是。\u003c/p>\u003cp>拆书家：对，也不是协同。协同需要基于所有人的目标创造出方案，而不是安排什么就是什么的退让。\u003c/p>\u003cp>【反例三】今天召开新项目会议，经过大家的表决，基本都对方案比较满意。是不是协同？\u003c/p>\u003cp>学习者：是/不是\u003c/p>\u003cp>拆书家：这个时候就有分歧了，有小伙伴说是，有小伙伴说不是。那么是还是不是？大家此刻觉得很迷惑。在这里，不是。满意只是妥协。满意的时候，那就这样吧，差不多就行了。协同达成的时候一定是开心，快乐，要有情绪的正向波动。\u003c/p>\u003cp>\u003cstrong>根据以上的例子，我给大家列出了“妥协”和“协同”的区别：\u003c/strong>\u003c/p>\u003cp> 名称 妥协 协同 \u003c/p>\u003cp>\u003cstrong>不\u003c/strong>\u003c/p>\u003cp>\u003cstrong>同\u003c/strong>\u003c/p>\u003cp>\u003cstrong>点 \u003c/strong>参照标准 某一方 参与者都认同的标准\u003c/p>\u003cp> 找寻方案 退让 创造\u003c/p>\u003cp> 心理活动 满意 情绪的正向波动\u003c/p>\u003cp>\u003cstrong>【强调重点和难点+适用边界】\u003c/strong>\u003c/p>\u003cp>从上面的例子可以看出，协同是关注大家的目标来创造出新方案，这个方案一定是人人都满怀期待的。它不适用于两种选择思维，当对方不愿意进行协同或者有精神层面的疾病，也是不能协同的。\u003c/p>\u003cp>\u003cstrong>（HOW）\u003c/strong>了解了协同，我根据书上的内容总结出以下步骤——“协同四步法”：\u003c/p>\u003cp>\u003cstrong>一，邀请对方一起。\u003c/strong>邀请对方一起来寻找解决方案：“我们一起来看看都有些什么方法？”\u003c/p>\u003cp>\u003cstrong>二，写出每人目标\u003c/strong>。将每一个人的目标罗列在一张纸上。\u003c/p>\u003cp>\u003cstrong>三，找出共同目标。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>四，确认解决方案\u003c/strong>。根据共同目标，先将所有的方案罗列出来，不做评判。怎么样来判定找到了最好的方案呢？当见到这个方案的时候（达成信号）期待/兴奋/开心/长舒一口气/气氛活跃/看到希望.........\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>刚刚给大家分享了上个星期我儿子每天打游戏很多，他认为是开学前的狂欢，而我认为他太迷恋游戏，已经上瘾了一定会影响学习。在上一个页面我们看到了双方的共识点，已经让自己情绪平和，建立了愉快的沟通。接下来运用“协同四步法”找到解决方案：\u003c/p>\u003cp>\u003cstrong>一，邀请对方一起。\u003c/strong>“儿子，我们一起来看看开学前这一周怎么度过会更好？”\u003c/p>\u003cp>\u003cstrong>二，写出每人目标\u003c/strong>。儿子：1.把游戏里的钱都花掉上学就不打了。2.疯狂的和同学一起玩。3.妈妈不要管的太多。我：1.不要整天的打游戏。2.不要让我看到打游戏。3.为开学做准备，学习要抓紧。\u003c/p>\u003cp>\u003cstrong>三，找出共同目标。\u003c/strong>在开学前的这段时间疯狂的玩的开心，做好提前预习。\u003c/p>\u003cp>\u003cstrong>四，确认解决方案\u003c/strong>。妈妈做自己的工作，之前我是请了假在家里陪他的，觉得这是对孩子最好的，实际上不是我认为的。儿子在家每天上午两个小时完成新课程预习作业，我不在的时候打游戏两个小时，其它时间下楼和小伙伴疯狂的躲猫猫或者打牌。每天晚上和妈妈确认当天的内容。\u003c/p>\u003cp>经过这样，后面这一个星期我们都过的很开心。1号的时候我儿子给我电话说了很久，自己的高中规划，理想。如果没有运用今天的方法，因为游戏不停吵架，是不是就不会有这么良好的亲子关系。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>可能有小伙伴会说,这样达成的方案一定好吗？好不好，只有去实践了才知道。如果不这么做，特别容易陷入争吵和自我辩护，损耗彼此的时间和精力，甚至损伤之前建立的感情和信任。需要注意的是分歧促进协同，但是不一定会在短时间内找到让人兴奋的结果，一些时候需要花更多的时间去进行。\u003c/p>\u003cp>\u003cstrong>【A3：微行动学习】接下来进入A3，微行动学习\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>在进入这个环节之前，我们先进行一个分组，三位下伙伴一组，三位小伙伴一组，剩下四位一组，共分三组。请大家30秒的时间内选一个组长，组长的职责是（安排成员上台分享/组织小组内讨论/安排记录的人员）三位组长举手示意我一下。\u003c/p>\u003cp>好，接下来我们进入微行动的环节，请大家关注我的引导。\u003c/p>\u003cp>\u003cstrong>1、【明确问题】\u003c/strong>\u003c/p>\u003cp>请大家用一分钟的时间思考一下，自己最近遇到的分歧是什么？是和谁之间发生的？\u003c/p>\u003cp>学习者（丫丫）：我侄女大三马上开学了，我看见她一直玩手机我也很不赞同。\u003c/p>\u003cp>拆书家：因为和侄女玩手机有分歧对不对？\u003c/p>\u003cp>学习者（丫丫）：是的。\u003c/p>\u003cp>学习者（明策）：外公想让我女儿周末学习，女儿不愿意学习。\u003c/p>\u003cp>拆书家：在我们的现场，我们来关注下我们自己遇到的分歧，外公和女儿因为不在现场学习，我们不太容易了解到他们的情况。刚才我们收集到三个分歧，第一个是青青因为喂饭的问题和婆婆意见不同，第二个是李任性，因为弟弟不工作，她想让弟弟工作。第三个是丫丫，因为打游戏和侄女的意见不同。这三位，你们想帮助哪一位来解决这个问题呢？\u003c/p>\u003cp>学习者（同）：李任性。\u003c/p>\u003cp>拆书家：你们都想帮李任性解决她和她弟弟的问题吗？\u003c/p>\u003cp>学习者（同）：是的。\u003c/p>\u003cp>拆书家：你确实觉得这件事情很困扰你吗？确实很想解决这个问题吗？\u003c/p>\u003cp>学习者（李任性）：确实。\u003c/p>\u003cp>拆书家：前面第一个页面的时候，李任性已经对和弟弟的矛盾进行了讲述，大家已经有了一定的了解，那我们一起来帮助她好不好？大家愿意吗？\u003c/p>\u003cp>学习者（同）：愿意。\u003c/p>\u003cp>\u003cstrong>2、【引导讨论问题本质】\u003c/strong>\u003c/p>\u003cp>拆书家：好。谢谢大家，接下来就进入我们的下一个环节，讨论问题的本质，很多时候我们看到的只是表象，这件事情背后的本质原因是什么呢？这个姐姐为什么觉得弟弟不工作让自己很困扰呢？她真正的只想解决让弟弟上班的问题吗？现在以小组为单位，大家把背后可能的本质罗列出来。\u003c/p>\u003cp>第一组：\u003c/p>\u003cp>1. 担心弟弟荒废掉。\u003c/p>\u003cp>2. 金钱的压力比较大。\u003c/p>\u003cp>3. 害怕弟弟能力太弱。\u003c/p>\u003cp>4. 担心弟弟孤僻，出现心理问题。\u003c/p>\u003cp>5. 家庭的负担比较重。\u003c/p>\u003cp>6. 认为弟弟无欲望。\u003c/p>\u003cp>第二组：\u003c/p>\u003cp>1. 姐姐没安全感。\u003c/p>\u003cp>2. 姐姐比较有责任心，焦虑。\u003c/p>\u003cp>3. 家庭压力比较大，社会压力大，担心亲戚说自己家里。\u003c/p>\u003cp>4. 希望弟弟更好，家庭更好。\u003c/p>\u003cp>第三组：\u003c/p>\u003cp>1. 姐姐担心家庭和睦问题。\u003c/p>\u003cp>2. 姐姐希望弟弟成长。\u003c/p>\u003cp>3. 父母传递给姐姐很多压力。\u003c/p>\u003cp>4. 姐姐认为弟弟破坏诺言，让自己情绪非常的崩溃和无语，想和弟弟建立良好的沟通。\u003c/p>\u003cp>\u003cstrong>3、【明确问题本质】（1分）\u003c/strong>\u003c/p>\u003cp>拆书家：好，我们刚才罗列了这么多的本质，请大家用一分钟的时间从自己那一组罗列的点里面找到最核心的一点，解决了这一点，其它的就解决了大部分了。\u003c/p>\u003cp>拆书家：第一组大家认为是哪一点？\u003c/p>\u003cp>学习者：我觉得是4。\u003c/p>\u003cp>拆书家：让弟弟身心健康你们觉得其它问题基本能解决了？\u003c/p>\u003cp>学习者：是的。\u003c/p>\u003cp>拆书家：第二组呢？\u003c/p>\u003cp>学习者：姐姐的安全感。\u003c/p>\u003cp>拆书家：第三组呢？\u003c/p>\u003cp>学习者：和弟弟建立有限沟通。\u003c/p>\u003cp>请大家举手表决一下，大家认为这三点里面，最关键的要解决哪一点？大家认为是弟弟心理健康这个的小伙伴举手示意一下。没有。大家认为解决了姐姐的安全感就可以了，三位小伙伴举手。大家认为只要姐姐能够和弟弟有效沟通就可以的举手示意一下，大部分的小伙伴都是这么认为的，大家都认为只要姐姐能够和弟弟有效沟通，姐姐和弟弟之间的分歧就解决了吗？\u003c/p>\u003cp>学习者（同）：是的。\u003c/p>\u003cp>我们的案主也是这么认为的吗？\u003c/p>\u003cp>学习者（李任性）：是的。\u003c/p>\u003cp>拆书家：那我们发现案主她想解决的其实是和弟弟的沟通问题。\u003c/p>\u003cp>在我们一起帮助她找到解决方案的之前，我们先问一下案主，在沟通这个事情上，你想解决到什么程度，目标是什么？\u003c/p>\u003cp>学习者（李任性）：沟通到他能给我一点回应，他现在是一个完全封闭的状态。\u003c/p>\u003cp>拆书家：沟通到他能给你一点回应。\u003c/p>\u003cp>学习者（李任性）：比如说他可以告诉我，他准备什么时候上班。他也可以说不想上班，我也可以去说服我父母，就是你接下来到底是要做什么，你给我一个回应。\u003c/p>\u003cp>拆书家：就是说你希望你弟弟给你一个回应是吗？\u003c/p>\u003cp>学习者（李任性）：是的。\u003c/p>\u003cp>拆书家：那有一个明确的时间吗？\u003c/p>\u003cp>学习者（李任性）：一个之内吧。\u003c/p>\u003cp>拆书家：好的，我们案主的目标是一个月之内和弟弟有一个良好的沟通可以让弟弟有想工作的意愿。弟弟是否想工作我们很难判断，但是良好的沟通我们是不是可以做到。\u003c/p>\u003cp>\u003cstrong>4、【引导分组讨论解决方案】\u003c/strong>\u003c/p>\u003cp>三分钟的时间，请大家根据案主的目标罗列出可行的方案。今天我们学习了凉个拆页，是否可以运用到我们的解决过程中呢？请大家进行探讨。\u003c/p>\u003cp>\u003cstrong>5、【请每位组长分享自己组的成果】\u003c/strong>\u003c/p>\u003cp>请每个组按安排一位人员上台来分享一下：\u003c/p>\u003cp>第一组：\u003c/p>\u003cp>1. 松弛的环境，沟通的过程中讲有趣的事情。\u003c/p>\u003cp>2. 多认同弟弟，回应弟弟的一切说法。\u003c/p>\u003cp>3. 找到共识点，如何都过的更好。\u003c/p>\u003cp>第二组：\u003c/p>\u003cp>1. 给弟弟一个放松的环境，当面沟通，不要微信电话。\u003c/p>\u003cp>2. 找心理咨询师介入。\u003c/p>\u003cp>3. 寻求亲友的帮助\u003c/p>\u003cp>4. 接受现状，姐姐先妥协。\u003c/p>\u003cp>第三组：\u003c/p>\u003cp>1. 不批评，愉快的聊天，找到爱好和挖掘内心想法。\u003c/p>\u003cp>2. 找到共识点。\u003c/p>\u003cp>3. 姐姐要立刻制定行动计划。\u003c/p>\u003cp>\u003cstrong>分类/归纳/提炼\u003c/strong>\u003c/p>\u003cp>根据大家刚才的分享，我来做一个总结：\u003c/p>\u003cp>1. 环境。轻松愉快的环境有利于进行沟通。\u003c/p>\u003cp>2. 多认同对方。\u003c/p>\u003cp>3. 找到共识点。\u003c/p>\u003cp>4. 寻找外界的帮助。\u003c/p>\u003cp>5. 制定行动的计划。\u003c/p>\u003cp>刚才这几点我们案主都记录清楚了吗？我看到她一直在点头，非常的谢谢大家，我们把掌声送给自己。\u003c/p>\u003cp>\u003cstrong>【A2-催化学习者应用-布置作业-特定任务】\u003c/strong>\u003c/p>\u003cp>经过了愉快的学习，到了布置作业的环节。今天我们学习了面对分歧时的处理方式，要让自己熟练运用就需要多多练习。请大家在一周内和一位家人或者朋友，针对你们最近出现的分歧或冲突运用今天学习的方法首先用“第三选择思维”达成共识，建立良好互动，然后共创解决方案。请大家写出你想分享的家人，你会在什么时间？什么地点？和这位家人分享的目地是什么？请大家写在便签上，一会儿交给我。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>现在我们来总结一下今天的学习，达成第三选择的两步：\u003c/p>\u003cp>\u003cstrong>一.用第三选择思维找到一致建立良好互动：\u003c/strong>\u003c/p>\u003cp>1、回问自己。2、倾听对方。3、回应对方。4、找到共识。\u003c/p>\u003cp>\u003cstrong>二.用协同共创解决方案：\u003c/strong>\u003c/p>\u003cp>1，邀请对方一起。2，写出每人目标。3，找出共同目标。4，确认解决方案。\u003c/p>\u003cp>希望通过今天的分享，大家能够更多的回看自己，理解他人，更好的建立自己的人际关系，并且在发生分歧的时候看到更多的可能性，积极进行协同，创造出可以带来双赢的方案。感谢大家，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1694003735000,"updated_at":1694445270000,"ria":true},{"id":16210,"topic":"用MTV法介绍不一样的自己","learn_goal":"","remark":"让人眼前一亮的自我介绍","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"看见的力量","city":""},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>大家好！我是娜娜，一位热爱工作、精致生活的阳光小姐姐。我用三个城市坐标来介绍自己：\u003c/p>\u003cp>1、我所在家乡的省会城市济南，23年霸榜阅读量第一名，当然我也是一位爱学习爱阅读的小伙伴，以书会友，与大家一起学习共同成长；\u003c/p>\u003cp>2、全国网红烧烤城市淄博，齐国故都，历史文化悠久，有着众多名垂千古人物，我也热爱旅游，热爱探索； \u003c/p>\u003cp>3、我现在所在的城市，世界美食之都——顺德，相信爱美食的小伙伴应该不会错过这趟顺德之行，欢迎大家来顺德找我。\u003c/p>\u003cp> 当然我还有着多年的家电行业销售管理经验，曾指导多家企业的私域运营、大促营销、团队建设等工作，欢迎大家多多沟通交流。\u003c/p>","ratings_count":2,"texts":[{"id":20298,"quote":"\u003cp>接下来，就由我来带领大家拆解一下今天的片段。\u003c/p>\u003cp>这个片段选自一本非常受欢迎的书《爆款写作课》。书中用MTV法三步法介绍自己如何写出眼前一亮的自我介绍？如何用正确的方式展示自己？如何用最短的时间吸引对方的注意力，产生连接的可能。\u003c/p>\u003cp>做自我介绍，其实就是一个做减法的过程，在过去的经历中的到最亮点的成就整件，找到关键数据支撑，然后尝试和对方连接。下面我们花1分钟的时间，看一下原文片段。\u003c/p>\u003cp>\u003cstrong>用MTV三步法介绍自己\u003c/strong>\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp>1．普通人如何做出属于自己的歌曲？\u003c/p>\u003cp>2．如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3．个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>","explains":"\u003cp>大家都看完了对吧？好~我们来看看，从这个片段中，我们可以学到什么？\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>那首先，什么是MTV法呢？\u003c/p>\u003cp>MTV 是一款简易通用的自我介绍的社交工具，是Me、Thing、Value的缩写，它能在最短时间让对方一目了然的知道你是谁、能做什么、能提供什么价值，这样对方就能快速检索与你的连接点、可共事的场景、可寻求协助或支持的机会点。\u003c/p>\u003cp>【WHERE】\u003c/p>\u003cp>此方法不仅适用于商务合作（如上下游、培训机构、政府合作等）或同社群（默认同理念人群）等场景。\u003c/p>\u003cp>但不适合与陌生人电话沟通或有目的性的通过介绍强连接，容易引起反感或猜疑。 \u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>简单来说，MTV分三步：\u003c/p>\u003cp>第一，M你是谁？\u003c/p>\u003cp>第二，T你做过什么成就事件？\u003c/p>\u003cp>第三，V你能提供什么价值？\u003c/p>\u003cp>\u003cstrong>【举例子】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我分享一个自己的亲身案例，让大家了解这个知识点的应用方法：\u003c/strong>\u003c/p>\u003cp>回想4月26日第一次参加拆书帮训练营的活动，其中第一个环节就是自我介绍，当时我很不以为然的这样介绍我自己：我是Sunny，用三个标签来相互认识一下吧：阅读爱好者，喜欢咖啡、旅游、小动物，知行合一的实践者，欢迎大家多多交流。这么介绍过后好像一片落叶飘到水中，一点涟漪都没泛起。\u003c/p>\u003cp>按MTV法我重新梳理如下：\u003c/p>\u003cp>第一步，M：你是谁？比如，我是一名从事家电行业热爱美食热爱生活的私域用户运营官\u003c/p>\u003cp>第二步，T：你做过什么成就事件？比如，我曾为15家以上头部家电零售商提供私域运营解决方案，带队运营私域群30+，服务用户15000名以上，期间把一款新品打造成爆品，私域转化率50%+\u003c/p>\u003cp>第三步，V：你能提供什么价值？比如，我可以为大家提供以下咨询：\u003c/p>\u003cp>1，每个人家里都少不了几件甚至十几件家电，可解决家电相关问题；\u003c/p>\u003cp>2、流量越来越分散，如何做好公域转私域，通过私域运营实现增长？ \u003c/p>\u003cp>3、新消费场景下组织及个人如何快速迭代适应新时代？\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>MTV自我介绍法让对方一目了然知道你是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>","interaction":"\u003cp>那我们现在进入A的环节。这次现场参与人数4位，不需要分组。\u003c/p>\u003cp>我们一起来回忆下过往你发生的有关自我介绍的案例，在这个场景里，你是怎么介绍自己的。时间为3分钟\u003c/p>\u003cp>有没有哪位小伙伴愿意分享一下自己的经历？【1-2人】3分钟\u003c/p>\u003cp>分享者一Rainbow\u003c/p>\u003cp>大家好，我叫Rainbow，现在佛山顺德。我是知识型的二胎宝妈，我小宝刚七个月，我也是知行合一的探索者，追求身心合一的内向型销售。我自己的力量来源是独处的、思考性的。那我过往Things也提三点，第一我能够在全国业绩两位数下跌的时候创造了两位数逆势增长的世界500强优秀销售冠军。第二是我有多次从0到1的渠道开拓经验。三个月的业绩过100万。我也是一个知识型的人，我会孩子为中心去支持他的一个兴趣，接纳他的情绪是我自己做到的。那我能够提供的价值是我能够提供一些销售业务方面的咨询，除了我本身过往的经验，我自己本身的专业是市场营销的。那第二个，因为我是二胎宝妈，所以我也可以提供一些育儿方面的一些知识或者或经验看法，第三个是我有比较丰富的渠道资源推荐，除了说，我自己目前是做电商的，所有的渠道说社交电商没有自己接触过，但是我也有一些从传统电商、兴趣电商的一些资源，然后我自己过往也有线下渠道的体验，以上三个方面是我自己的个人价值。\u003c/p>\u003cp>分享者二苏艳\u003c/p>\u003cp>我是苏艳，在佛山有24年了，我的成就是一直在做行政方面的工作在企业里面，已经有十年多之久，我们做行政就是做有温度的服务。我的第二个成就是我是突破爱好者。试过在一天之内从早上七点到晚上七点徒步37公里。然后第三个成就是我是带着我的小孩走过29个城市，会在这个期间去支持到他去看世界，用行走的方式。我的价值，就是因为带着孩子去过很多地方，在旅行这一块可能会有一些自由行方面的，比如说青旅，比如说家庭的约旦，这种不太一样的旅行方式可以跟大家去分享。第二个就是在修行的过程当中，我自己其实也是一个内观修行者，也是可以去给大家分享的。第三个就是一些阅读经验，因为在养育孩子的过程当中，在跟孩子行走世界的过程当中，也有一些在小孩从整个的小学初中到高中一些性格的养成，还有跟孩子的相处，以及孩子的职业规划等等。\u003c/p>\u003cp> \u003cstrong>行动计划\u003c/strong>\u003c/p>\u003cp>因为时间关系不能让每一位小伙伴把自己的经历分享给大家，大家可能也面临再次自我介绍的场景，那可以结合「MTV自我介绍法」与自身过往经历联系更好呈现自己。\u003c/p>\u003cp>下面我们用两分钟时间在便签纸上列一个行动计划，写下你们对这个方法的具体运用，一定要注意我们的行动步骤是具体可行的哦~\u003c/p>\u003cp>首先写下你的目标，希望在多长的时间维度，什么样的场景来践行「MTV自我介绍法」呢？\u003c/p>\u003cp>如果我们使用这个方法，我们将怎么做呢？有哪些具体的行动呢？\u003c/p>\u003cp>有没有哪位小伙伴愿意分享一下自己的计划呢？【视时间情况1-2人】1.5分钟 \u003c/p>\u003cp>分享者Rainbow\u003c/p>\u003cp>我将在下周日公司组织的读书分享会上使用MTV法来介绍自己。\u003c/p>\u003cp>我会首先明确MTV每个字母所代表的具体含义，做到准确使用，通俗易懂，其次T部分尽可能有过往数据论证，最后V部分结合自身经历展现自我价值。\u003c/p>\u003cp>最后我们来回顾一下，今天的拆书分享。\u003c/p>\u003cp>我们在《爆款写作课》这本书里学到了一个能够帮助我们如何通过「MTV自我介绍法」让自己在最短的时间内让人眼前一亮，并让对方有产生链接的想法与可能。日后大家遇到的需要自我介绍的场景，咱们就可以把这个方法用起来啦~\u003c/p>\u003cp>以上就是本次拆解的内容，你们的A2便签和热烈的掌声，就是让我持续分享的动力，谢谢大家~\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1689006477000,"updated_at":1689218186000,"ria":true},{"id":16063,"topic":"MTV自我介绍法：只需3步，让人主动加你微信！","learn_goal":"","remark":"你是否有过这样的经历：当你来到一个陌生场合，大家的自我介绍几乎都是，我叫什么名字、我来至什么地方、我做什么工作，我有什么爱好，千篇一律，显得很是无趣！\n\n如果人少还好，如果人多一点，这样的自我介绍，你根本就记不住几个，而同样的，你这样自我介绍，别人也很难记住你！那么，问题出来哪儿呢？问题在于你的自我介绍不够特别！\n\n这时有人会说：我没有什么特别的地方值得介绍啊！真的是这样吗？答案是否定的，其实，每个人都有他的特别之处，只要你慢慢发掘，就能够找到，这就是我们今天要带你来做的。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"丁大鹏","city":""},"club":{"name":"深圳桃李分舵","city":"深圳"},"prologue":"\u003cp>【技能点：学习目标】学习目标包含了学习者可被观察到／被测量到的行为或动作。\u003c/p>\u003cp>学习者在学完以后，能现场写出一份具有MTV自我介绍法特点的自我介绍并分享。\u003c/p>\u003cp>【技能点：FAB图书介绍法】能够清晰辨别出F、A、B\u003c/p>\u003cp>【开场白】大家好，我是丁大鹏，大鹏展翅的大鹏，我有3个标签，分别是：工地搬砖人，佛系单身Go和打油诗小王子。今天要分享的主题是：MTV自我介绍法，只要3步，让人主动加你微信。\u003c/p>\u003cp>【Feature特征】这个自我介绍法来自于《爆款写作课》这本书，他的作者叫弗兰克，曾经是一名世界500强外企的职业经理人，他在书中用了3大成功案例进行分析，拆解出了11种写作技巧，并通过128个实例来进行演练。\u003c/p>\u003cp>【Advantage优势】这本书涵盖了作者从零开始学写作，从实践中总结出来的吸引、打动、说服，这个新媒体3步写作法，的所有运用心得和体会，内容之充实，讲解之细致，真正做到了让写作变得简单易学，即使你是新手小白，也可以马上拿来操练，因此获得了秋叶、剽悍一只猫、彭小六等5位新媒体大咖的联名推荐。\u003c/p>\u003cp>【Benefit利益】那么现在我们来思考一下，在这个快节奏的移动互联网时代，如果我们想要快速与他人建立链接，并取得他人的信任，最好的方式是什么？是建立属于自己的个人品牌，而想要建立个人品牌的第一步是什么？是做好自我介绍。那什么样的自我介绍，才是一个好的自我介绍呢？这就需要我们快速而准确地告诉他人：我是谁？我能做什么？我能为你提供什么样的价值？这样才能让对方快速而准确地记住你、了解你、然后再去链接你，而我们将要学习的MTV自我介绍法，就能达到这个目的。\u003c/p>","ratings_count":1,"texts":[{"id":20145,"quote":"\u003cp>R便签：1.3. 学习写作，写出眼前一亮的自我介绍\u003c/p>\u003cp>片段来源《爆款写作课》P67-69\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>目标：提到不这么做的坏处，找出人们的通常做法，举出反面例子，而且使用片段包含的技能把反面例子加工成正面例子。\u003c/p>\u003cp>【技能点：不这么样的坏处】\u003c/p>\u003cp>【过渡】大家现在可以和我一起来回想一下，你每次去到一个陌生场合，都是怎样介绍自己的？而其他人又是怎么介绍自己的？\u003c/p>\u003cp>&lt;一般人的做法&gt;\u003c/p>\u003cp>一般人都是这样介绍自己的：我是某某某、来至哪儿哪儿哪儿、从事啥啥啥工作，兴趣爱好是什么什么什么什么，等等等等......这种流水账式地自我介绍是最常见的。\u003c/p>\u003cp>&lt;一般做法的坏处&gt;\u003c/p>\u003cp>【Why】那么让我们一起来思考一下，如果你也是这样自我介绍的，对方能够快速地了解你吗？能了解到你主要想表达的是什么吗？能了解到你能为他提供的价值是什么吗？那么我们来想象一个场景，现在你面对的人中，有你很想进入公司的HR,有你很想认识的男神、女神或者是社群大咖。他们不知道你主要想表达的是什么，也不知道你能为他们提供什么样的价值，那是不是很可能让你失去一次进入心仪公司，认识心仪对象，结识社群大咖的机会呢？这都不是我们想要的，对吧？而我们现在学习的MTV自我介绍法，就能帮助我们解决这些问题。\u003c/p>\u003cp>【What】通过阅读拆页，我们会发现MTV自我介绍法最大的2个特点：\u003c/p>\u003cp>1、快速地讲清楚自己能做什么？也就是成就事件，才能让对方更快地了解你。\u003c/p>\u003cp>2、快速地让对方明白你能为他提供什么样的价值？才能让对方更好地链接你。\u003c/p>\u003cp>最终才能达到降低沟通成本，提升沟通效率的目的。\u003c/p>\u003cp>【How】那么我们该怎么做呢？ \u003c/p>\u003cp>1、介绍自己，也就是Me,我的意思，里面可以包含了我是谁？我来至哪儿？我是做什么的，等等基本信息。这里最好的介绍方式是贴标签，比如我们都爱说的爱阅读\u003c/p>\u003cp>2、相应成就，也就是Thing，成就事件，要对应你给自己贴的标签，你说自己爱阅读，那么你1年读了多少本书呢？平时都读哪方面书呢？能不能报几个相应的书名出来呢？比如：我1年内读了50本沟通力方面的书籍，像《非暴力沟通》《这样沟通就够了》等等....当然，如果你能说出读书后的效果。比如：读完以后，我写了50篇1000字的读后感。那就更好了！\u003c/p>\u003cp>3、提供价值，也就是Value，我能为你提供什么样的价值？这个价值就隐藏在我们做事的细节里，比如：你读书时用了哪些方法，可以快速地提高阅读速度？快速地做笔记？等等等等，这些都是可以用来帮到对方的，这就是你能提供的价值。\u003c/p>\u003cp>【Where】当然，这个方法适合于那些你想要去链接他人，且需要你去链接他人的场合，比如面试、单身交友、行业交流等等。如果你不想要去链接他人，只想做个安静的小透明的话，就不适用，或者参加部门内部讨论做汇报，这种不需要链接他人的场合，也是不适用。当然，还要记住一点的是，针对不同的场合，面对不同的人群，我们需要不同的自我介绍内容。\u003c/p>\u003cp>【过渡】为了让大家更容易理今天的内容，我们看两个案例，第一个是我在没有学习MTV自我介绍法前的情况。\u003c/p>\u003cp>&lt;反面案例&gt;\u003c/p>\u003cp>大家好！我叫丁大鹏，来至重庆，从事监理工作，爱读书、爱锻炼、爱写打油诗。一般我在这样自我介绍完以后，现场还是会有人记得爱写打油诗这个标签的，然而，过一段时间以后，大家就对不上号了。\u003c/p>\u003cp>&lt;正面案例&gt;而学完MTV自我介绍法以后，是这样的：\u003c/p>\u003cp>M：大家好！我叫丁大鹏，大鹏展翅的大鹏，人送外号打油诗小王子。\u003c/p>\u003cp>T：在2020年到2021年期间，我曾写过100首以上的打油诗，同时用来为4家成都的头马演讲俱乐部做活动推文，因此获得了这个绰号。\u003c/p>\u003cp>V：如果你想拥有一首属于自己特色的打油诗的话，可以来找我，现场加微信的人，免费！谢谢大家！\u003c/p>\u003cp>通过这样的自我介绍，不但活动现场有人马上来加我的微信，活动过后也有人来找我链接。\u003c/p>","interaction":"\u003cp>【技能点：显像提问】显像提问清晰，其中包含了具体的情景。刚才的学习者分享了自己根据这个场景联系出过往情景或具体经验。\u003c/p>\u003cp>A1：那么现在我们来回忆一下，你第一次上台做自我介绍的情况是怎样的？比如你第一来拆书帮或者到其他的陌生场合。当时你是怎么介绍自己的？内心的感受是什么样的？结果又是怎么样的？我们这里来进行一个分组，进行讨论一下，刚好我们这里两边2组，最好是一个负面的案例，方便我们后面优化和练习。2分钟时间，可以交流一下。\u003c/p>\u003cp>【2分钟后】有想好自己以前做过的自我介绍吗？这位小姐姐你可以站起来大概地说一下，讲你当时大概是怎么做自我介绍的，你可以说一下。她说不出来我们换下一位。\u003c/p>\u003cp>运玲分享：拆书帮是有一个介绍模板的，就是上来3个标签，就刚才大鹏的标签会举相应的例子，而我介绍标签时只会说我是一个一级拆书家，却没有体现出我能给大家带来什么。介绍完后，谁也不认识谁，基本就相当于没有介绍。\u003c/p>\u003cp>【技能点：A1+】A1+反思加工指令清晰，联系出如果以后再遇到同等情况时自已的具体做法。\u003c/p>\u003cp>那么我们就回到自己做得不好的场景，再来想象一下，用我们现在学到的这个MTV自我介绍法，如何对我们以前的自我介绍进行一个加工写出自己的M、T和V。就像刚才运玲说她只是把标签抛出来了，就像我以前一样只抛标签，那么我们对应的事件提取一个标签出来，把它具体地说出来，比如爱健身，那么我一周做了几次健身？我在健身的过程中有没有针对性地去做，比如我去预防受伤啊，什么的，这就是价值。可以提炼重点，然后Emily大概的简短地分享一下。\u003c/p>\u003cp>EmilyXiao分享：我在做自我介绍的时候，再说我是一个早起践行者，对吧？那我能做的这个就是M，我的成就事件就是我连续早起了200多天，然后我也达成了我的早起目标，做阅读和复习考试的内容，而且我能稳定的在6点之前起床啦，然后我能能够提供的价值呢，是帮助想要早起的人分享如何晚上凌晨1点钟左右睡觉，差不多12点钟睡觉，还能精神一下午，或者晚上11点睡觉早上6点钟起来，都能达成目标。这个就是就是我能提供的价值。\u003c/p>\u003cp>好的，感谢Emily的分享，那么最后我们也大概的回顾一下：\u003c/p>\u003cp>第一个我们M就是关于我们的信息，最好的方法就是贴标签。\u003c/p>\u003cp>第二个是成就事件，那么我们可以运用数字化的方式把我们做的事情给描述出来。\u003c/p>\u003cp>第三个就是V，我们要去挖掘里面能为他人提供哪些价值。比如我们读书啊！里面会有什么方法可以教给别人。\u003c/p>\u003cp>那么，我的分享到此结束，希望大家可以运用这个方法，做出一个让人印象深刻的自我介绍，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1686917558000,"updated_at":1687168048000,"ria":true},{"id":16036,"topic":"爆款写作课","learn_goal":"","remark":"当面对陌生人\n你是如何做自我介绍的？\n三步自我介绍，让自己一眼被记住。","level":"TF1-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"米岚","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>大家好，做个自我介绍。\u003c/p>\u003cp> 【自我介绍】：1分钟\u003c/p>\u003cp>我是米岚。大米饭的米，山风岚。这是我的笔名。我的三个标签：\u003c/p>\u003cp>第一个标签：重拾旧业的职场兼职人员。我是一名工程经营领域从业者，10年以上工程预算和合同签订的工作经验。\u003c/p>\u003cp>第二个标签：儿童阅读指导师。我有一家空中绘本馆，提供绘本借阅服务和儿童阅读指导的服务。\u003c/p>\u003cp>第三个标签：新手拆书家一枚。2023.4.17日官网注册会员，成为了分舵的一名正式会员。\u003c/p>\u003cp>下面进入我今天的主体内容。\u003c/p>\u003cp>刚才在开始前包括我在内大家都做了自我介绍。自我介绍是为了彼此认识，但如果介绍完了双方并没有记住彼此，是不是就没有起到这个作用呢？那怎样能够在短短的自我介绍中，让对方迅速记住你呢？\u003c/p>\u003cp>今天就给大家介绍一种自我介绍的方法。这个方法来自于《爆款写作课》这本书。这本书主要讲的是新媒体写作，作者总结了3个黄金法则，教给读者如何成为新媒体写作达人。而从书中我发现这个自我介绍方法，不仅可以在写作中使用，而且在生活中也可以运用。\u003c/p>","ratings_count":2,"texts":[{"id":20115,"quote":"\u003cp>【R】环节：半分钟\u003c/p>\u003cp>大家拆页都已经拿到手了，请大家用半分钟阅读原文拆页，阅读完请抬头示意我。\u003c/p>\u003cp>【原文片段】 MTV 法介绍自己片段来源《爆款写作课》\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出&quot;哇&quot;之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具， MTV 法则。\u003c/p>\u003cp>M 是英文单词 Me 的缩写，意思是你是谁？\u003c/p>\u003cp>T 是英文单词 Thing 的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V 是单词 Value 的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>","explains":"\u003cp>【I】环节：4-5分钟\u003c/p>\u003cp>【what】这个片段介绍了一种自我介绍的方法：MTV法则。\u003c/p>\u003cp>【how】它有这样三个步骤：\u003c/p>\u003cp>1、M即Me，意思是你是谁？\u003c/p>\u003cp>2、T即Thing，意思是你的成就事件有哪些？\u003c/p>\u003cp>3、V即Value，意思是你能提供的价值是什么？\u003c/p>\u003cp>【why】这个自我介绍的方法包括了我是谁，我做过哪些事，还有我能提供什么。最重要的就是“我能提供什么”，也就是自己的价值。它就像小动物的触角，可以触达到对方，对方就立刻接收到了信息，敏锐察觉自己是否需要你的价值提供。\u003c/p>\u003cp>记得上一次我参加咱们线下活动，有位会员，当时他的自我介绍就是快消品从业人员，有需要快消品的可以找他。说实话我没有记住这位会员的名字，但是我记住了他是做什么的，因为我之前做过很短时间的快消品微商。就让我觉得想要和他探讨探讨快消品的销售经验。这就是和我产生了链接。\u003c/p>\u003cp>使用MTV法则，可以让大家很清楚的知道什么样的事情可以向你寻求帮助，帮助介绍方彼此产生链接。\u003c/p>\u003cp>【个人例子】拆书帮的线下活动每一次都要做一下自我介绍。2023.3.25那一次是我第二次参加分舵的线下活动，我还记得当时我的自我介绍：“大家好，我是一位成长型的全职妈妈，也是一名儿童阅读指导师，拥有一家空中绘本馆，提供绘本借阅和儿童阅读指导的服务，我还是一名&#x27;预备一级拆书家&#x27;。”在我发言后，下一位朋友做自我介绍的时候，发言中就直接表示后面要加我微信，因为他是一名2岁女孩的爸爸。果然在中场休息时，这位宝爸主动找到我添加微信，想要咨询一下绘本借阅的事情。\u003c/p>\u003cp>我那一次的自我介绍，对比这个MTV法则，有M（Me），我是儿童阅读指导师，有V（Value），我能提供绘本借阅和儿童阅读指导服务，T（Thing）我是做空中绘本馆的，但我这里面说的不够充分，没有成就的部分，我应该加上我曾为多少个家庭提供服务。之所以我刚介绍完自己，就有小伙伴主动链接我，我想可能就是因为在我的自我介绍中包含了MTV三个方面，让对方可以一下明朗链接关键点。\u003c/p>\u003cp>【where】这个方法通常适用于职场或有组织的活动中，也适用于成年人之间。不适用于亲戚之间，和向小朋友做自我介绍。\u003c/p>","interaction":"\u003cp>【A1】环节：4-6分钟\u003c/p>\u003cp>下面我们分一下组。（当学习者总数超过6人时就近分组，每组至少2-3人。）\u003c/p>\u003cp>请大家回顾一下自己之前是怎么做自我介绍的，有没有由于自己不善于自我介绍而错失了一些与人链接的机会呢？\u003c/p>\u003cp>请大家小组内分享一下刚才的这个问题，每人1-2分钟的时间\u003c/p>\u003cp>（根据人数一共 分钟的时间。）\u003c/p>\u003cp>我来邀请 组选位代表来分享一下你们组的方法。2分钟\u003c/p>\u003cp>【学习者案例】学习者在5月份，第一次参加拆书帮线下活动做自我介绍的时候，自我介绍的内容只是抛出了标签，没有想过自己的成就事件和能提供的价值，也没有想到过要把成就事件和自己的价值在自我介绍时候说出来。\u003c/p>\u003cp>【A2】环节：1分钟\u003c/p>\u003cp>现在我们设想一个场景，假设你第一次去参加一场线下读书会或其他别的活动，开始之前需要做自我介绍，请每人按照“MTV法则”写一个这个场景下的自我介绍。\u003c/p>\u003cp>有时间请一位学习者分享。\u003c/p>\u003cp>【学习者案例】大家好，我叫张晓阳，三个标签简要介绍一下我自己：\u003c/p>\u003cp>第一个标签，我是一名时间管理践行者，目前已经践行一年多的时间，简书日更235天。我可以为大家提供时间管理践行的各类方法和小工具。\u003c/p>\u003cp>第二个标签是小物件心理疗愈师，青少年动力指导师，成功帮助一家三口抑郁的家庭走出阴霾。我可以给大家提供1v1心理疗愈以及1v1青少年学习动力提升。\u003c/p>\u003cp>第三个标签是八年异地恋修成正果的二宝妈，正走在幸福路上。大家有关情感的问题，也很欢迎来一起探讨交流。\u003c/p>\u003cp>可以看出学习者使用了MTV法则的三个方面，也让我对小物件心理疗愈产生了兴趣。感谢学习者的分享。\u003c/p>\u003cp>【结束语】以上就是我今天的全部内容，我今天介绍了自我介绍的“MTV法则”，希望对大家有帮助。感谢大家耐心听我的讲解。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1686639267000,"updated_at":1687341455000,"ria":true},{"id":16010,"topic":"自我介绍-MTV法","learn_goal":"","remark":"我们常常听说\"时间就是金钱,效率就是生命\"。在移动互联网时代，注意力等于时间，谁拥有了用户的注意力，谁就拥有了用户的时间，谁也就拥有了金钱。\n那么，我们在自我介绍时，如何抓住对方的注意力呢？\n6月9日，请来听我和你分享，如何使用MTV法做出让人眼前一亮的自我介绍，链接你我。\n\n","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"雪荔","city":"深圳市"},"club":{"name":"深圳桃李分舵","city":"深圳"},"prologue":"\u003cp>&lt;自我介绍&gt;\u003c/p>\u003cp>大家好,我叫李雪,用三个标签向大家介绍一下我自己:\u003c/p>\u003cp>1、学过正面管教的2个孩子的妈妈；\u003c/p>\u003cp>2、表达需提升的注册会计师；\u003c/p>\u003cp>3、保持学习、保持好奇心的“保保”；\u003c/p>\u003cp>很开心能和小伙伴们一起拆书打怪，共同晋级。\u003c/p>\u003cp>&lt;拆书帮介绍&gt;\u003c/p>\u003cp>原来我觉得学习枯燥，书本成为我最好的催眠工具，我努力的死记硬背，但是知识总是很快被我\u003c/p>\u003cp>遗忘,白白浪费了时间和精力。如何能让学过的知识不流失,并且为我所用呢?\u003c/p>\u003cp>使用“拆书”工具RIA便签法可以帮助学习者达到这个目的:\u003c/p>\u003cp>具体来说:\u003c/p>\u003cp>R便签代表(Reading),即阅读原文片段；\u003c/p>\u003cp>I便签代表（Interpretation),用自己的语言，对原文片段进行解读；\u003c/p>\u003cp>A便签代表（Appropriation),即关联自身相关经验反思，并规划后续具体的行动计划；\u003c/p>\u003cp>通过三张便签帮助学习者真正理解并应用知识，拆为己用。\u003c/p>\u003cp>拆书分为个人应用便签学习和现场引导学习者学习,通过学习能达到同主题培训的效果。\u003c/p>\u003cp>“拆书家”是经过专门便签训练营培训，掌握便签法后，选择站在台前和学习者一起磨练技能的\u003c/p>\u003cp>人，拆书家共有3大级，9小级,级数越高，难度越大。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵，是非营利性青年自组\u003c/p>\u003cp>织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":20086,"quote":"\u003cp>今天给大家介绍MTV自我介绍法,接下来请大家用1-2分钟读一下手中的拆页.读完可以抬头示意\u003c/p>\u003cp>我一下。\u003c/p>\u003cp>MTV法介绍自己片段来源《爆款写作课》\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方联接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜\u003c/p>\u003cp>忌。\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以\u003c/p>\u003cp>解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价\u003c/p>\u003cp>值，那么对方就会联接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>我们参加活动经常会有自我介绍的环节，大家的自我介绍是不是经常都是，我叫什么？我来自哪\u003c/p>\u003cp>里？我从事什么工作？这类质朴的自我介绍呢？\u003c/p>\u003cp>这样的自我介绍能给他人留下深刻印象吗？显然不会！\u003c/p>\u003cp>\u003cstrong>WHY：\u003c/strong>\u003c/p>\u003cp>如何才能让他人对你产生兴趣，留下深刻印象，甚至想要主动联接你呢？\u003c/p>\u003cp>人际交往从实质而言是一个“价值互换”的场域。\u003c/p>\u003cp>自我介绍其实是一个在他人面前呈现自我价值的机会。\u003c/p>\u003cp>\u003cstrong>WHAT：\u003c/strong>接下来我给大家介绍一个一定会让他人留下深刻印象，并想要联接你的自我介绍法-MTV法\u003c/p>\u003cp>则。\u003c/p>\u003cp>MTV的M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是英文单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>\u003cstrong>HOW：\u003c/strong>让我结合一个具体的案例来演示一下具体怎么使用MTV法则。\u003c/p>\u003cp>第一步：说出我是谁，在这里需要重点突出介绍的是：我是一个具备〇〇能力的人。\u003c/p>\u003cp>（比如，我叫李雪，专业的瑜伽教练，持有国际瑜伽教练证书）\u003c/p>\u003cp>第二步：说出我的成就事件。说出成就事件是一份信任状，是对刚才所讲的自己的能力的进一步\u003c/p>\u003cp>佐证。\u003c/p>\u003cp>（比如，有一次我们和其他妈妈在一起等待孩子下课期间，看到有位妈妈身体紧张，就走过去教\u003c/p>\u003cp>了她几个舒缓瑜伽的动作，她立刻觉得身心放松了很多。然后一群妈妈都围过来说要学这几个动\u003c/p>\u003cp>作。从此等待孩子放学的时间成为妈妈们跟我学瑜伽的时间。）\u003c/p>\u003cp>第三步:说出我可以为你提供的价值。\u003c/p>\u003cp>（如果你平时会有腰酸背疼，身体紧张的状态，可以来找我，我可以免费给你支几招哟！）\u003c/p>\u003cp>\u003cstrong>WHERE:\u003c/strong>MTV法适用于和想结交成朋友的陌生人第一次见面、工作面试、推销产品及沙龙活动等。\u003c/p>","interaction":"\u003cp>A1关联过往\u003c/p>\u003cp>上周参加财富流沙盘推演游戏活动，一桌人一起玩，玩之前老师先起了个头进行自我介绍，大家\u003c/p>\u003cp>都按我叫什么，哪儿人，从事什么工作。进行了一圈自我介绍,等到1个小时游戏结束后，大家\u003c/p>\u003cp>一起互加微信的时候，我发现大家还是会问一遍，你叫什么来着，你是做什么的？这样的自我介\u003c/p>\u003cp>绍完全没有被记住。因为我们的自我介绍没有呈现我的自我价值,也没有呈现价值交换点。\u003c/p>\u003cp>A2规划未来\u003c/p>\u003cp>阅读了MTV法则的书，在近期要如何运用在生活中呢？\u003c/p>\u003cp>周末去参加鼓励咨询的课程，我可以用MTV法则来向大家介绍我自己。\u003c/p>\u003cp>M，大家好，我是李雪。我是一个逢考必过的学习能手。\u003c/p>\u003cp>T，我在刚参加工作时，利用工作之余的时间考取了注册会计师；备考两周时间，考取了证\u003c/p>\u003cp>券从业资格证和基金从业资格证；我在生了宝宝之后，学习了正面管教，并一直带着觉察持续学\u003c/p>\u003cp>习和实践；我在困惑夫妻相处之道时，学习了幸福婚姻；我在对人生之路迷茫时，来参加了鼓励\u003c/p>\u003cp>咨询。\u003c/p>\u003cp>V，能和大家在这里一起参与鼓励咨询课，相信大家都想在课程里有所收益获得成长，在此\u003c/p>\u003cp>期间，如果你自己或你孩子缺乏学习力，缺乏学习方法，可以来联接我，我可以告诉你逢考必过\u003c/p>\u003cp>的秘诀，我还可以和大家一起交流日常生活中如何应对孩子的挑战；探讨各种财务问题；让我们\u003c/p>\u003cp>通过学习和练习，互相鼓励、互相赋能。很高兴认识大家！\u003c/p>\u003cp>这样介绍你记住我了吗？\u003c/p>\u003cp>今天的分享到此结束,感谢大家的倾听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1686467320000,"updated_at":1686468307000,"ria":true},{"id":15944,"topic":"用MTV法做一分钟自我介绍","learn_goal":"","remark":"新媒体写作是隔着屏幕和读者说话。把读者当朋友，用聊天的语气和对方沟通，一个人会说话就会写作。新媒体写作是把文字当做产品。通过主题、标题、内容和互动来满足用户需求，帮助他解决问题、表达观点和塑造形象。新媒体写作是和用户心智做竞争。通过故事、细节、案例和数据，做到吸引眼球、打动人心和理性说服，最终让用户行动。所谓的爆款文章都有迹可循，以价值为内核，用情绪做外衣。通过理性和感性满足用户需求，从而获得广泛传播。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"占春","city":"上饶市"},"club":{"name":"上饶光阴分舵","city":"上饶"},"prologue":"\u003cp>\u003cstrong>开场（自我介绍1分钟）：\u003c/strong>\u003c/p>\u003cp>各位好，今天开始实践我的TF1-1现场过级，今天的内容分为三个部分，第一部分就是我的自我介绍；第二部分是介绍拆书和拆书帮；第三部分是今天的主题MTV法自我介绍拆页。\u003c/p>\u003cp>我姓余，年年有余的余；名占春，占春、占春当然霸占不了整个春天，父亲取名占春是希望我在重男轻女的环境中能巾帼不让须眉依然占尽春光。我是一个有着丰富实操经验的HR,国家三级心理咨询师、终生学习者，善于倾听。\u003c/p>\u003cp>我个人成长成就是，在13岁时由于不读书，被父亲流放到杭州闸弄口菜场卖了一年的菜，觉醒了自我的同时成为了菜场的小精灵销量不输甚至远超成人，后不负父亲所望从重男轻女的偏远乡村冲破思想的禁锢和现实的阻碍成为了村第一个大学生而且是女生，如今成为终生学习者。 \u003c/p>\u003cp>如果你自卑、迷茫发现不了自己的优点可以找我，我最擅长发现别人的长处。\u003c/p>\u003cp>\u003cstrong>拆书帮介绍（2分钟）\u003c/strong>\u003c/p>\u003cp>很多人好奇拆书帮是个什么样的组织？什么是拆书呢？下面我来介绍下我认识的拆书帮和拆书法。\u003c/p>\u003cp>拆书帮是基于拆书法的学习爱好者社群，表现为各地拆书帮分舵，其使命是帮助更多学习爱好者成为拆书家，释放学习促进者的能量，是非营利性青年自组织。\u003c/p>\u003cp>什么是拆书呢？拆书并不是把书拆了或者撕掉，拆是转化和内化，是一种学习方法论，就是把书本中的拆页知识转化为学习者自己的能力，拆为己用的过程。适用于成人学习用以解决实际问题、提升个人能力的一种学习方法。\u003c/p>\u003cp>“拆书”分为个人学习和组织学习两种。个人学习通过RIA便签学习法，让人读一本致用类图书达到参加同主题培训的效果；组织学习依靠RIA现场学习，又叫拆书家现场带拆，由拆书家用一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。一位拆书家创造的价值不亚于一个培训师。\u003c/p>\u003cp>重点介绍下拆书帮魔法棒，RIA便签法。R：reading（阅读片段），I：interpretation（用自己的语言重述信息），A：appropriation（描述自己的相关经验；我的应用，目标和行动，将其拆为己用）\u003c/p>\u003cp>这就是拆书帮，一群积极向上爱好学习者的舞台。欢迎爱学习的你。\u003c/p>","ratings_count":1,"texts":[{"id":20035,"quote":"\u003cp>\u003cstrong>R原文片段（2分钟）:\u003c/strong>\u003c/p>\u003cp>过渡：下面我们一起阅读以下这个片段\u003c/p>\u003cp>片段来源《爆款写作课》P30\u003c/p>\u003cp>主题：MTV法介绍自己\u003c/p>\u003cp>自我介绍中梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁?\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件?\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值?\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>比如，一个制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询:\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲?\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣?\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己?\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。理财的朋友可以协助配置家庭资产;读书很厉害的朋友可以帮助提高阅读速度;跑步的朋友可以解答坚持跑步过程中的疑惑;做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力(品类和标签)，说出成就事件(信任状)，说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>\u003cstrong>I拆书家讲解引导（4分钟）:\u003c/strong>\u003c/p>\u003cp>接下来我将从是什么？为什么？怎么做以及适用边界四个方面来讲解下我对该片段的理解：\u003c/p>\u003cp>（What）该片段讲述了如何用MTV介绍自己。运用MTV法简单具体表达出你是谁？能做什么？能提供怎样的价值？让对方清晰的了解你，知道你的价值并与你产生有效链接成功打造自己的品牌，大家可以思考下自己是谁？能做什么？能提供怎样的价值给到他人？ \u003c/p>\u003cp>（Why）:如果他人不能清晰了解你的价值很难和你产生链接，因为只有简单清楚的让别人知道你是谁，能做什么，能提供怎样具体的价值才能获得别人的链接，别人才能从你的介绍中\u003cstrong>找到需求点\u003c/strong>来选择你这样的品牌。\u003c/p>\u003cp>那么具体怎么做到这么棒的自我介绍呢？让我一起来看看具体操作方法。\u003c/p>\u003cp>（How）具体操作步骤如下：\u003c/p>\u003cp>1、M（me）：你是谁？比如我一名优秀的形象设计师等等。\u003c/p>\u003cp>2、T（thing）:你做过什么成就的事？比如成功将XX包装成功推广了XX使得对方获得了一份很好的工作。\u003c/p>\u003cp>3、V（value）：你能提供什么价值？比如可以提供如何借鉴明星包装经验推广自己。\u003c/p>\u003cp>（where）：MTV适用于初次见面、接触时长有限、演讲等需要连接他人、推销自己的场合进行自我介绍。因为要在很短的时间进行自我介绍并推广自己个人品牌，这种情况适用MTV法可以让人轻松清晰的认识你并根据自己的需求来链接到你。\u003c/p>","interaction":"\u003cp>\u003cstrong>A：拆为己用\u003c/strong>\u003c/p>\u003cp>过渡语：通过上面的讲解相信各位优秀的小伙伴对MTV自我介绍法都有了一定的理解，下面我来分享一个我曾经的自我介绍经历来帮助大家更深入的了解MTV自我介绍法的魅力。\u003c/p>\u003cp>\u003cstrong>A1：（1分钟）2023年5月8号\u003c/strong>参加拆书帮14天训练营的第一天，教练积极高效的给我们开了一个腾讯会议并让大家各自简单介绍了自己。大致记得当时我的介绍是---我是余占春，毕业于华东交通大学，本科工商管理，从事人力资源工作，因为这几年从未思考过自己的标签。还是听到前面的人介绍自己是宝妈，心理咨询师培训师等，我才想起自己也是宝妈，也考了国家心理咨询师三级证书，谈及成就我感觉是人生平淡无奇并无啥大成就，因为从未回顾思考过自己。听了大家的介绍觉得自己的介绍没点新意和特点，很难让别人事后和我产生链接估计都不记得啥。听了这样的介绍小伙伴们听了是不是就过了，过了就想不起来了，哈哈。\u003c/p>\u003cp>让我们一起分析不成功的原因：1、没体现成就事宜，让别人知道我的成功经验；2、没有体现价值，别人不知道我能做啥；3、没有认真思考过自己的自我介绍。\u003c/p>\u003cp>结论：反思自己，需要对自己的自我介绍模式进行改进，在这种陌生场合，初次见面或者演讲等开场介绍，需要推销展现自己并使他们能更好连接自己的场合中运用MTV法来介绍自己让别人更清晰的认识自己，打造自己的个人品牌。\u003c/p>\u003cp>\u003cstrong>A2：（4分钟）未来\u003c/strong>目标：下次周六分舵线下活动自我介绍时，用MTV自我介绍法链接他人。\u003c/p>\u003cp>1、 分舵线下活动需要进行自我介绍，我做好提前准备；\u003c/p>\u003cp>2、 轮到我介绍的时候用MTV 法介绍:\u003c/p>\u003cp>M（me）：你是谁？（我是余占春，一个有着丰富实操经验的HR,国家三级心理咨询师、劳动关系协调员，终生学习者，善于倾听）\u003c/p>\u003cp>T（thing）:你做过什么成就的事？（1、在13岁时由于不读书被父亲流放到杭州闸弄口菜场卖了一年的菜觉醒了自我的同时，成为了菜场的小精灵销量不输成人甚至远超2、不随波逐流，爱挑战的我从重男轻女的偏远山村冲破思想的禁锢和现实的阻碍成为了那个村第一个大学生；3、一边工作一边带娃，在别人觉得女孩子婚后有孩子这辈子就这样时，不放弃自我提高和觉醒的我参加全国研究生统考并于今年成功考取南昌大学工商管理研究生）。\u003c/p>\u003cp>V（value）：你能提供什么价值？如果你自卑发现不了自己的优点可以找我，我最擅长发现别人的长处。如果你也想考研究生可以找我，我可以分享对你有利的经验给你。如果你是宝妈觉得婚后没有自我可以找我，我会教你如何时间管理；如果利用自己的现有的资源来帮助自己找回自我。\u003c/p>\u003cp>3、 主动链接自卑的小伙伴，把我发现她的长处告诉她。\u003c/p>\u003cp>结语:好的，大家都非常棒，今天的拆书分享到此结束，感谢各位小伙伴的陪伴和积极参与，在前行的路上我们又进步了一点点。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1685928523000,"updated_at":1689843167000,"ria":true},{"id":15688,"topic":"自我介绍MTV法则","learn_goal":"","remark":"你的“名号”比名字更重要，让人从记住你、认可你、选择你！","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"晨捷","city":"太原市"},"club":{"name":"太原黄河分舵","city":"太原"},"prologue":"\u003cp>【开场】15秒\u003c/p>\u003cp>过渡语：各位老师好！通过2次线下活动的相聚以及TF1-1的过级大家对我已经比较熟悉了，感谢再次陪伴。\u003c/p>\u003cp>【分组】1分钟\u003c/p>\u003cp> 今天到场的一共X位老师，恰好是两组的最佳人数，我按照会议成员的名单顺序，将单数为一组、双数为一组，学习过程中会有组内发言和分享学习的互动环节，还请大家积极参与，每次参与都是一次非常好的学习。\u003c/p>\u003cp>【介绍图书】1分钟\u003c/p>\u003cp> 上一趴用了三个标签M-人才的发动机HRD履历、T-深度学习人、V-全流程的人力服务，就是运用了今天的主讲内容”自我介绍MTV法则”，片段来源于《爆款写作课》一书。\u003c/p>\u003cp>本书的作者曾为世界500强外企职业经理人弗兰克，33岁起从0开始写作，两年后做自媒体收入100万，并且用了3年时间潜心钻研和15期线上训练营教学和实践验证，独创了吸引、打动、说服写作3步法，只要咱们会说话就一定会写作。选取本书有2个原因，从我们个人角度来讲，名号就是我们自己的标签，名号比名字更重要，为自己贴个有价值的标签，呈现和传播之后就是我们的个人品牌；从读者角度看，我们如何将他们作为朋友，实现隔着屏幕来聊天便是写作的技巧。\u003c/p>","ratings_count":2,"texts":[{"id":19756,"quote":"\u003cp>【R片段 阅读原书拆页】1分钟\u003c/p>\u003cp> 过渡语：我提前为各位老师准备了一个小片段可以看屏幕也可以阅读我发的拆页，阅读完成后请抬头示意我。\u003c/p>\u003cp> 梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了这里我要向你介绍一个做自我介绍的工具，MTV法则。M是英文单词Me的缩写，意思是你是谁?T是英文单词Thing的缩写，意思是你做过什么成就事件?V是单词Value的缩写，意思是你能提供什么价值?这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp> 比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询:1.普通人如何做出属于自己的歌曲?2.如何成功脱单，找到自己的心灵伴侣?3.个人品牌时代，如何借鉴明星包装经验推广自己?当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。理财的朋友可以协助配置家庭资产，读书很厉害的朋友可以帮助提高阅读速度，跑步的朋友口以解答坚持跑步过程中的疑惑，做演讲的朋友可以提升公众演讲能力。当我们在自我介绍中说出能力 (品类和标签)，说出成就事件(信任状) ，说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>【I便签】2分钟\u003c/p>\u003cp>What：\u003c/p>\u003cp> 在人际交往中常常会需要自我介绍，30秒左右的时间不仅要让对方清晰知悉你的身份、已有成就和带来的价值体现，还要展示出可信度取得对方好感、关注与信任。MTV法则是一个自我介绍的工具，具体释义为M-me（我是谁？）、T-thing（我在对应领域取得过哪儿些成就？）、V-value（我可以为您提供哪儿些服务和价值？）。\u003c/p>\u003cp>Where：\u003c/p>\u003cp> MTV法则适用范围广泛，对象可以是个人也可以是团队，应用于自我营销、结交朋友、商务会谈、培训演讲，甚至是电话沟通等不同场合。建议事先梳理一份完整的自我介绍，需注意在阐述个人成就和价值体现时，还应匹配对方的身份和诉求，对细节进行适时调整。\u003c/p>\u003cp>Why:\u003c/p>\u003cp> 相信大家都熟悉首因效应也就是第一印象的重要性，一个好的自我介绍成为整个相处中好的开始，我们所陈述的价值点成功链接到对方，能达到让听者“哇塞”的作用，从而取得对方关注和信任。\u003c/p>\u003cp>How：\u003c/p>\u003cp> 那究竟应该如何做呢，请随我一起揭秘——用好“我成家”，打响我的名号。\u003c/p>\u003cp> 1.我（M-me）:在介绍我是谁的部分，需要有完整性表述，可有利的借助所处平台和职位的光环，提升沟通层次；但需注意，此处一定是要和本次见面的对象或者授课、演讲的主题有强关联。\u003c/p>\u003cp> 2.成（T-thing）:在做能力介绍时及时给自己贴标签，过往曾取得XXX成就，为对方加深印象取得信任。\u003c/p>\u003cp> 3.“家”（V-value）:基于以上的成功经验，能为您的XXX带来价值；实现value提取，为后面的会谈或者内容讲述来打开机会。\u003c/p>","interaction":"\u003cp>【A1激活经验】5分钟\u003c/p>\u003cp> 通过对拆页的理解，已经掌握了MTV的使用，那么请大家回忆下自己的过往经历，有没有掉过类似我这样的坑，每人1-2分钟讨论一下吧。\u003c/p>\u003cp> 1分钟的时间，想发言的伙伴可以分享一下曾经那个尴尬的自我介绍。\u003c/p>\u003cp>分享一：【韩娟】\u003c/p>\u003cp> 我回想到有一个尴尬的自我介绍，是在单位带员工做拆书活动时，开场做自我介绍包含了公司现在的职务、获得职称以及心理咨询方面的证书和荣誉，但是只字未提拆书相关的内容，以致于同事们都不清楚我在拆书方面有过什么样的经验。\u003c/p>\u003cp>【A2催化应用】4分钟\u003c/p>\u003cp> 有了故事就催生了行动，请大家2分钟内设计一份最想展示给大家的自我介绍，并完成学以致用的行动步骤吧，届时将有3分钟的时间来分享给大家。\u003c/p>\u003cp>分享二：【刘欣】\u003c/p>\u003cp> 大家好，我是刘欣。\u003c/p>\u003cp> 在学完MTV模型的时候，也特别想更新一份自我介绍。三个步骤：1.先梳理了自己的经历和热爱的事情——曾经在学校、企业和社区工作，喜欢人与之间的沟通；2.思考我是谁、为过往业绩贴标签，来增加和大家的粘性——考取过心理咨询师，目前在公司工会从事着员工心理咨询工作，我有资质也有权威性；3.最后提炼出来我的价值——可以为大家提供团队心理咨询辅导和OH卡培训。以上三点，希望下一期OH卡活动的时候按照这个模型来充分介绍自己。\u003c/p>\u003cp>【结语】我们今天的学习已经进入尾声了，祝贺大家都有所收获，也希望很快就能将这份崭新的名片递出去，感谢支持。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1682306095000,"updated_at":1694956722000,"ria":true},{"id":15617,"topic":"MTV法介绍自己","learn_goal":"","remark":"【主题介绍】做自我介绍，其实就是一个做减法的过程，在过去的经历中，找到最亮点的成就事件，找到关键数据做支撑，然后尝试和对方连接。\n【书籍介绍】弗兰克，曾为世界500强外企职业经理人，2015年33岁起从0开始写作，2017年做自媒体收入100万。3年时间潜心钻研写作章法与逻辑，2017年7月1日，10小时找到1万付费会员。通过15期线上训练营教学和实践验证，独创了新媒体写作3步法——吸引、打动、说服。他主张会说话就会写作，普通人只要遵循技巧，也能写出10W+。作者详细拆解了爆文的构成元素，手把手教你从选题立意牢牢抓住读者眼球，循序渐进打动和说服读者，最终将文字变现。掌握简单的方法，让你成为新媒体写作高手。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"小熊123","city":""},"club":{"name":"南宁清澄分舵","city":"南宁"},"prologue":"\u003cp>\u003cstrong>自我介绍：\u003c/strong>\u003c/p>\u003cp>大家好，我叫小熊。我用三个标签来介绍我自己。第一个标签我是一名设计师，平时的工作是画图，比如要建设一座桥梁，我们设计师先设计好图纸，然后交给工人师傅们按照图纸绑扎钢筋、浇筑混凝土，最后一座崭新的桥梁就建成了。第二个标签是慢跑爱好者，由于平时加班比较多，我每周都会进行1-2次慢跑，通过慢跑来缓解内在的压力，放松自我。第三个标签是随笔爱好者，我从高中开始坚持写随笔，已经写了13年的随笔，随笔伴随我度过快乐、悲伤、平淡的时光，也陪伴我一路成长。\u003c/p>\u003cp>今天我给大家分享的拆页是《爆款写作课》里面的“MTV法介绍自己”，这本书的作者是弗兰克，他曾为世界500强外企职业经理人，独创了新媒体写作3步法——吸引、打动、说服。\u003c/p>\u003cp>希望通过今天的学习我们能够用“MTV法”自我介绍，更好的展现自己。\u003c/p>\u003cp>\u003cstrong>分组：\u003c/strong>\u003c/p>\u003cp>首先给大家小小的提示一下，我们今天的拆书活动会有分组讨论环节，下面我先简单给大家分一下组，坐在左手边的小伙伴为第一组，中间的小伙伴为第二，右边的小伙伴为第三组，一会在我讲解完后会进行分组讨论。\u003c/p>\u003cp>下面，请大家用1分钟的时间阅读拆页内容，阅读完毕后请抬头向我示意。\u003c/p>","ratings_count":2,"texts":[{"id":19681,"quote":"\u003cp>\u003cstrong>原文选自拆页《爆款写作课》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>M是英文单词Me的缩写，意思是你是谁？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>V是单词Value的缩写，意思是你能提供什么价值？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.普通人如何做出属于自己的歌曲？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.如何成功脱单，找到自己的心灵伴侣？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/strong>\u003c/p>","explains":"\u003cp>好的，看到很多小伙伴抬我向我示意，相信大家已经阅读完毕。下面由我来和大家分享一下我对这段话的理解。\u003c/p>\u003cp>【Why】我们每个人都是独一无二的个体，如何让小伙伴们能够快速地记住自己，如何才能高效精简地亮出自己的名片，让对方对你“过目不忘”？今天，就由我向大家介绍一种高效地自我介绍的方法。\u003c/p>\u003cp>【What】这种方法叫做MTV自我介绍法\u003c/p>\u003cp>M就是Me：我是谁？\u003c/p>\u003cp>T就是Things：事情，我做过哪些有成就的事？\u003c/p>\u003cp>V就是Value：价值，我能为大家提供哪些价值？\u003c/p>\u003cp>【How】在MTV法介绍的过程中我们需要做到以下三点：\u003c/p>\u003cp> 1、说明自己能干什么\u003c/p>\u003cp> 2、简单描述自己做过的有成就的1～2件事。\u003c/p>\u003cp> 3、能为他人提供什么价值\u003c/p>\u003cp> 通过以上三点，就可以比较容易地取得他人信任并获取主动链接，为个人树立良好品牌形象。\u003c/p>\u003cp>下面我以自己为例讲述如何使用MTV法介绍自己：\u003c/p>\u003cp>1、M(ME)   这里指的是“我”，也就是要介绍我的特征，叫什么名字，从事什么工作等？例如：我叫小熊，是一名工程师，到现在已经工作了3年，目前从事于交通基础设施设计。\u003c/p>\u003cp>2、T(Thing）  这里翻译过来是“事情”，在MTV法中指代有成就的事情，也就是要讲述我做了哪些有成就的事，说1～2件就可以。例如：我从高中开始坚持写随笔，一直保持这个习惯13年。。\u003c/p>\u003cp>3、V（value） 这里翻译过来是“价值”，也就是大家常说的价值点、闪光点，可以理解为我身上哪些价值点是对周围的小伙伴有帮助、有吸引力。例如：由于工作的原因，我对cad画图还有三维建模比较擅长，可以给大家提供cad画图的简单入门教学。\u003c/p>\u003cp>同时，我也擅长打乒乓球，可以和大家分享一些乒乓球快速入门小技巧，这就是我的value。\u003c/p>\u003cp> 【Where】\u003c/p>\u003cp>MTV法的适用范围比较广泛，例如在交友方面，我们可以将这个方法运用在学习社群里的自我介绍，让其他小伙伴更深入的了解自己，从而产生链接；其次，MVT法也适用于在演讲和培训方面，应用MTV法可以让观众明白来听演讲的价值；当然，这个方法也可以运用在职场求职，通过MVT法可以让面试官对你印象更加深刻，让我们更有机会争取到一份满意的工作。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1-激活经验：\u003c/strong>\u003c/p>\u003cp> 好的，相信大家通过我的讲解，已经对MTV自我介绍法有了初步了解，那么请大家回忆一下，在平常生活中，大家都是怎么样介绍自己的呢？比如在读书阶段班级里的迎新晚会上，或者在大家第一次参加拆书帮活动的时候，又或者在公司刚入职的第一天等等场景，大家自我介绍完之后，现场效果如何？过后有没有小伙伴主动添加联系方式？大家可以在小组里相互交流。本次小组讨论时间为3分钟。\u003cbr> 看到各组小伙伴讨论得都很热烈，有哪位小伙伴愿意来分享一下呢？好，下面我们就有请十七来分享一下自己的过往经验，大家掌声欢迎～\u003c/p>\u003cp>\u003cstrong>A1- 学习者案例记录：\u003c/strong>\u003cbr>\u003cstrong> 十七分享：\u003c/strong>\u003c/p>\u003cp>\u003cstrong> \u003c/strong>我面对不同的人群，不同的场合的时候，在自我介绍时会有不同的侧重点。比如在工作场合，我在自我介绍的时候，会更多地侧重于介绍自己工作上的事情，比如介绍自己岗位的情况、工作的职责、公司的特点等。但是对于MTV法中的第三点“价值”，如何挖掘自身的价值这一块，可能还是缺少相关的思考，比如我在第一次来参加拆书帮线下活动的时候，在自我介绍时，只是简单地介绍了一下自己个人的基本信息，但是对于自己能给小伙伴提供什么价值这一块，当时没有过多地思考，这一块还有待加强。\u003c/p>\u003cp>\u003cstrong>A2-催化应用：\u003c/strong>\u003c/p>\u003cp>听完这位学习者的分享，我们是不是有一种似曾相识的感觉呢？其实自我介绍的方法有很多，但是MTV法介绍自己更能吸引大家的注意力，让大家对你有一种“过目不忘”的感觉。下面是实践应用环节，请大家按照MTV法的步骤在便签纸上写下自我介绍，然后在下一次参加拆书帮线下拆书活动的时候，运用今天标签上的内容来介绍自己，下面给大家1分钟的时间，大家开始应用起来～\u003cbr> 好的，看到大多数小伙伴已经写好了，1分钟就可以完成MTV法介绍自己，这就是MTV法的魅力！\u003cbr> 我今天的拆书到此结束，谢谢大家。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1681738334000,"updated_at":1682047763000,"ria":true},{"id":15511,"topic":"拆页主题:MTV法介绍自己","learn_goal":"","remark":"这一拆页主要是告诉我们如何用MTV法介绍自己，能够让对方一目了然知道自己是谁、能做什么、能够给对方提供什么价值，做到相互坦诚，不用相互猜忌，并且让对方容易记住自己。","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"徐怡芳","city":"兰州市"},"club":{"name":"兰州金城关分舵","city":"兰州"},"prologue":"\u003cp>【自我介绍】：\u003c/p>\u003cp>大家好！我是徐怡芳，我的三个标签是：\u003c/p>\u003cp>1、 拥有18年的餐饮运营加盟经验\u003c/p>\u003cp>2、 44岁从零出发，开启创业之路\u003c/p>\u003cp>3、 双胞胎女儿的妈妈，希望通过自己的学习和践行帮助更多的家长在育儿道路上少走弯路，看到家庭教育的初心—家长被滋养成长，才有肥沃的土壤养育孩子\u003c/p>\u003cp>人生，就是一场自己与自己的较量：让积极打败消极，让快乐打败忧郁，让勤奋打败懒惰，让坚强打败脆弱。在每一个充满希望的时候，告诉自己：努力，就总能遇见更好的自己。\u003c/p>\u003cp>【图书推荐】：\u003c/p>\u003cp>今天给大家分享的拆页选自《爆款写作课》，作者；弗兰克\u003c/p>\u003cp>Feature：特征 \u003c/p>\u003cp>弗兰克，曾为世界500强外企职业经理人，2015年33岁起从0开始写作，2017年做自媒体收入100万，主张会说话就会写作，普通人只要遵循技巧，也能写出10W+\u003c/p>\u003cp>Advantage：优势 \u003c/p>\u003cp>这是一本非常畅销的书，被知名作者剽悍一只猫老师极力推荐过，还荣登CCTV2的《第一时间》栏目受主持人高度赞誉。与同类书籍相比较，这本书是讲述实用方法和技巧，如果你想在短时间里成为一名写作10万+爆文，那么本书就是你很好的选择。\u003c/p>\u003cp>Benefit：价值\u003c/p>\u003cp> 今天的拆页是自我介绍里一种非常好用的MTV自我介绍法，学习完，你能掌握三个步骤，让你轻松应对职场、生活中不知道如何做自我介绍的窘境。\u003c/p>","ratings_count":2,"texts":[{"id":19558,"quote":"\u003cp>\u003cstrong>下面请大家花2分钟的时间阅读拆页，读完后请举手示意我。\u003c/strong>\u003c/p>\u003cp>【R原文片段】MTV法介绍自己P64-65\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp> 比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>\u003cstrong>好，我看到大家已经看完拆页了。接下来，我分享一下自己的理解和体会。\u003c/strong>\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>这一片段主要观点告诉我们如何用MTV法介绍自己，能够让对方一目了然知道自己是谁、能做什么、能够提供什么价值，做到相互坦诚，不用相互猜忌，并且让对方容易记住自己。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>每个人都想在一个陌生的环境里，通过自我介绍，让别人认识并链接自己。但是我们大多数的自我介绍最多传达的信息是:\u003c/p>\u003cp>你是谁？来自哪里？从事什么职业？有什么兴趣爱好？\u003c/p>\u003cp>但是这样的自我介绍并不能让别人和你起到链接和交流，顶多是当下知道有这样一个人，那么我们要想通过自我介绍让大家短时间认识你，认识你的的好处，并开始对你感兴趣，愿意和你继续展开下面的交流。\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp> MTV法介绍自己，具体步骤如下:\u003c/p>\u003cp> 1、M 是英文单词 Me 的缩写，意思是你是谁？\u003c/p>\u003cp>比如:我是徐怡芳;或者是正面管教、SEL社会情感教育讲师BOBO老师;又或者是两个双胞胎女孩的妈妈;又或者是具备18年餐饮运营加盟经验的徐老师\u003c/p>\u003cp> 2、T 是英文单词 Thing 的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>比如: 完成50梯储备干部的培育及输送;22年疫情期间带领一家餐饮门店，做到全年利润盈利100万; 辅导门店管理和运营300+以上；餐饮运营管理经理人成功转型家庭教育的讲师。\u003c/p>\u003cp> 3、V 是单词 Value 的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>比如:我可以帮助你搭建新开餐饮店的运营系统;我可以帮助你辅导规划家庭教育一对一咨询服务；我可以帮你辅导0-12岁的孩子成长规划\u003c/p>\u003cp>【WHERE】\u003c/p>\u003cp>这个片我们过往的介绍角度是从介绍者自己的角度出发，没有较强的目的性，容易被遗忘。而MTV法介绍结构，完全从听众的角度出发，告诉对方，我对你的价值。让对方迅速捕捉到自己需要的讯息，进行链接。并且也符合现在个人IP形象打造。\u003c/p>\u003cp>MTV法介绍适合运用场景:\u003c/p>\u003cp>1、新加入一个团队，比如我们拆书帮学习\u003c/p>\u003cp>2、进行公开课的演讲\u003c/p>\u003cp>3、网络直播课\u003c/p>\u003cp>4、求职应聘面试\u003c/p>\u003cp>5、推广并拓展自己的品牌和业务\u003c/p>\u003cp>以上个人觉得MTV方法更适用于商用，而不适用于平时结交朋友的介绍。\u003c/p>\u003cp>【成功案例】：现在我就分享一个发生在我自己身上的成功案例\u003c/p>\u003cp> 时间：2023年 人物：家长、孩子 场景：线上课程 地点：网络、家\u003c/p>\u003cp> 每次新开少儿情商课程一阶段班，我都需要给孩子和家长们进行自我介绍\u003c/p>\u003cp>M部分：大家好，我是BOBO老师，同时也是一名正面管教、SEL社会情感教育讲师，也是两个双胞胎女儿的妈妈\u003c/p>\u003cp>T部分：14年教练辅导经验；线上开展20梯少儿情商课程；帮助50+以上家庭一对一进行教育咨询\u003c/p>\u003cp>V部分：帮助你辅导梳理家庭教育一对一咨询服务；帮助辅导你0-12岁的孩子成长规划\u003c/p>\u003cp>希望通过我的成功案例，能够让大家接下来的学习有所启发。\u003c/p>","interaction":"\u003cp> \u003cstrong>（拆书家A1提问设计）\u003c/strong>\u003c/p>\u003cp>好的，刚刚我讲解了原文片段，还分享了发生在我自己身上的一个小故事。那么接下来请每组的伙伴们用2分钟的时间各自回忆一下：\u003cstrong>你曾经自我介绍的一个经历\u003c/strong>\u003c/p>\u003cp> 预计2分钟时间，请大家回忆一下\u003c/p>\u003cp>好的，2分钟时间到了，下面我们请伙伴们分享一下，大家欢迎。\u003c/p>\u003cp>1、如果今天的学习者可以自告奋勇，请开麦分享，给你1分钟。\u003c/p>\u003cp>2、不方便的开麦小伙伴，也可以把自己的分享扣在聊天区。\u003c/p>\u003cp>3、没有的话我就随机抽取幸运2位伙伴来分享。\u003c/p>\u003cp>我将给幸运伙伴各用1分钟的时间分享。\u003c/p>\u003cp>\u003cstrong>（学习者案例记录）\u003c/strong>学习者经验分享\u003c/p>\u003cp> 案例1：我分享刚进入拆书帮，进行学员介绍的经历，在介绍的过程中针对我的姓名和职业这部分会有详细的介绍，但是针对自己取得成就的事和自己的价值这部分平时缺少察觉和梳理，一般在介绍的过程中没有展示过这方面的信息，这部分今天有引发思考，接下来要学习调整自我介绍的方式。\u003c/p>\u003cp>\u003cstrong>（拆书家A2提问设计）\u003c/strong>\u003c/p>\u003cp>好，非常感谢这位小伙伴的分享。接下来，我们就规划一下，在不久的将来，怎样运用今天学习的MTV法做自我介绍。\u003c/p>\u003cp>我会给大家2分钟的时间，把行动规划写到便签纸上。\u003c/p>\u003cp>注意要符合以下格式：\u003c/p>\u003cp>1、 \u003cstrong>你未来什么时间使用？\u003c/strong>\u003c/p>\u003cp>2、 \u003cstrong>你会在什么场景使用？\u003c/strong>\u003c/p>\u003cp>3、 \u003cstrong>什么地方？\u003c/strong>\u003c/p>\u003cp>4、 \u003cstrong>如何具体使用MTV法自我介绍（依据M、T、V三步骤，逐一写下了）\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 大家可以参考PPT格式表来表述\u003c/strong>\u003c/p>\u003cp>写完的小伙伴请评论区回复2示意我\u003c/p>\u003cp>\u003cstrong>（学习者案例记录）：\u003c/strong>学习者应用\u003c/p>\u003cp>1、学员预计未来一个月内使用\u003c/p>\u003cp>2、学员准备在进入一个新的学习社群入群时的场景使用\u003c/p>\u003cp>3、学员准备在线上学习群使用\u003c/p>\u003cp>第一步M：大家好，我是李俊斌，我是一个来自甘肃兰州95后的刚步入职场的新人，我从事的是建筑行业工作，有4年多的工作经历。\u003c/p>\u003cp>第二步T：我曾经通过阅读书籍，找寻方法，自己实践，成功戒烟，我很高兴将我戒烟的经历分享给有同样需求的小伙伴\u003c/p>\u003cp>第三步V：我是从事建筑行业的，如果小伙伴们有需要新房验收、装修咨询方面的需求，可以找我。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>好的，我看到大家已经写下了具体的步骤，并且学会了如何使用MTV法自我介绍\u003c/p>\u003cp>最后，简单总结回顾一下今天学习的《爆款写作课》中MTV法自我介绍：\u003c/p>\u003cp>1、M 是英文单词 Me 的缩写，意思是你是谁？\u003c/p>\u003cp>2、T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>3、V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>以上就是我今天的分享，希望今天的学习可以让大家收获慢慢，并且生活中能够运用\u003c/p>\u003cp>我的分享就到这里，感谢大家的参加。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1680496866000,"updated_at":1682661701000,"ria":true},{"id":15351,"topic":"MTV介绍法","learn_goal":"","remark":"无","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"无求乃乐","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>请问观察家老师拿到记录表、准备表和拆页了么？\u003c/p>\u003cp>请问各位小伙伴都拿到我的拆页了么？好，现在正式开始今天的晋级。\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是吴乐。\u003c/p>\u003cp>感谢大家参加我的晋级，在开始之前，请允许我用三个标签介绍自己。\u003c/p>\u003cp>1、二宝妈：\u003c/p>\u003cp>我有一个14岁女儿、一个6岁儿子。我非常感恩孩子们的到来，给我打开了一个全新的世界，促使我不断学习，跟上孩子们的成长步伐。\u003c/p>\u003cp>2、双语阅读指导师：\u003c/p>\u003cp>我最初是为了孩子去学习成为中英文双语阅读指导师。在多年陪伴孩子阅读过程中，我践行家庭“悦”读，让阅读变成家庭生活中很自然的一部分。而现在反观效果，不仅有效提升孩子的阅读兴趣和能力，更重要的是激发了我自己的学习好奇心和内驱力，享受阅读带来的自然成长。\u003c/p>\u003cp>3、终身学习践行者：\u003c/p>\u003cp>陪伴孩子一起学习成长中，我持续输入、觉察、反思和行动。面对未来的不确定和更多的可能性，我更加坚定要践行终身学习，享受“以学为乐，以行促知”给我带来的丰盈与从容。\u003c/p>\u003cp>\u003cstrong>【关于拆书帮】\u003c/strong>\u003c/p>\u003cp>我的个人介绍有个关键词就是“学习”。这也是与拆书帮结缘之处。\u003c/p>\u003cp>第一次听说拆书帮，是我的朋友推荐，她身为三级拆书家的超强读书学习能力，让我心向往之。我虽然喜欢看书，但时间精力有限，如何有效地学为己用，提高学习效能，我带着这份好奇和期待来到拆书帮训练营体验。\u003c/p>\u003cp>进入训练营，我一下子就被社群里积极浓厚的学习氛围深深吸引，这是一群拆书法学习爱好者的社群，有趣有料有爱。在训练营里提升了我对拆书法的理解和运用，拆书法强调的是以学习者为主，把书中知识内化为学习者自己的能力，关联自己实际要解决的问题、或要提升的能力，并且落实到具体行动计划上，执行和调整，以便达成效果。\u003c/p>\u003cp> 随着训练营的顺利毕业，我获得进入【拆书帮】分舵的敲门砖。拆书帮在各地有分舵，方便学习爱好者们就近提升交流和互动，这是一个非营利性组织，它的使命是帮助更多学习爱好者成长为拆书家，相互陪伴，助人达己。它的价值观是陪伴赋能、拆为己用、反求诸己、持续精进、共同成长。在我刚入成都蜀汉分舵的短短几天，就参加了很多线上学习交流活动，还有我师父精心准备的各种指导分享和一对一的交流活动。从我师父和师兄师姐们身上，我切身感受到这种温暖、激励人心的积极学习力量，这与我内心的价值观和学习愿望特别吻合。我感到非常幸运，终于找到我向往和同频的学习型组织，学习路上不孤单，也非常期待在今后陪伴成长的路上，能跟随前辈们一路向前、越走越远。\u003c/p>","ratings_count":1,"texts":[{"id":19396,"quote":"\u003cp>关于拆书帮就介绍到这里，现在步入主题，请大家花2分钟时间看下我发给大家的拆页。\u003c/p>\u003cp>【拆解片段】《爆款写作课—MTV法介绍自己》\u003c/p>\u003cp>【R：阅读原文片段】\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp> M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp> T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp> V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp> 2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>好，大家已经看完拆页了，接下来我就分享一下我自己的理解和体会。\u003c/p>\u003cp>【WHY】: \u003cbr> 在面对陌生人的场合里，比如我们加入一个新的社群组织，通常都需要做\u003c/p>\u003cp>自我介绍，以便大家能更好地认识你。不知在这样的场景下，你会如何展\u003c/p>\u003cp>示自己？是侃侃而谈、自信满满，还是不知所措、焦虑慌张？我们还经常看到\u003c/p>\u003cp>很多自我介绍容易局限在介绍自己的优势或成就事件，对方听到可能当时会觉\u003c/p>\u003cp>得很牛啊，可惜过后依旧是毫无关系的路人。\u003c/p>\u003cp>我就经历过泛泛而谈、匆忙一带而过地介绍自己的窘境，事后想想又觉得有些遗憾，没能更好地与陌生人建立关系，让同好、同频的人能快速地认识我、连接我。\u003c/p>\u003cp>那有什么便捷的方法能帮助我们克服这种自我介绍的障碍？如何通过一个介绍内容就能快速地让对方记住我、走进我，为今后的彼此连接和互助打下基础？\u003c/p>\u003cp>【WHAT】：\u003c/p>\u003cp>在《爆款写作课》片段“MTV法介绍自己”拆页中就介绍了一种连接听者、有价值又简洁高效的自我介绍法则。为了便于记忆，我把MTV法用自己的语言加工为——“我是值得”。\u003c/p>\u003cp> “我是值得”法则与众不同的是，要介绍自己可以提供什么具体的价值点，这样能够建立彼此的连接，坦诚相待的同时，也让他人非常清楚以后有什么事情可以来找你协助和支持。\u003c/p>\u003cp> 【HOW】：\u003c/p>\u003cp> “我是值得”法则要如何做？\u003c/p>\u003cp> 第1步，“我”，介绍【我是谁】。\u003c/p>\u003cp> 第2步，“是”，事件的谐音，介绍【我做过的成就事件】，让他人清楚你能做什么。\u003c/p>\u003cp> 比如作为双语阅读指导师，我跟6岁孩子坚持6年亲子共读几千本书，并且督导协助多个家庭实现家庭阅读乐园。\u003c/p>\u003cp> 第3步，“值得”，介绍【我可以提供什么价值，对方可以得到什么协助】。这里需要提出较具体的价值点，让听者明白可以得到哪些方面的具体协助。\u003c/p>\u003cp> 比如，我可以为他人提供家庭阅读关键的指导，包括如何让父母避开阅读陷阱，如何提升孩子阅读兴趣，如何给适龄孩子选书，如何推进孩子英文水平提高等。\u003c/p>\u003cp> 【WHERE】：\u003c/p>\u003cp>“我是值得”法则适用于各种陌生场合推广自己，比如各种交流大会活动、新社群等，以便今后跟更多的人建立连接。\u003c/p>\u003cp>不过对于步骤2、步骤3，需要根据具体场合和目标群体的需求进行调整，比如我向拆书帮老师们自我介绍时会重点说学习相关的个人价值，如果跟同行工作交流时也许就是工作业务经验的价值点了。\u003c/p>\u003cp>同时，如果在某个场合，你并不想与他人有更进一步的交往，或者面对慢热型新朋友，这样介绍也可能会被误解成利益交换。所以，是否要采用“我是值得”法则，还是要分人分场合。\u003c/p>","interaction":"\u003cp>这个拆页是我在训练营的作业，我当时一看到这个拆页就觉得特别实用，我需要学会这个方法来改善我的自我介绍。\u003c/p>\u003cp>回忆我以前基本是采用比较笼统平淡的自我介绍，就是介绍自己的姓名，坐标，或者一些爱好，基本上没给他人留下什么深刻印象。\u003c/p>\u003cp>还记得2月11日我们训练营小组第一次线上交流，也进行了自我介绍，我当时没准备，也有点紧张，只是简要说了自己的名字，自己对莲花的喜好和联想期望，没有提及自己的具体价值点，显然是没有给他人留下什么深刻印象。\u003c/p>\u003cp>【反思】\u003c/p>\u003cp> 我反思这次线上活动的自我介绍，一是自己内心没有放开，没想要多说自己具体的事情；二是自己当时也在套用练习教练指导我们的介绍模板，有种完成作业的思维，没有更多去思考如何表达更利于连接他人，给他人提供有价值的帮助。同时，我以前很少需要用来推广的自我介绍，没有深入挖掘自己的价值点的准备，这也促使我对自我价值认知进行更多思考。\u003c/p>\u003cp>\u003cu>目标：\u003c/u>\u003cbr>3月底之前，完成一个适合自己当前的“我是值得”自我介绍，分享到学习型社群。\u003c/p>\u003cp>\u003cu>行动计划：\u003c/u>\u003c/p>\u003cp>1、我先按照“我是值得”法则来完善自我介绍：\u003c/p>\u003cp>A、【我是谁】\u003c/p>\u003cp>我是吴乐，来自成都，我用三个标签介绍自己：\u003c/p>\u003cp>1）二宝妈：我有一个14岁女儿、一个6岁儿子。\u003c/p>\u003cp>2）双语阅读指导师：陪伴6岁孩子坚持6年亲子共读几千本中英文图书。\u003c/p>\u003cp>3）终身学习践行者：面对未来的不确定和更多的可能性，我坚定践行，享受“以学为乐，以行促知”给我带来的丰盈与从容。\u003c/p>\u003cp>B、【我做过的成就事件】\u003c/p>\u003cp>1）在2022年我陪伴孩子一起共读了近1000本绘本书籍，享受阅读的乐趣。\u003c/p>\u003cp>2）从2022年3月，我担任某图书馆社群父母悦读趣写学院院长，带领身边十多位妈妈一起共学，陪伴成长，建立家庭阅读乐园。\u003c/p>\u003cp>3）从2021年开始，我陆续深入学习蒙台梭利在家教育指导师、积极心理学指导师、PBL教师、青少年生涯规划指导师，这些让我学到了更多更广的家庭教育知识，打开视野，提升认知。\u003c/p>\u003cp>C、【我可以提供什么价值】\u003c/p>\u003cp>1）我可以为他人提供家庭双语阅读关键指导，包括如何让父母避开阅读陷阱，如何提升孩子阅读兴趣，如何适龄选书，如何推进孩子的英文水平提高等。\u003c/p>\u003cp>2）我可以在家庭教育领域陪伴他人一起学习、交流提升。\u003c/p>\u003cp>2、3月份，在合适的社群或交流活动场合分享自我介绍。\u003c/p>\u003cp>3、达成目标后，给自己买一杯奶茶作为小奖励。\u003c/p>\u003cp>以上就是我今天晋级场的所有分享，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1679133293000,"updated_at":1680069174000,"ria":true},{"id":14624,"topic":"MTV法介绍自己","learn_goal":"","remark":"用最短的时间简单清晰地介绍自己，节约对方的时间 ","level":"TF1-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"唐钰茹","city":"广州市"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>评审员：\u003c/p>\u003cp> 你好！\u003c/p>\u003cp> 这是唐钰茹2022年11月20日过TF1-1的录音，请接收！\u003c/p>\u003cp> 大家好，我是唐钰茹，感谢大家参加今天的拆书学习，那么在开始之前，请允许我先用三个标签介绍下自己：\u003cbr> 第一个标签：迪宝/CHCH品牌广州区负责人、管理17间店铺人、货、场的运营\u003cbr> 第二个标签：语写践行者，通过每天1小时一万字的输出，倒逼自己输入，锻炼自己的表达能力\u003cbr> 第三个标签：食疗健康活法推广者，一日三餐吃适合自己体质的家常菜调理自己的身体，充满能量。\u003cbr> 总结一下：我是爱工作、爱学习、爱健康的钰茹，好的，大家已经认识我了，我们就开始今天的拆书学习吧。\u003cbr> \u003cbr> \u003c/p>\u003cp>首先我们今天的学习分为2步，第一部分我会用2分钟的时间跟大家介绍拆书帮，以便于大家知道你参加的是什么？然后第二部分我用2分钟时间介绍《MTV法介绍自己》\u003c/p>\u003cp> 1、关于拆书和拆书帮：\u003cbr> 去年开始喜欢看书，几乎每个月都会看两本书，但是有一个问题，看了书中的内容很快就忘记了，就想到之前有些朋友参加了拆书帮成为了拆书家都成为了很优秀的人，发现她们很会读书，我想学会学到致用的方法，于是便来到了拆书帮。\u003cbr> “拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习、强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。\u003cbr> 分为个人学习的拆书法和组织学习的拆书法：\u003cbr> 个人学习应用是便签法，让人读一本书就能达到参加同主题培训的效果；\u003cbr> 组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\u003cbr> 从学习者的学习效果来衡量的话， 一位拆书家创造的价值不亚于一位培训师。\u003cbr> \u003cbr> “拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵。\u003cbr> \u003c/p>\u003cp>拆书帮分舵是公益性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":18638,"quote":"\u003cp> 【拆解片段】《爆款写作课—MTV法介绍自己》\u003cbr> 【R：阅读原文片段】\u003cbr> 梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003cbr> 但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003cbr> \u003cbr> 这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003cbr> M是英文单词Me的缩写，意思是你是谁？\u003cbr> T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003cbr> V是单词Value的缩写，意思是你能提供什么价值？\u003cbr> \u003cbr> 这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003cbr> \u003cbr> 比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003cbr> 1.普通人如何做出属于自己的歌曲？\u003cbr> 2.如何成功脱单，找到自己的心灵伴侣？\u003cbr> 3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003cbr> \u003cbr> 当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003cbr> 理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003cbr> 当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003cbr> \u003c/p>","explains":"\u003cp> 【What】是什么？\u003cbr> 这个片段主要讲了MTV法介绍自己，可以让对方一目了然，知道自己是谁？能做什么？能够提供什么价值？相互坦诚，不用相互猜忌。\u003cbr> 【Why】：为什么？\u003cbr> 我们为什么要用MTV法介绍自己呢？梳理出自己的成就事件，用最短的时间，简单清晰的介绍出来，节约对方的时间。\u003cbr> 如果不用MTV法介绍自己，很难让对方记住你，很难与对方链接，最多让对方觉得很牛，发作赞叹之声可能就没有后面的链接了，会失去很多让别人了解自己的机会。\u003cbr> 【How】具体步骤\u003cbr> MTV法介绍自己，有以下三点\u003cbr> 1.在介绍自己的时候，先介绍你是谁？\u003cbr> 比如说你的名字，你的职业，让对方清晰了解你的基本信息。\u003cbr> 2.你做过什么成就事件？当你罗列出来你做过什么成就事件的时候，别人就通过你的事件了解你的能力有多强。\u003cbr> \u003cbr> 3.你能提供什么价值？当别人具体知道你是谁？你的成就是什么？接着他就会关注你能为别人提供什么价值？\u003cbr> 比如：我可以提供食在道中的食养联系方式，通过吃家常菜就可以学会调理自己身体获得健康！\u003cbr> 当别人需要的时候就会主动找到我来了解。\u003cbr> 【Where】适用场景：\u003cbr> \u003c/p>\u003cp>职场求职，商务合作，销售谈判，商务宴会，认识新朋友等情况下，都可以使用MTV法，进行介绍自己，可以让别人对你的印象深刻。\u003c/p>","interaction":"\u003cp> \u003cstrong>A1：故事：（起因、经过、结果）\u003c/strong>\u003cbr> \u003cstrong>在2022年8月上台分享我们公司研发的平衡鞋的时候。自己在做自我介绍时，没有提前做准备，非常的紧张，只是讲了我来自广州，我叫唐钰茹，讲完课之后真的是没有然后了，他们除了只知道我的名字外，对我其他方面一无所知，没有链接到朋友也没有链接到成交。\u003c/strong>\u003cbr> \u003c/p>\u003cp>A2:我的应用：\u003c/p>\u003cp> 目标：【Smart原则】\u003cbr> 我要在2022年12月31日前，在公司的新品发布会上用 MTV法介绍自己。来获得他们快速了解我，并且非常的愿意来链接与我合作，达成3单销售。\u003cbr> \u003cbr> 【行动计划】\u003cbr> 为了实现这个目标，我打算按一下步骤行动：\u003cbr> 1. 你是谁？本人来自于哪里，用三个标签介绍自己：\u003cbr> 我的名字叫唐钰茹，来自于广州，用三个标签介绍\u003cbr> 第一个标签：迪宝/CHCH品牌广州区负责人、管理17间店铺人、货、场的运营，\u003cbr> 第二个标签：语写践行者，通过每天1小时一万字的输出，倒逼自己输入，锻炼自己的表达能力，\u003cbr> 第三个标签：食疗健康活法推广者，一日三餐吃适合自己体质的家常菜调理自己的身体，充满能量。\u003cbr> \u003cbr> 2.你做过什么成就事件？\u003cbr> 1）2021年8月开始至今用语音写作的方式完成了600万字。\u003cbr> 2）2020年报名食在道中，学会用家常菜调理身体，解决身体鼻炎、甲减、眼睛干痒等亚健康的问题，现在能量满满，并收获身体健康。\u003cbr> 3）2022年学习投资理财课程，学会搭建投资理念，学会投资自己，增加收入渠道。\u003cbr> 4）在迪宝公司，工作17年，带领广州区团队业绩创新高3600万/年，单店最高500万/年。\u003cbr> \u003cbr> 3.你能提供什么价值？\u003cbr> 1）如何做到1小时1万字的输出，找我告诉你语写方法。\u003cbr> 2）可以提供食在道中平台的食养联系方式，通过吃家常菜就可以学会调理自己身体，获得健康！\u003cbr> 3）想学习投资理财课程，掌握投资理念，实现人生增值，找我可以把我们老师介绍给你。\u003cbr> 4）我们公司最新研发出来的有30余项专利的平衡鞋，足弓有三点支撑，穿着让身体达到一种平衡的状态，轻松每一步，可以缓解疲劳，促进血液循环，改善手脚冰凉，保护脊椎，使身躯挺拨，自信，让你日行万步不累脚。如果有需要来找我了解享受最低折扣。\u003cbr> \u003cbr> 奖惩：\u003c/p>\u003cp>奖励：如果在截止时间内完成目标，奖励自己一支口红！\u003c/p>\u003cp> 如果在截止时间内没有完成目标，罚自己写一份复盘。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1669000795000,"updated_at":1669013322000,"ria":true},{"id":14473,"topic":"爆款写作课","learn_goal":"","remark":"爆款写作课","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"米老鼠vera","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>\u003cstrong>请问观察家老师拿到记录表、准备表和拆页了么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请问各位小伙伴都拿到我的拆页了么？好，现在正式开始今天的晋级。\u003c/strong>\u003c/p>\u003cp>首先自我介绍一下，我叫周玲，来自成都蜀汉分舵。目前我有3个人生标签：第一个，是前上市信托资产管理公司财务经理；第二个，是一个两岁女孩的妈妈；第三个，是未来帮助他人达成有效人际关系，尤其是与自己、与家庭关系的实际促进者。\u003c/p>\u003cp>今天是我第一次参加拆书帮晋级的日子，首先给小伙伴们解释一下什么是【拆书法】，拆书的拆并不是拆散的意思，而是强调把书本里的知识转化为学习者的能力。“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。分为个人学习的拆书法和组织学习的拆书法:个人学习的应用是便签法，让人读一本书就能达到参加同主题培训的效果；组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>\u003cbr> 【拆书帮】是拆书法学习爱好者的社群，表现为各地的拆书帮分舵也叫拆书帮俱乐部。拆书帮分舵是非营利性组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":18485,"quote":"\u003cp>关于拆书帮就介绍到这里，现在步入主题，请大家花2分钟时间看下我发给大家的拆页，拆页片段来自《爆款写作课》的MTV法介绍自己。麻烦大家看完以后请在对话框打出666向我示意一下。\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>\u003cstrong>M是英文单词Me的缩写，意思是你是谁?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>T是英文单词Thing的缩写，意思是你做过什么成就事件?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>V是单词Value的缩写，意思是你能提供什么价值?\u003c/strong>\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询:\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲?\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣?\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己?\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产;读书很厉害的朋友可以帮助提高阅读速度;跑步的朋友可以解答坚持跑步过程中的疑惑;做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力(品类和标签)，说出成就事件(信任状)，说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>好，我看到大家已经看完拆页了，接下来我就分享一下我的理解和体会。\u003c/p>\u003cp>关于【WHAT】:\u003c/p>\u003cp>这个片段给我们提供了一个如何快速、准确、高效的自我介绍方法，以达到可与对方进行高效链接的目的。\u003c/p>\u003cp>\u003cbr> \u003cbr> 关于【WHY】：\u003c/p>\u003cp>我们总是会渴望结交新朋友进行思想或实物价值的交换，可能够打破第一印象进行深度链接的情况少之又少。自我介绍的重点一定是让对方觉得你的介绍跟他有关系，他才会在听完介绍以后，决定是否选择与你进行价值链接。快销时代也包含对自己的推销，若在短短1分钟内，对方只是知道你的品类标签，他根本没有余力主动挖掘你的点，合作链接也就很难产生。所以要主动出击完善MTV法介绍。\u003c/p>\u003cp>关于【HOW】：\u003c/p>\u003cp>1、M我是谁--可列举自己在当下介绍环境中的适宜标签，尽量是跟介绍对象相关的。\u003c/p>\u003cp>2、T我的成就事件--结合以上的标签，进行事实例证，事件务必可量化和可视化描述。\u003c/p>\u003cp>3 V我能提供的价值--分条罗列可以提供的价值服务或交换点，尽量具体化、细化到某个具体的行动事件上。\u003c/p>\u003cp> 关于【WHERE】：\u003c/p>\u003cp>这个方法在各种比较正式的介绍场合都挺适用，大家都带有明确合作链接目的的见面。但在非工作类的非正式化场合，比如熟悉的朋友聚会，这样的介绍反而让人觉得推销性质太强;朋友的婚礼、生日宴这种有明确的一个主角的场合，不能越俎代庖太彰显自己。\u003cbr> \u003cbr> \u003cbr> \u003c/p>","interaction":"\u003cp>看完拆页的内容，我立即联想到发生在我身上的一个经历（故事）：\u003cbr> 去年圣诞节，我们组织了一次行业的线下主题交流会，目的是帮助大家认识并链接资源，推动跨界合作。我作为主办方之一比较早的到现场去接待陆续到达的嘉宾，我以为大家知道我们公司是做什么的、我是谁就应该够了，所以每一个自我介绍都是“您好，我是xxx，xx公司花生活团队的合伙人”。事实上很少有人找我聊合作的事，即使找我聊天的时候也略显得有些不知所语。\u003cbr> \u003c/p>\u003cp>\u003cem>【反思】\u003c/em>\u003c/p>\u003cp>如果我可以在自我介绍的时候直接简明扼要的向对方表示我可以提供的价值，也许可以获得更多的价值链接，接到更多的合作意向，也让大家对我的价值有更深刻的印象。\u003c/p>\u003cp>计划在未来一周内，重新参加一次圈子的线下交流会，并且在聚会上用以下MTV自我介绍法，链接到1个深度圈友/客户，并且这个圈友/客户是主动向我寻找信息链接的。\u003c/p>\u003cp>我将在聚会上主动寻找比较陌生的朋友，去打招呼主动做自我介绍：\u003c/p>\u003cp>1、第一个是M，介绍我的名字、职务。\u003c/p>\u003cp>2、第二个是T，说出我的成就事件—比如描述自己带领公司做出的业绩，还有自己的一些相关爱好，并且是跟业务相关的技能体现。比如我带领的被肯定的设计作品。\u003c/p>\u003cp>3、第三个是v，即我能提供的价值--直接点明我可以提供的服务:xxx咨询;xx设计服务等。\u003c/p>\u003cp>以上信息连贯起来的话，就可以是：\u003c/p>\u003cp>您好，我是幽幽，XX公司花生活团队的合伙人。\u003c/p>\u003cp>我很喜欢花儿和植物软装设计，这都是让我们生活更加富有氧气和生命力的好伙伴，我们的花艺和宴会布置让在网上被很多顾客称赞。我们也做过很多像GUCCI、奥利奥这样大品牌的商业美陈项目，甚至2019年成都中日韩三国首脑峰会的宴会厅也是交由我们设计和完成的。\u003c/p>\u003cp>如果有兴趣，我可以向您提供3个方面的服务：第一个方面是个性花束设计、主题宴会流程安排和场景花艺布置方案、花艺游学；第二个方面是店铺商业美陈设计和交付，第三个方面是家居或店铺的植物软装设计和项目实地交付。\u003c/p>\u003cp>期待和您可以有更深入的相互了解。\u003c/p>\u003cp>\u003cu>以上就是我今天晋级场的所有分享，谢谢大家。\u003c/u>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1667234655000,"updated_at":1667623997000,"ria":true},{"id":14189,"topic":"MTV法介绍自己","learn_goal":"","remark":"从选题到结尾一句话，作者一步一步地拆解成功案例并提炼经典观点和方法，手把手教你打造10W 爆文。\n推荐看完这本书，你将提笔打造10万加，靠写作挣得100万加 。","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"孙浩雄","city":"兰州市"},"club":{"name":"兰州金城关分舵","city":"兰州"},"prologue":"\u003cp>\u003cstrong>请问观察家老师拿到记录表、准备表和拆页了么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请问各位小伙伴都看到我的拆页了么（我发到聊天区了）？好，现在正式开始今天的晋级。\u003c/strong>\u003c/p>\u003cp>自我介绍：大家好，我是孙浩雄，三个数字来简单介绍自己120\u003c/p>\u003cp>【1】代表，我的职业是一名医药从事行业，从而实现终身成长学习人\u003c/p>\u003cp>【2】代表我有两个热爱\u003c/p>\u003cp>1、户外运动。比如，用时3天环湖骑行360公里；用时5天沙漠徒步。    \u003c/p>\u003cp>2、极限挑战。比如，2017年在338米澳门塔蹦极。每一次经历会带来很多收获和成长。\u003c/p>\u003cp>【0】代表，我有一个初心，热爱公益，帮助他人。曾在疫情间报名高风险核酸及秩序志愿者。\u003c/p>\u003cp>【分组】由于今天有讨论环节，我们根据参与者的多与少进行分组。。。。由于人员不多，我们大家就自成一组进行讨论。\u003c/p>\u003cp>今天给大家分享的拆页选自《爆款写作课》，作者；弗兰克\u003c/p>\u003cp>\u003cstrong>Feature：特征 \u003c/strong>弗兰克，曾为世界500强外企职业经理人，2015年33岁起从0开始写作，2017年做自媒体收入100万，主张会说话就会写作，普通人只要遵循技巧，也能写出10W+，介绍到这里大家是不是很有兴趣想了解主题，接下来开始介绍本书；\u003c/p>\u003cp>主要讲了三种套路，吸引-打动-说服，只要按照作者方法即可0基础写出爆款文章\u003c/p>\u003cp>\u003cstrong>Advantage：优势 \u003c/strong>这是一本非常畅销的书，被知名作者剽悍一只猫老师极力推荐过，还荣登CCTV2的《第一时间》栏目受主持人高度赞誉。与同类书籍相比较，这本书是讲述实用方法和技巧，如果你想在短时间里成为一名写作10万+爆文，那么本书就是你很好的选择。\u003c/p>\u003cp>\u003cstrong>Benefit：价值 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>今天的拆页是\u003c/strong>自我介绍里一种非常好用的MTV自我介绍法，学习完，你能掌握三个步骤，让你轻松应对职场、生活中不知道如何做自我介绍的窘境。 \u003c/p>","ratings_count":2,"texts":[{"id":18202,"quote":"\u003cp>\u003cstrong>下面请大家花2分钟的时间阅读拆页，读完后请举手示意\u003c/strong>\u003c/p>\u003cp> MTV法介绍自己P64-65  \u003c/p>\u003cp>出自,《爆款写作课》弗兰克\u003c/p>\u003cp>家庭，工作，恋爱时都缺少不了开场的自我介绍。\u003c/p>\u003cp>而自我介绍能简单清晰讲解，让对方觉得你很牛，并发哇，之后就没有然后。这里我要向你介绍一个自我介绍工具，MTV法则，\u003c/p>\u003cp>这个方法可以让我们在工作，家庭，恋爱更有优势，避免工作失去机会，家庭沟通顺畅。\u003c/p>\u003cp>这个方法具体工具是；M me缩写 你是谁？\u003c/p>\u003cp> T Thing缩写 你做过什么成就事情？\u003c/p>\u003cp> V value 缩写 你能提出什么价值？\u003c/p>\u003cp>这样，让对方一目了然，更知道你是谁？能做什么，提出价值，相互坦诚，不用互相猜忌从而抓住机会。\u003c/p>","explains":"\u003cp>\u003cstrong>好，我看到大家已经看完拆页了。接下来，我分享一下自己的理解和体会。\u003c/strong>\u003c/p>\u003cp>【WHAT】；本片段中阐述了一个自我介绍的法则-MTV很清晰指导你是谁？你做过什么事?能提供什么价值？\u003c/p>\u003cp>【WHY】这个方法可以让我们自我介绍时，很多人应用传统介绍方法，未起很好效果，，利用MTV介绍自己时避免让自己失去机会总之很快记住你\u003c/p>\u003cp>【HOW】；MTV介绍自己关键步骤；\u003c/p>\u003cp>1、M(ME)   这个英文单位是“我”的意思，也就是要介绍我的特征，叫啥名谁，从事什么工作等？例如：我叫李大明，刚从某211大学毕业，今年23岁，从事于互动网行业。\u003c/p>\u003cp>2、T(Thing）  这个英文单位是“事情”的意思，也就是要讲述我做了哪些大多数人没有做到的一些牛逼的事，说一件或二件就可以。例如：我在大学里参加华北区校园舞蹈大赛获得冠军。\u003c/p>\u003cp>3、V（value） 这个英文单位是“价值”的意思，也就是要讲述我身上有哪些价值点，是对在座的人有帮助、有吸引。例如：我对无人机编程技术非常在行，曾获国家相关科技奖。同时，我也擅长户外攀岩运动，欢迎对这些有兴趣的人加我微信，我们共同探讨、精进。\u003c/p>\u003cp>【WHERE】\u003c/p>\u003cp>这个方法适应用任何社交场场景（线上线下）。\u003c/p>\u003cp>为了方便大家的运用，我再分享一个我自己用这个方法进行面试管理岗位时的例子。\u003c/p>\u003cp>时间；2022.1月 场景；面试  地点；写字楼  人物；应聘厂家\u003c/p>\u003cp>面试官好，我叫孙浩雄，兰州人，目前28岁，（这是M）因为喜欢贵公司文化，很开心我获得面试机会。\u003c/p>\u003cp>我的工作经历主要有，1、医药启蒙经历，2018-2020年。2、工作转型期，2020-2021年在外资企业工作。3、2021-2022年加入贵公司成为了基层员工。\u003c/p>\u003cp>目前我已有4年的医药销售的工作经验，在职期间促进该区域业绩一直在增长，去年任务130万，实际达成220万；\u003c/p>\u003cp>同时，我热爱演讲，曾代表西北区域参加全国PPT演讲获得第一名（这是T）；自己也是团队中合规官员，擅长做表格分析，公司领导每月都请我当讲师教同事应用函数分析技能提升工作效率。能够融入团队，与小伙伴的关系很友好（这是V），希望通过我的努力能让我们的公司更加美好。\u003c/p>","interaction":"\u003cp>（拆书家提问设计）\u003c/p>\u003cp>刚刚，我们学习了拆页的知识，请大家回忆一下，你有没有类似的关于自我介绍的经历？\u003c/p>\u003cp>这里我强调一下：\u003c/p>\u003cp>目前，大家是静音状态。\u003c/p>\u003cp>1、如果今天的学习者可以自告奋勇，请开麦分享，给你1分钟。\u003c/p>\u003cp>2、不方便的开麦小伙伴，也可以把自己的分享扣在聊天区。\u003c/p>\u003cp>3、没有的话我就随机抽取幸运2位伙伴来分享。\u003c/p>\u003cp>我将给幸运伙伴各用1分钟的时间分享。\u003c/p>\u003cp>好，我给大家30秒思考时间....\u003c/p>\u003cp>思考时间到，下面我们请小伙伴进行分享，大家欢迎。\u003c/p>\u003cp>\u003cstrong>（学习者案例记录）\u003c/strong>学习者经验分享\u003c/p>\u003cp>案例1：时间：去年年底，分享者正好公司策划比较忙，正巧准备另一家公司进行面试，在面试中自我介绍的环节，面试官提问：简单的自我介绍，分享者回忆：“过程走了许多弯路”，首先，被面试官提问，想到哪说到哪，后面导致没有逻辑，语无伦次，接下来分享者开始写稿子，背稿子，这下有一定的层次架构，但很可惜那时没有听过你的课，听过我的课可能会更好一点，分享结束。\u003c/p>\u003cp>案例2：学习者经常出去上课，都是在课前需要一个自我介绍环节，但是以前的自我介绍比较传统，可能就把自己的职称，资历简单跟大家介绍一下，结束。没有今天介绍的这么多内容，学习者今天听完以后，会觉得这些内容都是平常有过的环节，如果应用今天所学内容会更丰富。分享结束。\u003c/p>\u003cp> \u003cstrong>（拆书家提问设计）\u003c/strong>\u003c/p>\u003cp>好，非常感谢这位小伙伴的分享。接下来，我们就规划一下，在未来的一个月内，怎样运用今天学习的MTV方法做自我介绍，在什么场景？什么地方？通过使用MTV法后想达到目的/目标？\u003c/p>\u003cp>注意这个目标不是喊口号，而是具体的可实现的目标，也就是可衡量或可观察可达到的目标\u003c/p>\u003cp>我会给大家2分钟的时间写出你的应用规划，你可以写在一张纸上也可以发到聊天区，注意要符合上述要求。\u003c/p>\u003cp>不会写的小伙伴，可以参考下这种格式：\u003c/p>\u003cp>今天学习了“MTV”这个知识点，\u003c/p>\u003cp>我想在（ ）【时间】，在（ ）时【场景】，应用今天的知识，第一步M（ ），第二步T（ ） ，第三步V（ ），建立自己的自我介绍模版，下次遇到类似的场景就可以直接拿出来用。\u003c/p>\u003cp>2分钟时间到了，我请一个小伙伴念一下他写的A2。\u003c/p>\u003cp>不方便也可以打到聊天框。\u003c/p>\u003cp>\u003cstrong>由于时间原因，没写完的小伙伴可以等会结束后接续再写。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（学习者案例记录）：\u003c/strong>\u003c/p>\u003cp>学习者准备在今年寒假到酒店面试的时候运用，我是游芳，是旅游管理毕业，对酒店这块比较熟悉，之前在成都蓝海酒店有过实习，有一定的对客服务工作经验，带过两个徒弟，在文笔方面也不错，曾给两位领班写过季度分享，也得到了优秀实习生的称号。如果有幸能够进入到贵公司，我也会虚心学习，为公司做出价值，贡献。\u003c/p>\u003cp>【总结】以上就是我今天分享的拆页MTV自我介绍，该方法每个人都可以实际应用到工作与生活当中。\u003c/p>\u003cp>我的TF1-2晋级就到这里，感谢大家的参与。\u003c/p>\u003cp>谢谢观察家，谢谢师父，请您们给予指正。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1663430324000,"updated_at":1665150312000,"ria":true},{"id":12952,"topic":"\"MTV公式\"自我介绍，更好的展现自己。","learn_goal":"","remark":"作者是弗兰克曾为世界五百强外企职业经理人，作者详细拆解了爆文的构成元素，手把手教你从选题立意牢牢抓住读者眼球，循序渐进打动和说服读者，最终将文字变现。","level":"TF2-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"解毒心肺","city":"廊坊市"},"club":{"name":"燕郊星火分舵","city":"廊坊"},"prologue":"\u003cp>【技能点】学习目标包含了学习者可被观察到／被测量到的行为或动作。\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，大家会用MTV法则进行自我介绍，要别人都更容易记住我们，和我们产生更深入的链接，帮助我们抓住机会展示自己。 \u003c/p>\u003cp>【开场】个人介绍和图书介绍\u003c/p>\u003cp>大家好，我是解毒。用三个标签介绍下自己：1.HR小姐姐。2.8岁孩子的宝妈。3.家庭教育指导师。 \u003c/p>\u003cp>在拆书之前，我先给大家分一下组。左手边小伙伴一组，右手边小伙伴一组。\u003c/p>\u003cp>通过今天的学习我们要能够用“MTV公式”自我介绍，更好的展现自己\u003c/p>\u003cp>【技能点】学习目标包含了学习者可被观察到／被测量到的行为或动作。\u003c/p>\u003cp>【F】特征：《爆款写作课》 作者弗兰克曾为世界500强外企职业经理人，作者详细拆解了爆文的构成元素，手把手教你从选题立意牢牢抓住读者眼球，循序渐进打动和说服读者，最终将文字变现。\u003c/p>\u003cp>【A】优势：与同类型的书相比本书独创了新媒体写作3步法——吸引、打动、说服。作者主张会说话就会写作，普通人只要遵循技巧，也能写出10W+。用简单的方法，让你成为新媒体写作高手。\u003c/p>\u003cp>【B】利益：\u003c/p>\u003cp> B1： 如果你没有写作的基础也想从事新媒体写作，想做自媒体收入百万，想通过故事、细节、案例和数据，去吸引读者的眼球、打动人心和理性说服，最终让用户行动。那你可以读读这本书，他很适合从0开始写作的你。 \u003c/p>\u003cp> B2：今天拆的这个片段，是关于如何介绍自己，如果你之前不太会介绍自己，你想要大家都记住你，更好的展现自己，要别人和你建立更深一步的链接，那你今天是来对了。\u003c/p>","ratings_count":1,"texts":[{"id":16933,"quote":"\u003cp>下面我给大家发一篇这本书的一张拆页，请大家仔细阅读，阅读完毕之后，请举手示意我。片段很短，但是你琢磨一下。时间为1分钟。\u003c/p>\u003cp>\u003cstrong>【技能点】【R】所选拆页，包括how的内容；且总内容未超过2页图书内页\u003c/strong>\u003c/p>\u003cp>梳理出自己的成就事件，用最短的时间简单清晰地介绍出来，节约对方的时间。\u003c/p>\u003cp>但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。\u003c/p>\u003cp>这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp>M是英文单词Me的缩写，意思是你是谁？\u003c/p>\u003cp>T是英文单词Thing的缩写，意思是你做过什么成就事件？\u003c/p>\u003cp>V是单词Value的缩写，意思是你能提供什么价值？\u003c/p>\u003cp>这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。\u003c/p>\u003cp>比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：\u003c/p>\u003cp>1.普通人如何做出属于自己的歌曲？\u003c/p>\u003cp>2.如何成功脱单，找到自己的心灵伴侣？\u003c/p>\u003cp>3.个人品牌时代，如何借鉴明星包装经验推广自己？\u003c/p>\u003cp>当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。\u003c/p>\u003cp>理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。\u003c/p>\u003cp>当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp>时间到了，大家都看完了吧！好，下面我来和大家分享一下我对这段话的理解。\u003c/p>\u003cp>【I：拆书家讲解引导】\u003c/p>\u003cp>（what）\u003c/p>\u003cp> 作者向我们介绍了一个自我介绍的工具，MTV法则。要我们在自我介绍中说出自己是谁。自己做过哪些成功的事？这些事情提供了什么样的价值？这样大家就可以找到相互协助支持的点。能真正起到自我介绍的作用。 \u003c/p>\u003cp>（why）(不这么做的坏处)： \u003c/p>\u003cp>常规自我介绍一般都是说：“大家好，我是某某某，今年XX岁，来自XXX地方，主要做XXX工作的。这样的介绍很普通不能给人留下深刻的印象，也不能更好的体现你的价值，无法和别人产生深入的链接。\u003c/p>\u003cp>举例：\u003c/p>\u003cp>每次去面试自我介绍的时候，我都会和面试官说，“领导你好，我叫黎成昕，今年xx岁，来自青海，06年来北京，第一份工作是做记忆力开发的培训师，之后做过猎头，做过招聘经理，员工培训和面试官培训，我来应聘贵公司的xx职位，我觉得自己的能力可以胜任。”\u003c/p>\u003cp>这样的介绍太平淡了，并不能体现出我的实力。\u003c/p>\u003cp>（how）\u003c/p>\u003cp>①M我：我是谁？\u003c/p>\u003cp>②T讲事件：我做了什么？\u003c/p>\u003cp>③V显价值：我能提供什么价值？\u003c/p>\u003cp>学完今天的这个方法，整理一下思路，下一次面试我会这介绍自己：\u003c/p>\u003cp>M（我）:\u003c/p>\u003cp>领导好，我叫黎成昕来面试贵公司的培训教师。\u003c/p>\u003cp>T（讲事件）： \u003c/p>\u003cp> 我有三年培训教师的经验，做的是记忆力提高的培训。我曾经通过主题阅读、知识点重构、建立模型的方式制作出了新的课程体系，并把它分享给我的同事们。\u003c/p>\u003cp>毕业入职三个月就生为培训部主任。\u003c/p>\u003cp>V（显价值）：\u003c/p>\u003cp> ①我有研发新课件的能力，用我之前的方法我可以不断的给公司持续开发出更多的新课件。\u003c/p>\u003cp> ②我可以培训讲师。\u003c/p>\u003cp> ③我很擅长找目前课程里的问题，进行问题优化，要公司的课程，不断的迭代，更加接近完美。\u003c/p>\u003cp> ④我还可以给公司同事及家属孩子提供记忆力的培训。\u003c/p>\u003cp> 希望领导能够给我一个表现的机会，我定不负所望。\u003c/p>\u003cp> 这样可以更好的展现自己，赢得更多的机会。\u003c/p>\u003cp>【预防异议】：听完后是不是觉得太麻烦了，简单的一句话就够了，还要说我都做过什么？我能提供什么价值？是不是太啰嗦了？太浪费时间？\u003c/p>\u003cp>第一，自我介绍是向别人展示自己的一个重要手段。介绍的质量直接关系到我们是不是可以顺利和别人交往，在工作学习中是不是可以相互支持、信任。我们在介绍中加入了自己做过的事，要别人更好的了解了我们之前的经验，显价值可以要别人了解我们能够提供给别人什么，这样别人有机会的时候可以想到我们，或者给我们引荐。\u003c/p>\u003cp>第二，自我介绍也代表了我们对自己的认知，所以认真的梳理自我介绍也是在梳理自我意识。 \u003c/p>\u003cp>【好处】：通过这样的方法来介绍自己，要我们更好的展现自己，赢得更多的机会。 \u003c/p>\u003cp>（where）面试，争取一份工作；谈判，争取合作机会；演讲，要别人确定来听你演讲的价值；参加聚会沙龙，拓展自己的人脉圈；自我复盘，梳理自我意识等。\u003c/p>\u003cp>不合适的场景：时间受限，大家都很匆忙的时候，就不需要展开来讲了。\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>【技能点】【A2】【分步催化应用】（4分钟）\u003c/p>\u003cp>\u003cstrong>分步催化1\u003c/strong>：大家设想一下，在未来的一周或一个月内，你在哪些场合下需要做自我介绍，比如：即将要面试一份新的工作，要讲一堂课，要会见一个客户，认识一个新的朋友，加入一个社群------请大家设想一下未来应用的具体自我介绍场景。我强调一下哈只需要考虑场景哦。\u003c/p>\u003cp>大家先思考2分钟，然后我们有请一位小伙伴来用1分钟时间分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>（海昱）我之后要开一个算法的分享的课程，在开课前会给来听课的小伙伴进行自我介绍。\u003c/p>\u003cp>\u003cstrong>分步催化2：\u003c/strong>（5分钟）\u003c/p>\u003cp>请大家在刚刚想象到的场景中，利用今天的“MTV公式”说出你的具体步骤，以便将来的生活中加以应用。\u003c/p>\u003cp>请大家在小组内讨论并分享你自我介绍具体的内容。限时3分钟， \u003c/p>\u003cp>学习者案例记录（逐字稿）\u003c/p>\u003cp>3分钟后，哪位小伙伴愿意和我们一起分享一下你的应用。 \u003c/p>\u003cp>时间到，请这位小伙伴分享一下他的案例。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>①M我：我是海昱。\u003c/p>\u003cp>②T讲事件：我之前自己坚持系统学习算法的理论，刷题做练习。\u003c/p>\u003cp>③V显价值：对有同样需求的小伙伴我可以分享给大家好的资料，学习的方法、经验，帮助大家系统高效的掌握这些知识，对大家的个人发展有帮助，现在很多企业都需要这样的人。\u003c/p>\u003cp>很好海昱的自我介绍更好的展现了自己，赢得更多和别人链接的机会。 \u003c/p>\u003cp>总结：非常感谢小伙伴的分享。\u003c/p>\u003cp>希望大家在生活中都能用“MTV公式”更好的展现了自己，赢得更多和别人链接的机会。我今天的拆书到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1642341424000,"updated_at":1642580123000,"ria":true},{"id":11577,"topic":"TF1-1过级","learn_goal":"","remark":"TF1-1","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"依哲","city":"洛阳市"},"club":{"name":"昆明春城分舵","city":"昆明"},"prologue":"\u003cp>大家好，我是依哲，很高兴参加本次拆书训练，我的三个标签:\u003c/p>\u003cp>1.优势教养推广者:用闪光点打卡的活动，帮助50个家庭发现孩子的优点；\u003c/p>\u003cp>2.家庭教育传播者:学习家庭教育以来，进行30多场公益讲座，并成为幸福家河南公益讲师团团长；\u003c/p>\u003cp>3.积极学习践行者:在自我探索、发掘积极学习动力、主动突破自我的路上不断前行。\u003c/p>\u003cp>期待在拆书学习的路上互相促进，共同成长。\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>在开始内容之前先介绍下什么是“拆书帮”。\u003c/p>\u003cp>首先，我是怎样跟拆书帮搭上线的？\u003c/p>\u003cp>今年年初发现自己的阅读量不够、阅读速度、理解能力也需要提高，就去寻找高效阅读的方法，参加了一个7天的训练营，感觉所学的并非我想要的，这时，在一个社群里，看到了岳忠婧的群昵称写着拆书法，就主动跟她联结了一下，由此知道了拆书帮，之后又听了她的一个关于拆书法的分享，就对拆书法有了更深的兴趣。\u003c/p>\u003cp>那么，什么是神奇的拆书法？\u003c/p>\u003cp>简单来说，就是把书本知识拆为自己的能力，帮助自己解决切身问题，不断提升自我能量的一种读书方法，方法就是在理解原文的基础上，关联自己过去的经验进行反思，并制定目标和行动用于自己今后的生活。彻底解决成人阅读中常见的“没时间看书”“看不懂记不住”“家里很多看了半截的书心存愧疚”等问题，让书籍真正发挥价值，实现传播知识、启迪智慧的作用。拆书法可分为供个人学习的“便签学习法”和供组织学习的“RIA现场学习”。\u003c/p>\u003cp>最后，来说说我们的组织——拆书帮\u003c/p>\u003cp>拆书帮是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书帮俱乐部）。拆书帮分舵是公益性的青年自组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>也就是缘于以上的介绍，让我深深爱上了拆书帮，并决心努力植舵，帮助更多的人创造学习的价值。\u003c/p>","ratings_count":1,"texts":[{"id":15504,"quote":"\u003cp>下面进入到今天分享的主体内容部分。\u003c/p>\u003cp>【主题】：MTV法介绍自己 \u003c/p>\u003cp>【片段来源】：《爆款写作课》 1.3（《微信读书》版78-81页）\u003c/p>\u003cp> 做自我介绍，其实就是一个做减法的过程，在过去的经历中，找到最亮点的成就事件，找到关键数据做支撑，然后尝试和对方连接。\u003c/p>\u003cp> 用MTV 3步法介绍自己\u003c/p>\u003cp> 梳理出自己的\u003cstrong>成就事件\u003c/strong>，用最短的时间\u003cstrong>简单清晰\u003c/strong>地介绍出来，节约对方的时间。但是，这并不一定能和对方连接，最多让对方觉得很牛，发出“哇”之后，可能就没有然后了。这里我要向你介绍一个做自我介绍的工具，MTV法则。\u003c/p>\u003cp> M是英文单词Me的缩写，意思是\u003cstrong>你是谁\u003c/strong>？T是英文单词Thing的缩写，意思是你做过什么\u003cstrong>成就事件\u003c/strong>？V是单词Value的缩写，意思是你能\u003cstrong>提供什么价值\u003c/strong>？\u003c/p>\u003cp> 这样，是让对方一目了然知道自己是谁、能做什么、能够提供什么价值，相互坦诚，不用相互猜忌。比如，一开始的制片人姐姐，她自我介绍的最后说，她可以提供以下几个话题的一对一咨询：1.普通人如何做出属于自己的歌曲？2.如何成功脱单，找到自己的心灵伴侣？3.个人品牌时代，如何借鉴明星包装经验推广自己？当她陈列一个一个具体的价值点的时候，大家就非常清楚，什么事情可以找到她协助和支持。理财的朋友可以协助配置家庭资产；读书很厉害的朋友可以帮助提高阅读速度；跑步的朋友可以解答坚持跑步过程中的疑惑；做演讲的朋友可以提升公众演讲能力。当我们在自我介绍中说出能力（品类和标签），说出成就事件（信任状），说出给对方提供的价值，那么对方就会连接你，选择你这个品牌。\u003c/p>","explains":"\u003cp> 【what】一种简单清晰却能让对方记忆深刻的自我介绍的方法，MTV介绍法，通过我是谁、我的高光时刻、我能提供的价值三个方面介绍，让对方对你有全面的认识，清楚你的技能特长、优势价值。\u003c/p>\u003cp> 【why】这样做的好处：\u003c/p>\u003cp> 1、当你采用MTV法去推介自己之前，会对自己的人生进行一个回顾，去思考我们的高光时刻、去发现我们的优势所在，去探寻我们能给他人带去的价值，这个过程本身就能增加我们的自信心和成就感，在我们不断地介绍中，这种感觉还将得到加深和巩固；\u003c/p>\u003cp> 2、简单的传统自我介绍，不能给人留下深刻印象；MTV法则可以使人秒懂你是谁、你有多厉害、你能提供什么，让你在他人眼中形成清晰的个人品牌；\u003c/p>\u003cp> 3、社交的范围在扩大、频率在增加，你主动表明自己能提供的价值，可以给那些需要的人主动联结你的机会，增加你成交的可能性。\u003c/p>\u003cp> 不这样做的坏处：\u003c/p>\u003cp> 1、失去“第一印象”的深刻记忆，让你没入芸芸众生，错失脱颖而出的机会；\u003c/p>\u003cp> 2、没能抓到主动推销的机会进行自我展示，之后就需要更大的投入去寻找目标受众，而没能让目标主动来找你。\u003c/p>\u003cp> 【how】具体做法我们按照M、T、V的顺序来进行即可\u003c/p>\u003cp> 第一步M：说明自己是谁，包括名字、身份、标签等；\u003c/p>\u003cp> 第二步T：说出自己高光时刻，包括做过的成就事件，可以是对你而言的自我突破（让他人看到你的努力）、让你感到有成就感的事件（让他感受你的能力），也可以是对受众来讲有挑战的事件（让他人清楚你的厉害）。\u003c/p>\u003cp> 第三步V：列出你可以带给别人的价值点，即你能帮别人做什么。 要尽量具体，这样有需要的人更能主动联结。\u003c/p>\u003cp> 比如：当你说你可以提供沟通技巧；就不如你说：如何更好地赞美他人、如何有效说服别人、怎样让对方更好地感受到我们的感激、女朋友生气时我们如何应对等等，这样会显得你更专业、更可信，也更能符合受众需要。\u003c/p>\u003cp> 【where】MTV法则适用于你新进入的一个场域，向初次相识的人或虽然认识过去并不了解的人介绍自己时可以使用。线上社群、线下沙龙、新人入职、跨部门协作、商务社交等等场合均可。\u003c/p>\u003cp> 甚至：一些熟识的朋友再次加深认识也可，你可以推介自己一些他意想不到的个人价值，比如向你的老同学们介绍自己，让他们知道你在工作上有多么优秀；增加个人自信和沟通能力的课程也可采用。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】（激活过去经验） 2分钟 \u003c/strong>\u003c/p>\u003cp> 3月份，刚加入一个新的社群，群主邀请大家进行自我介绍，格式要求是在一个叫“群勾搭”的小程序里，填写个人内容，包括[昵称]、[坐标]、[一句话简介]、[擅长领域]、[高光时刻]、[想要勾搭]等内容，我第一次看到这个邀请，还挺排斥呢，纠结一会还是按要求进行了填写。在编辑内容时，发现“一句话简介”还有字数限制50字以内，“想要勾搭”需要填你想链接的人群，也就是你的目标受众。写完后，感觉还挺好玩。\u003c/p>\u003cp> 没多久后，又有个新加入的社群要求自我介绍，我就把这个小程序的介绍发了过去，很快就有好几个人私信或@我，有的是对我这个小程序很感兴趣，有的是对我这个人很感兴趣，成功实现了个人推介。\u003c/p>\u003cp>在四月训练营的分享中，我也采用了这个方法介绍自己，很多拆友记住了我，还主动加了我的微信，跟更多的志同道合的伙伴发生了联结。\u003c/p>\u003cp>【反思】\u003c/p>\u003cp>在写一句话简介时，着实费了一番脑筋，怎样在50个字以内，将自己的个性、特点、优势给表达清楚，这句话还得比较优美，最好是很文艺、很金句，更能让人一眼记住。这个过程让我对自己过去的个人经历、自我价值、优势特点进行了强制的总结和回顾，很有意义；\u003c/p>\u003cp>当你勇于去亮出自己时，给自己一个机会的同时，也给了对方机会，现在就是价值交换价值，这样更有利于发现同频共振的人；\u003c/p>\u003cp>很多时候，通过自我介绍，大家就能直觉判断对方跟自己合不合拍，这样你能用MTV法清晰准确地表达自己，可以很大程度减少无效社交；\u003c/p>\u003cp>曾经在一个群解散前的告别中，通过一个女孩的视频号个人介绍，主动跟她联结，不仅交到了一个好朋友，更学习到了一种新的家庭教育方法，受益匪浅；也曾有人因为我的个人介绍主动找到我，彼此成就。\u003c/p>\u003cp>\u003cstrong>【A2】 \u003c/strong>（规划未来应用）\u003cstrong>1.5分钟 \u003c/strong>\u003c/p>\u003cp>【目标】从现在开始，在今后的场合（新入社群、线下沙龙、出去讲课）需要自我介绍时，采用MTV法去推介自己。首先在5月底前拿出个人简介精华稿。\u003c/p>\u003cp>【行动】1、将自己的个人简介再次进行深入思考和打磨，将自己的优势和价值以更清晰、更简洁、更文艺的话术进行准备，形成文字稿，熟背；\u003c/p>\u003cp>2、尝试通过视频的形式，录一段自己的介绍视频，包含自己的高光时刻的照片、自己的作品、成就证书等内容；\u003c/p>\u003cp>3、在好友面前进行演练，请她们给予点评，不断修改精进；\u003c/p>\u003cp>4、对自己推介成功的案例记录整理，加深印象、巩固成果。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1621689851000,"updated_at":1621828398000,"ria":true}]};